window.WORKBOOK={"title": "Around the World in 80 Integrals", "course": "Math 23B · Application Worksheets", "version": 1, "accessed": "2026-11-17", "sources": {"noaa": {"title": "NOAA Monterey Harbor tidal datums", "url": "https://tidesandcurrents.noaa.gov/benchmarks/9413450.html", "kind": "Published observation-derived datums", "note": "Station 9413450; epoch 1983–2001; benchmark sheet published October 12, 2011. Meters above MLLW. These are long-term reference levels, not successive tide readings or a forecast.", "headers": ["Datum", "Height above MLLW (m)"], "rows": [["MHHW", "1.626"], ["MHW", "1.412"], ["MTL", "0.873"], ["MSL", "0.862"], ["MLW", "0.333"], ["MLLW", "0.000"]]}, "aquarium": {"title": "Monterey Bay Aquarium facts and figures", "url": "https://www.montereybayaquarium.org/about-us/about-the-aquarium/newsroom/media-kits/facts-and-figures", "kind": "Published dimensions and capacities", "note": "Published exhibit dimensions and capacities, accessed November 17, 2026. They are not a survey of tank shape or a measured spatial velocity field.", "headers": ["Exhibit", "Published dimensions / capacity"], "rows": [["Open Sea", "90 ft across; 52 ft front to back; 35 ft tall; 1,200,000 US gal"], ["Kelp Forest", "28 ft tall; 343,000 US gal"], ["Sea Otters", "15 ft tall; 55,000 US gal"]]}, "imd_grid": {"title": "IMD 0.25° gridded daily rainfall for India (Pai et al., 2014)", "url": "https://mausamjournal.imd.gov.in/index.php/MAUSAM/article/view/851", "kind": "Peer-reviewed dataset description", "note": "D. S. Pai, M. Rajeevan, O. P. Sreejith, B. Mukhopadhyay and N. S. Satbha, MAUSAM 65(1), 1–18, 2014, abstract. The rainfall pattern on the 2 × 2 block of cells used in the problem is a teaching model, not a day from the dataset.", "headers": ["Quantity", "Published value"], "rows": [["Grid spacing", "0.25° latitude × 0.25° longitude"], ["Rain-gauge stations used", "6955"], ["Period covered", "1901–2010 (110 years)"]]}, "imd_terms": {"title": "IMD terminology for heavy rainfall (Hazard Atlas)", "url": "https://www.imdpune.gov.in/hazardatlas/extreme.pdf", "kind": "Official classification", "note": "India Meteorological Department, Pune, Hazard Atlas notes on extreme rainfall events, “terminologies used by the India Meteorological Department”. Amounts are 24-hour rainfall at a station.", "headers": ["Term", "24-hour rainfall (mm)"], "rows": [["Heavy rainfall", "64.5–115.5"], ["Very heavy rainfall", "115.6–204.4"], ["Extremely heavy rainfall", "204.5 or more"]]}, "cpc_oni": {"title": "NOAA CPC Oceanic Niño Index (ERSST.v6)", "url": "https://www.cpc.ncep.noaa.gov/products/analysis_monitoring/enso/oni/v6/", "kind": "Published climate index", "note": "NOAA Climate Prediction Center, accessed November 17, 2026. The ONI is the 3-month running mean of SST anomalies in the Niño 3.4 region; El Niño periods use a threshold of +0.5 °C met for at least five overlapping seasons. CPC now notes that the Relative ONI (RONI) is used for official monitoring. The anomaly maps in the problem are models, not observed fields.", "headers": ["Quantity", "Published value"], "rows": [["Niño 3.4 region", "5°N–5°S, 120°–170°W"], ["Warm/cold threshold", "+0.5 °C (warm) and −0.5 °C (cold)"], ["ONI, Nov–Jan 2015/16", "2.6 °C"], ["ONI, Nov–Jan 1997/98", "2.4 °C"], ["ONI, Nov–Jan 2023/24", "2.0 °C"]]}, "inah_sun": {"title": "Sarabia González, “Los túneles arqueológicos en la pirámide del Sol de Teotihuacán”", "url": "https://revistas.inah.gob.mx/index.php/arqueologia/article/download/18327/19713/39517", "kind": "Peer-reviewed archaeology journal (INAH)", "note": "Alejandro Sarabia González (Zona Arqueológica de Teotihuacán, INAH), Arqueología 61, July 2020, p. 1 (Spanish; translated). Other sources give heights from about 63 m to 75 m, partly because they measure different construction stages. The square base and smooth or stepped shapes in the problem are models.", "headers": ["Quantity", "Published value"], "rows": [["Height today", "66.00 m"], ["Base", "224.00 m"], ["Architectural levels (cuerpos)", "4"], ["Solid volume", "a little over 1,175,000 m³"]]}, "asce_gerd": {"title": "Civil Engineering (ASCE): Giant Ethiopian dam promises greater flood control", "url": "https://www.asce.org/publications-and-news/civil-engineering-source/civil-engineering-magazine/issues/magazine-issue/article/2025/07/giant-ethiopian-dam-promises-greater-flood-control-and-water-management", "kind": "Published engineering description", "note": "ASCE Civil Engineering magazine, July 2025. The article also stresses the Blue Nile’s “substantial sediment load” but gives no number; the sediment profile in the problem is assumed.", "headers": ["Quantity", "Published value"], "rows": [["Dam height and length", "145 m high, 1,780 m long"], ["Storage at full capacity", "74 billion m³"], ["Reservoir area when full", "about 1,874 km²"], ["Full supply level", "640 m above mean sea level"], ["Powerhouse capacity", "5,150 MW"]]}, "wiki_gerd": {"title": "Wikipedia: Grand Ethiopian Renaissance Dam (infobox)", "url": "https://en.wikipedia.org/wiki/Grand_Ethiopian_Renaissance_Dam", "kind": "Secondary source (encyclopedia)", "note": "Secondary, uncited infobox values, accessed November 17, 2026; used only for the depth at the dam and the reservoir length, which the ASCE article does not give.", "headers": ["Quantity", "Reported value"], "rows": [["Maximum water depth", "140 m"], ["Maximum reservoir length", "246 km"]]}, "nasa_ozone": {"title": "NASA Ozone Watch: annual records", "url": "https://ozonewatch.gsfc.nasa.gov/meteorology/annual_data.html", "kind": "Published observation-derived records", "note": "NASA Goddard Ozone Watch, accessed November 17, 2026: maximum daily ozone-hole area and minimum daily ozone for each year. NASA’s facts page defines the hole as “the region over Antarctica with total ozone of 220 Dobson Units or lower.” The circular hole and the coarse square grid in the problem are models.", "headers": ["Year", "Max hole area (million km²), date", "Min ozone (DU), date"], "rows": [["2000", "29.9, 9 Sep", "89, 29 Sep"], ["2006", "29.6, 24 Sep", "84, 8 Oct"], ["2015", "28.2, 2 Oct", "101, 4 Oct"], ["2022", "26.5, 5 Oct", "97, 1 Oct"], ["2023", "26.0, 21 Sep", "99, 3 Oct"]]}, "pilat": {"title": "Syndicat Mixte de la Grande Dune du Pilat: visitor brochure (2023)", "url": "https://ladunedupilat.com/wp-content/uploads/2023/07/Dune_Pilat_depliant_HD_EN_2023.pdf", "kind": "Published site figures", "note": "Official English brochure of the public body that manages the Grand Site de la Dune du Pilat. Figures are rounded; the height is given as about 110 m. The parabola-and-line cross-section in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Width", "600 m"], ["Length", "2,900 m"], ["Height", "about 110 m"], ["Sand", "55 million m³"], ["Movement toward the forest", "1 to 5 m per year"]]}, "khumbu": {"title": "Wikipedia: Khumbu Glacier", "url": "https://en.wikipedia.org/wiki/Khumbu_Glacier", "kind": "Secondary source (encyclopedia)", "note": "Wikipedia, accessed November 17, 2026, citing an ASTER study of supraglacial lakes in the Everest region. Only the length and elevations are published here; the tongue length, width, thickness, and shape in the problem are assumptions for a model, not survey values.", "headers": ["Quantity", "Reported value"], "rows": [["Length of the main glacier", "about 17 km"], ["Elevation of the terminus", "4,900 m"], ["Elevation of the source", "7,600 m"]]}, "turkana": {"title": "Lake Turkana Wind Power Project: Updated ESIA Summary (EIB, 2011)", "url": "https://www.eib.org/attachments/registers/53222536.pdf", "kind": "Published project summary", "note": "European Investment Bank register, Updated Environmental and Social Impact Assessment Summary, November 2011. The wind farm was completed in 2018 with the same 365 V52 turbines. The Weibull wind model and the turbine power curve in the problem are assumptions.", "headers": ["Quantity", "Published value"], "rows": [["Turbines", "365 Vestas V52, 0.850 MW each, hub height 44 m"], ["Installed capacity", "310 MW"], ["Average wind speed", "11 m/s (on-site measurements by DEWI)"], ["Estimated average production", "1,440 GWh per year"]]}, "threegorges": {"title": "Wikipedia: Three Gorges Dam (ship lift)", "url": "https://en.wikipedia.org/wiki/Three_Gorges_Dam", "kind": "Secondary source (encyclopedia)", "note": "Wikipedia, accessed November 17, 2026; the lift height is cited there to the China Three Gorges Project. The smooth-start motion in the problem is an assumption.", "headers": ["Quantity", "Reported value"], "rows": [["Ship lift basin", "120 m × 18 m × 3.5 m"], ["Vertical distance travelled", "113 m"], ["Largest ships lifted", "3,000 tons"]]}, "kspivot": {"title": "Considerations for Nozzle Package Selection for Center Pivots (K-State L908)", "url": "https://bookstore.ksre.ksu.edu/download/considerations-for-nozzle-package-selection-for-center-pivots_L908", "kind": "Published extension guidance and worked example", "note": "D. H. Rogers and M. Alam, Kansas State University Research and Extension publication L908, December 2008. The 128-acre, 650 gpm system is the publication’s worked example, not a particular farm. Treating the irrigated area as one full circle and the nozzle spacing are assumptions.", "headers": ["Quantity", "Published value"], "rows": [["Share of Kansas irrigated acreage watered by center pivots", "approximately 90 percent"], ["Worked example: irrigated area", "128 acres"], ["Worked example: system flow", "650 gpm"], ["Worked example: system irrigation capacity", "0.27 in/day"], ["Why nozzle rates rise outward", "application rate increases with distance from the pivot point as more area is covered by the nozzle"]]}, "graphene": {"title": "Scientific Background on the Nobel Prize in Physics 2010: Graphene", "url": "https://www.nobelprize.org/uploads/2018/06/advanced-physicsprize2010-1.pdf", "kind": "Published physical constants of a material", "note": "Class for Physics of the Royal Swedish Academy of Sciences, 2010. The lattice vectors used in the problem follow from the published carbon–carbon distance; the hammock is the document’s own illustration.", "headers": ["Quantity", "Published value"], "rows": [["Carbon–carbon distance", "0.142 nm"], ["Atoms per unit hexagonal cell", "2"], ["Area of the unit cell", "0.052 nm²"], ["Density", "0.77 mg/m²"], ["1 m² hammock: load it could hold", "approximately 4 kg (a cat)"]]}, "neowise": {"title": "JPL Small-Body Database and Horizons: comet C/2020 F3 (NEOWISE)", "url": "https://ssd.jpl.nasa.gov/tools/sbdb_lookup.html#/?sstr=C%2F2020%20F3", "kind": "Published orbit solution and ephemeris", "note": "NASA JPL Solar System Dynamics, orbit solution JPL#31 (epoch 2020-Jul-06), accessed November 17, 2026. Heliocentric distances are from a Horizons vector ephemeris (centre: Sun). 1 au = 149,597,870.7 km.", "headers": ["Quantity", "Published value"], "rows": [["Perihelion distance q", "0.29465 au"], ["Eccentricity e", "0.99918"], ["Time of perihelion", "JD 2459034.179 TDB (2020 July 3.68)"], ["Distance from Sun, 2020-Aug-09 00:00 TDB", "148,741,645 km"], ["Distance from Sun, 2020-Aug-10 00:00 TDB", "151,791,397 km"]]}, "boxmuller": {"title": "Box–Muller Transformation (Wolfram MathWorld)", "url": "https://mathworld.wolfram.com/Box-MullerTransformation.html", "kind": "Published method (secondary reference)", "note": "E. W. Weisstein, MathWorld, accessed November 17, 2026; secondary source for the method of G. E. P. Box and M. E. Muller, Ann. Math. Statist. 29 (1958), 610–611. No measured data are involved.", "headers": ["Item", "Published form"], "rows": [["Inputs", "two independent uniform random numbers in (0, 1)"], ["First output", "$\\sqrt{-2\\ln x_1}\\cos(2\\pi x_2)$"], ["Second output", "$\\sqrt{-2\\ln x_1}\\sin(2\\pi x_2)$"], ["Result", "two independent standard normal numbers"]]}, "snyder": {"title": "Map Projections: A Working Manual (USGS Professional Paper 1395)", "url": "https://pubs.usgs.gov/pp/1395/report.pdf", "kind": "Published projection formulas", "note": "J. P. Snyder, U.S. Geological Survey, 1987, chapter 7 (Mercator) and chapter 10 (cylindrical equal-area), spherical forms.", "headers": ["Projection", "Published formula"], "rows": [["Mercator", "$x=R(\\lambda-\\lambda_0)$, $y=R\\ln\\tan(\\pi/4+\\phi/2)$"], ["Mercator scale factor", "$h=k=\\sec\\phi$"], ["Mercator areal scale factor", "$\\sec^2\\phi$"], ["Cylindrical equal-area (standard parallel 0°)", "$x=R(\\lambda-\\lambda_0)$, $y=R\\sin\\phi$"]]}, "unareas": {"title": "UN Demographic Yearbook 2014, Table 3 (surface area)", "url": "https://unstats.un.org/unsd/Demographic/products/dyb/dyb2014/Table03.pdf", "kind": "Published national surface areas", "note": "United Nations Statistics Division. Surface area includes land and inland waters.", "headers": ["Country or area", "Surface area (km²)"], "rows": [["Greenland", "2,166,086"], ["Democratic Republic of the Congo", "2,344,858"]]}, "gatewayarch": {"title": "Gateway Arch Fact Sheet (National Park Service)", "url": "https://www.nps.gov/jeff/planyourvisit/gateway-arch-fact-sheet.htm", "kind": "Published structural dimensions", "note": "Gateway Arch National Park, U.S. National Park Service, accessed November 17, 2026. The parabolic outlines and the thickness-based density in the problem are models, not the arch’s design curve.", "headers": ["Quantity", "Published value"], "rows": [["Outer width (outside north leg to outside south leg)", "630 ft (192 m)"], ["Maximum height", "630 ft (192 m)"], ["Shape of arch section", "equilateral triangle"], ["Dimension of arch at base", "54 ft (16.46 m)"], ["Dimension of arch at top", "17 ft (5.18 m)"], ["Concrete between skins", "to 300 ft (91 m)"]]}, "earthfacts": {"title": "NASA Earth Fact Sheet (bulk parameters)", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC, accessed November 17, 2026. The moment of inertia factor is measured from Earth’s response to the torques of the Sun and Moon; the quadratic density profile in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Mass", "5.9722 × 10²⁴ kg"], ["Volumetric mean radius", "6371.000 km"], ["Mean density", "5513 kg/m³"], ["Moment of inertia (I/MR²)", "0.3308"], ["GM", "0.39860 × 10^6 km³/s² (398,600 km³/s²)"], ["Escape velocity", "11.186 km/s"]]}, "fmiradar": {"title": "First experiences of operational use of a dual-polarisation weather radar in Finland", "url": "https://ams.confex.com/ams/35Radar/webprogram/Manuscript/Paper191344/Manuscript.pdf", "kind": "Published radar scan schedule", "note": "L. Nevvonen and E. Saltikoff (Finnish Meteorological Institute), 35th AMS Conference on Radar Meteorology, 2011, Table 1. The schedule repeats every 15 minutes. The flat-Earth, straight-beam geometry in the problem is a simplification.", "headers": ["Scan group", "Elevation angles (deg)", "Range (km)"], "rows": [["A", "0.3, 1.5, 3, 5, 9", "250"], ["B", "0.3, 2, 4", "100"], ["C", "2, 7, 11, 15, 25, 45", "100"], ["RHI", "0.0 to 60.0", "150"]]}, "walker1977": {"title": "The effects of urban lighting on the brightness of the night sky", "url": "https://articles.adsabs.harvard.edu/pdf/1977PASP...89..405W", "kind": "Published observations and empirical law", "note": "M. F. Walker (Lick Observatory, UC Santa Cruz), Publications of the Astronomical Society of the Pacific 89 (1977) 405–409, Table III, column (1). Sky brightness at 45° altitude toward Salinas, in units of the natural sky brightness. Uniformly spread lights in the problem are a model.", "headers": ["Distance from Salinas (km)", "Visual intensity", "Blue intensity"], "rows": [["8.0", "2.41", "2.36"], ["10.5", "1.91", "1.91"], ["14.2", "1.23", "1.18"], ["16.9", "0.59", "0.64"], ["18.7", "0.68", "0.68"], ["24.5", "0.27", "0.27"], ["32.2", "0.14", "0.09"], ["35.7", "0.09", "0.05"]]}, "taipeidamper": {"title": "Guinness World Records: largest tuned mass damper", "url": "https://www.guinnessworldrecords.com/world-records/774616-largest-tuned-mass-damper", "kind": "Published record entry", "note": "Guinness World Records, record dated December 31, 2004, accessed November 17, 2026. The damper is built of stacked steel plates; treating it as a solid ball of uniform steel is an assumption.", "headers": ["Quantity", "Published value"], "rows": [["Mass of the pendulum weight", "660 tonnes"], ["Hangs between floors", "87th and 92nd"], ["Building height", "508 m"], ["Maximum extension", "1.5 m"]]}, "ggbridge": {"title": "Golden Gate Bridge: design and construction statistics", "url": "https://www.goldengate.org/bridge/history-research/statistics-data/design-construction-stats/", "kind": "Published structural statistics", "note": "Golden Gate Bridge Highway and Transportation District, accessed November 17, 2026. The weight row covers both main cables plus the suspender cables and accessories.", "headers": ["Quantity", "Published value"], "rows": [["Main span (distance between towers)", "4,200 ft (1,280 m)"], ["Diameter of one main cable, with wrapping", "36 3/8 in (0.92 m)"], ["Steel wires in one main cable", "27,572"], ["Length of one main cable (anchorage to anchorage)", "7,650 ft (2,332 m)"]]}, "ggbstatics": {"title": "The Golden Gate Bridge (statics chapter), Table 3.2", "url": "https://www.goldengate.org/assets/1/6/ggb-exhibit-chapter-statistics1.pdf", "kind": "Published structural properties (textbook table)", "note": "Chapter by Thalia Anagnos in Sheppard and Tongue, Statics: Analysis and Design of Systems in Equilibrium (Wiley), hosted by the Bridge District. Its Table 3.2 cites the District and Abdel-Ghaffar and Scanlan (1985). The parabolic shape used in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Length of main span", "1280 m"], ["Maximum sag in main cable", "144 m"], ["Weight of cable per one horizontal meter", "48.7 kN/m"], ["Height of each tower", "227 m"]]}, "acc": {"title": "WHOI Polar Discovery: Antarctic circulation", "url": "https://polardiscovery.whoi.edu/antarctica/circulation-en2.html", "kind": "Published typical current speeds", "note": "Woods Hole Oceanographic Institution, Polar Discovery (2006), map caption. The companion WHOI page divediscover.whoi.edu/polar-regions/antarctic-ocean-circulation describes the current as the West Wind Drift, driven by strong westerly winds. The speed field in the problem is a model, not a measurement.", "headers": ["Quantity", "Published value"], "rows": [["Average speed of the Antarctic Circumpolar Current", "50 cm/s (1 knot)"], ["Range of speeds around Antarctica", "about 10 to 100 cm/s"]]}, "everest": {"title": "J. B. West, “Oxygenless” climbs and barometric pressure", "url": "https://publications.americanalpineclub.org/articles/12198412600", "kind": "Published field measurement", "note": "American Alpine Journal, 1984. The article reports the pressure Chris Pizzo measured on the summit of Mount Everest during the American Medical Research Expedition to Everest, October 1981, and notes it was 17 mm higher than the Standard Atmosphere predicts. 760 mm Hg is one standard atmosphere by definition.", "headers": ["Quantity", "Published value"], "rows": [["Barometric pressure on the summit, October 1981", "253 mm Hg"], ["Standard sea-level pressure (definition of 1 atm)", "760 mm Hg"]]}, "stelvio": {"title": "Südtirol tourism: Passo dello Stelvio", "url": "https://www.suedtirol.info/it/it/informazioni/mobilita/passi-in-alto-adige/passo-dello-stelvio", "kind": "Published elevations and route data", "note": "Official South Tyrol tourism site, accessed November 17, 2026. The page gives 1838 m of climbing for the 25 km bike route; the endpoint elevations below differ by 1842 m.", "headers": ["Quantity", "Published value"], "rows": [["Height of the Stelvio Pass", "2757 m"], ["Height of Prato allo Stelvio", "915 m"], ["Hairpin bends between Prato and the pass", "48"], ["Bike route length", "25 km"]]}, "earthgm": {"title": "NASA Earth Fact Sheet (gravity parameters)", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC, accessed November 17, 2026. GM is the product of the gravitational constant and Earth’s mass. The real Earth is slightly flattened and rotating; the problem uses a non-rotating sphere.", "headers": ["Quantity", "Published value"], "rows": [["GM", "0.39860 million km³/s²"], ["Volumetric mean radius", "6371.000 km"], ["Mean surface gravity", "9.820 m/s²"]]}, "lightning": {"title": "National Weather Service: How powerful is lightning?", "url": "https://www.weather.gov/safety/lightning-power", "kind": "Published typical values", "note": "NOAA National Weather Service, accessed November 17, 2026. The strike frequency is from the NWS page weather.gov/safety/lightning-myths. Real flashes vary widely; the straight, steady channel in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Typical lightning flash current", "about 30,000 A"], ["Typical lightning flash voltage", "about 300 million V"], ["Strikes on the Empire State Building", "about 23 per year on average"]]}, "earth": {"title": "NASA Earth Fact Sheet", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/earthfact.html", "kind": "Published planetary parameters", "note": "NASA NSSDC Earth Fact Sheet, accessed November 17, 2026. The volumetric mean radius is the radius of a sphere with Earth’s volume; the real Earth is slightly flattened at the poles.", "headers": ["Quantity", "Published value"], "rows": [["Volumetric mean radius", "6371.000 km"], ["Obliquity to orbit (axial tilt)", "23.44°"]]}, "alma": {"title": "ALMA Memo 574: 12 m antenna optics", "url": "https://science.nrao.edu/facilities/alma/aboutALMA/Technology/ALMA_Memo_Series/alma574/memo574.pdf", "kind": "Published antenna design parameters", "note": "Sugimoto et al. (NAOJ ALMA project office), ALMA Memo 574, 2007, Table 1. The memo states that the ACA 12 m antenna shares the optics parameters of the 12 m antennas used for ALMA. The tabulated values are for the 12 m prototype design.", "headers": ["Quantity", "Published value"], "rows": [["Primary mirror diameter", "12 m"], ["Primary focal length", "4800 mm"], ["Primary focal ratio f/D", "0.4"], ["Vertex hole diameter", "750 mm"]]}, "cooling": {"title": "Niederaussem natural-draft cooling tower", "url": "https://structurae.net/en/literature/journal-article/world-s-tallest-natural-draft-cooling-tower", "kind": "Published structural dimensions", "note": "Busch, Harte, Krätzig and Montag, Structural Engineering International 11(2), 2001, describe the 200 m tower. The 152 m base diameter and 0.24 m wall thickness come from co-author W. B. Krätzig’s summary on shellbuckling.com. The narrowest radius and exact shape in the problem are assumed.", "headers": ["Quantity", "Published value"], "rows": [["Height", "200 m"], ["Base diameter", "152 m"], ["Shell wall thickness", "about 0.24 m"]]}, "zimbabwe": {"title": "Great Zimbabwe: the Conical Tower", "url": "https://en.wikipedia.org/wiki/Great_Zimbabwe", "kind": "Published approximate dimensions (secondary source)", "note": "Wikipedia’s Great Zimbabwe article, citing P. Garlake, Great Zimbabwe (1973), p. 29, gives the dimensions below. Other descriptions differ by about a meter. The top radius used in the problem is assumed.", "headers": ["Quantity", "Reported value"], "rows": [["Height", "30 ft (about 9 m)"], ["Base diameter", "18 ft (about 5.5 m)"]]}, "iter": {"title": "ITER EDA Newsletter (IAEA), October 2000", "url": "https://www-pub.iaea.org/MTCD/Publications/PDF/Newsletters/ITER-NL-9-10.pdf", "kind": "Published design parameters", "note": "International Atomic Energy Agency, ITER EDA Newsletter Vol. 9 No. 10, lists the plasma parameters below. The real plasma cross-section is D-shaped, not circular.", "headers": ["Quantity", "Published value"], "rows": [["Plasma major radius", "6.2 m"], ["Plasma minor radius", "2.0 m"], ["Plasma volume", "837 m³"]]}, "tsi2011": {"title": "A new, lower value of total solar irradiance (Kopp and Lean, 2011)", "url": "https://espo.nasa.gov/node/30086", "kind": "Published satellite measurement (peer-reviewed)", "note": "G. Kopp and J. Lean, Geophysical Research Letters 38 (2011), doi:10.1029/2010GL045777. Abstract hosted by NASA ESPO, accessed November 17, 2026: “The most accurate value of total solar irradiance during the 2008 solar minimum period is 1360.8 $\\pm$ 0.5 W m$^{-2}$.” The irradiance varies by about 0.1% over a solar cycle.", "headers": ["Quantity", "Published value"], "rows": [["Total solar irradiance at 1 au (2008 solar minimum)", "1360.8 $\\pm$ 0.5 W/m²"]]}, "sunfacts": {"title": "NASA Sun Fact Sheet", "url": "https://nssdc.gsfc.nasa.gov/planetary/factsheet/sunfact.html", "kind": "Published solar parameters", "note": "NASA NSSDC Sun Fact Sheet, accessed November 17, 2026. The luminosity is listed as $382.8\\times10^{24}$ J/s; it is used here only as a check on the flux computation.", "headers": ["Quantity", "Published value"], "rows": [["Mean distance from Earth", "$149.6\\times10^{6}$ km"], ["Luminosity", "$382.8\\times10^{24}$ J/s"]]}, "noor1": {"title": "NREL SolarPACES: NOOR I CSP Project", "url": "https://solarpaces.nlr.gov/project/noor-i", "kind": "Published plant data", "note": "NREL concentrating solar power project database (now hosted at solarpaces.nlr.gov), accessed November 17, 2026. SENER’s NOORo I fact sheet gives the matching figures 160 MWe and “1.3 Mm2 total reflective area.”", "headers": ["Quantity", "Published value"], "rows": [["Location (lat, long)", "30.994, −6.863"], ["Turbine capacity", "160 MW"], ["Solar-field aperture area", "1,308,000 m²"], ["Collector", "SenerTrough parabolic trough"], ["Thermal storage", "3 h, molten salt"], ["Expected generation", "370 GWh/year"]]}, "sentrough": {"title": "Parabolic Trough Collector Overview (Kearney, NREL Parabolic Trough Workshop 2007)", "url": "https://webarchive.library.unt.edu/eot2008/20081106024529/http://www.nrel.gov/csp/troughnet/pdfs/2007/kearney_collector_technology.pdf", "kind": "Published collector design data (workshop slides)", "note": "D. W. Kearney, NREL Parabolic Trough Workshop, March 2007, slide 11 (SENER collector), archived copy. These are SENER’s 2007 collector dimensions; that NOOR I uses exactly this geometry is an assumption.", "headers": ["Quantity", "Published value"], "rows": [["Aperture width", "5.76 m"], ["Focal length", "1.70 m"], ["Length per collector module", "12 m"], ["Length per collector assembly", "150 m"]]}, "usgsrain": {"title": "USGS Water Science School: Precipitation and the Water Cycle", "url": "https://www.usgs.gov/water-science-school/science/precipitation-and-water-cycle", "kind": "Published typical values (secondary table)", "note": "USGS table of typical raindrop properties, which USGS credits to Lull (1959), USDA Forest Service Misc. Publication 768. Values are typical, not measurements of a particular storm.", "headers": ["Precipitation type", "Intensity", "Median drop diameter", "Fall velocity"], "rows": [["Moderate rain", "0.15 in/h (0.38 cm/h)", "1.60 mm", "18.7 ft/s (5.7 m/s)"], ["Heavy rain", "0.60 in/h (1.52 cm/h)", "2.05 mm", "22.0 ft/s (6.7 m/s)"]]}, "bocci2012": {"title": "Whether or not to run in the rain (Bocci, 2012)", "url": "https://iopscience.iop.org/article/10.1088/0143-0807/33/5/1321", "kind": "Peer-reviewed physics paper (abstract)", "note": "F. Bocci, European Journal of Physics 33 (2012) 1321. The abstract states that the best strategy depends on the shape and orientation of the moving body and on the wind. No numbers from the paper are used here.", "headers": ["Item", "Value"], "rows": [["Journal", "Eur. J. Phys. 33, 1321 (2012)"], ["Main finding", "Best strategy depends on body shape, orientation, and wind"]]}, "planck2018": {"title": "Planck 2018 results VI: Cosmological parameters", "url": "https://arxiv.org/abs/1807.06209", "kind": "Published measurement (peer-reviewed)", "note": "Planck Collaboration, Astronomy and Astrophysics 641, A6 (2020). Abstract: “Hubble constant H0 = (67.4 $\\pm$ 0.5) km/s/Mpc,” assuming the base Lambda-CDM model.", "headers": ["Quantity", "Published value"], "rows": [["Hubble constant (from the cosmic microwave background)", "67.4 $\\pm$ 0.5 km/s/Mpc"]]}, "shoes2022": {"title": "A comprehensive measurement of the local value of the Hubble constant (Riess et al., 2022)", "url": "https://arxiv.org/abs/2112.04510", "kind": "Published measurement (peer-reviewed)", "note": "A. G. Riess et al. (SH0ES team), Astrophysical Journal Letters (2022), doi:10.3847/2041-8213/ac5c5b. Abstract: “Our baseline result from the Cepheid-SN sample is H0=73.04+-1.04 km/s/Mpc.”", "headers": ["Quantity", "Published value"], "rows": [["Hubble constant (Cepheids and supernovae)", "73.04 $\\pm$ 1.04 km/s/Mpc"]]}, "pdgastro": {"title": "Particle Data Group: Astrophysical constants and parameters (2016)", "url": "https://ccwww.kek.jp/pdg/2017/reviews/rpp2016-rev-astrophysical-constants.pdf", "kind": "Published unit conversion", "note": "Review of Particle Physics 2016 (mirror at KEK). Used only for the unit conversion of H0 to inverse gigayears.", "headers": ["Quantity", "Published value"], "rows": [["Hubble rate conversion", "$100h$ km/s/Mpc $= h\\times(9.777752$ Gyr$)^{-1}$"], ["Parsec", "$3.08567758149\\times10^{16}$ m"]]}, "saharadust": {"title": "NASA: Satellite reveals how much Saharan dust feeds Amazon’s plants", "url": "https://www.nasa.gov/science-research/earth-science/nasa-satellite-reveals-how-much-saharan-dust-feeds-amazons-plants/", "kind": "Published satellite-based estimates (press release)", "note": "NASA, February 2015, describing H. Yu et al., Geophysical Research Letters (2015), doi:10.1002/2015GL063040, based on CALIPSO observations 2007–2013. Values are multi-year averages; the press release says “tons,” treated here as metric tonnes.", "headers": ["Quantity", "Published value"], "rows": [["Dust carried past the western edge of the Sahara (15°W)", "182 million tons per year"], ["Still airborne near South America’s east coast (35°W)", "132 million tons per year"], ["Falling on the Amazon basin", "27.7 million tons per year"], ["Travelling past 75°W to the Caribbean", "about 43 million tons per year"]]}, "noaastations": {"title": "NOAA CO-OPS tide station metadata", "url": "https://api.tidesandcurrents.noaa.gov/mdapi/prod/webapi/stations/8723214.json", "kind": "Published station coordinates", "note": "NOAA Center for Operational Oceanographic Products and Services metadata API, accessed November 17, 2026: stations 8723214, 2695540, and 9755371 (replace the station number in the link). The stations stand in for the three cities; a flat chart and rounded vertices are modeling choices.", "headers": ["Station", "Latitude", "Longitude"], "rows": [["Virginia Key (Miami), FL", "25.7314° N", "80.1618° W"], ["Bermuda, St. Georges Island", "32.3734° N", "64.7033° W"], ["San Juan, La Puntilla, PR", "18.4589° N", "66.1164° W"]]}, "bermuda": {"title": "NOAA Ocean Service: What is the Bermuda Triangle?", "url": "https://oceanservice.noaa.gov/facts/bermudatri.html", "kind": "Published agency statement", "note": "NOAA National Ocean Service. The vertices Miami, San Juan, and Bermuda come from Vincent Gaddis’s 1964 Argosy article, as summarized in Wikipedia’s article on the Bermuda Triangle (a secondary source), which notes that later writers used other boundaries enclosing 1.3 to 3.9 million km².", "headers": ["Item", "Published statement"], "rows": [["Location", "A region in the western part of the North Atlantic Ocean"], ["Official status", "The U.S. Board on Geographic Names keeps no official file on the area"], ["Disappearances", "No evidence that they occur there with any greater frequency than elsewhere"]]}, "orange": {"title": "The Ancient Theatre Archive: Theatre at Orange (Arausio)", "url": "https://www.whitman.edu/theatre/theatretour/Orange/Orange.home.htm", "kind": "Published dimensions (academic archive)", "note": "Thomas G. Hines, Department of Theatre, Whitman College (2009). The page gives no measurement method; other descriptions give a cavea about 104 m across and an orchestra about 27 m across. The half-ring shape is a model.", "headers": ["Quantity", "Published value"], "rows": [["Seating diameter", "103.63 m"], ["Orchestra diameter", "29.9 m"], ["Seating capacity", "5,850 / 7,300"]]}, "haiyan": {"title": "JMA position table for Typhoon Haiyan (1330)", "url": "https://www.data.jma.go.jp/typhoon/data/T1330.pdf", "kind": "Published best-track values (Regional Specialized Meteorological Center Tokyo)", "note": "Japan Meteorological Agency. Winds are 10-minute averages. JMA defines the storm-force wind area as winds of 25 m/s or more and the gale area as 15 m/s or more (jma.go.jp/jma/kishou/know/typhoon/1-3.html). Agencies that use 1-minute averages reported higher peak winds.", "headers": ["Quantity (peak, Nov. 7, 21 JST to Nov. 8, 03 JST)", "Published value"], "rows": [["Central pressure", "895 hPa"], ["Maximum 10-minute wind", "65 m/s"], ["Storm-force (25 m/s) wind radius", "150 km"], ["Gale (15 m/s) wind radius", "460 km north, 330 km south"]]}, "imoseac": {"title": "IMOS Deep Water Arrays: the East Australian Current (EAC) array", "url": "https://imos.org.au/facility/deep-water-moorings/deep-water-arrays", "kind": "Published program description (Integrated Marine Observing System, operated by CSIRO)", "note": "Integrated Marine Observing System (Australia), accessed November 18, 2026. Water depths and float clusters come from the IMOS 2015 deployment drawings, data.aodn.org.au/IMOS/DWM/Deployments/Schematic_EAC_array.pdf (drawing titles and the M4 sheet).", "headers": ["Item", "Published value"], "rows": [["Moorings in the EAC array", "6, from the continental slope to the abyssal waters off Brisbane"], ["Status", "The array ceased in 2023"], ["2015 drawings, water depth of M1 to M6", "500, 2000, 3200, 4200, 4700, 4800 m"], ["Mooring M4 design depth", "4259 m"], ["M4 float cluster near the top", "16 glass floats, 17-inch"]]}, "vitrovex": {"title": "VITROVEX glass floatation spheres (Nautilus Marine Service)", "url": "https://www.vitrovex.com/en/overview-flotation-housings-spheres", "kind": "Published manufacturer specifications", "note": "Nautilus Marine Service GmbH, overview page and datasheet (last update 03/2020); the datasheet states that its figures are based on seawater of 1.025 g/cm³. The IMOS drawings say only “glass floats 17-inch” without naming a maker, so this model stands in as a representative 17-inch deep-sea sphere.", "headers": ["Quantity (model FS-6700-17)", "Published value"], "rows": [["Depth rating", "6700 m"], ["Outer diameter", "17 in (432 mm)"], ["Wall thickness", "14 mm"], ["Weight in air", "17 kg"], ["Net buoyancy", "26 kg"], ["Density basis", "seawater 1.025 g/cm³"]]}, "agulhas": {"title": "CFOO Sea Atlas: Agulhas rings", "url": "https://cfoo.co.za/seaatlas/agulhasring.php", "kind": "Published typical properties", "note": "Centre for in situ Observational Oceanography (South Africa), Sea Atlas education pages, citing Pichevin, Nof and Lutjeharms (1999) for the drift speed. The swirl profile in the problem is a model.", "headers": ["Quantity", "Published value"], "rows": [["Rings shed per year", "about six"], ["Diameter", "200 to 280 km"], ["Depth reached", "about 1100 m"], ["Sense of rotation", "anticyclonic"], ["Drift speed", "about 5 to 8 km per day"]]}, "iersconst": {"title": "IERS useful constants", "url": "https://hpiers.obspm.fr/eop-pc/models/constants.html", "kind": "Published geodetic constants", "note": "International Earth Rotation and Reference Systems Service (Paris Observatory), accessed November 17, 2026. The nominal angular velocity is exact by definition; the measured mean value agrees to the digits shown.", "headers": ["Quantity", "Published value"], "rows": [["Nominal angular velocity of the Earth", "$7.292115146706\\times10^{-5}$ rad/s"], ["Earth’s equatorial radius", "6,378,136.6 m"]]}, "montereylat": {"title": "NOAA station 9413450, Monterey Harbor: location", "url": "https://tidesandcurrents.noaa.gov/benchmarks/9413450.html", "kind": "Published station coordinates", "note": "NOAA Tides and Currents benchmark sheet for station 9413450 (the same page as the shared tidal-datum source), accessed November 17, 2026.", "headers": ["Quantity", "Published value"], "rows": [["Station", "MONTEREY, MONTEREY HARBOR CA"], ["Latitude", "36° 36.3′ N (36.60500)"], ["Longitude", "121° 53.3′ W (−121.88800)"]]}, "qispec": {"title": "The Qi Wireless Power Transfer System, Power Class 0, Part 4: Reference Designs (v1.2.3)", "url": "https://faculty-web.msoe.edu/johnsontimoj/EE4980/files4980/Qi-PC0-part4-v1.2.3.pdf", "kind": "Published industry specification", "note": "Wireless Power Consortium, February 2017, Section 2.2.2 (Power Transmitter design A2), Table 1; copy hosted on a Milwaukee School of Engineering course page. Other Qi designs use other coils and frequencies.", "headers": ["Quantity (design A2 primary coil)", "Published value"], "rows": [["Outer diameter", "40 $\\pm$ 1 mm"], ["Inner diameter", "19 $\\pm$ 1 mm"], ["Turns", "10 per layer, 2 layers"], ["Operating frequency", "fixed, 140 kHz"]]}, "lhcdesign": {"title": "LHC Design Report, Volume I, Chapter 2: Beam parameters and definitions", "url": "https://indico.cern.ch/event/1001431/contributions/4205544/attachments/2183624/3689221/Vol_1_Chapter_2.pdf", "kind": "Published design parameters", "note": "CERN, LHC Design Report Vol. I (2004), Tables 2.1 and 2.4 (copy on CERN Indico). Collision values for 7 TeV protons.", "headers": ["Quantity", "Published value"], "rows": [["Ring circumference", "26,658.883 m"], ["Number of main bends (dipoles)", "1232"], ["Field of main bends", "8.33 T"], ["Circulating beam current", "0.582 A"], ["Bare inner vacuum screen in arcs", "36.9 mm wide, 46.5 mm high"]]}, "lhcquad": {"title": "Performance of the LHC arc superconducting quadrupoles (EPAC 2006)", "url": "https://proceedings.jacow.org/e06/PAPERS/WEPLS105.PDF", "kind": "Published magnet parameters (conference paper)", "note": "T. Tortschanoff et al. (CERN, CEA Saclay, ACCEL Instruments), Proceedings of EPAC 2006, Edinburgh, paper WEPLS105.", "headers": ["Quantity", "Published value"], "rows": [["Main arc quadrupoles fabricated", "408"], ["Nominal gradient", "223 T/m"]]}, "esacluster": {"title": "ESA Cluster: Electrifying aurorae", "url": "https://sci.esa.int/web/cluster/-/29108-electrifying-aurorae", "kind": "Published research summary", "note": "European Space Agency science pages (last updated September 1, 2019), describing Cluster satellite observations of the regions that accelerate auroral electrons.", "headers": ["Quantity", "Published description"], "rows": [["Electron energies after acceleration", "several keV (thousand electronvolts)"], ["Acceleration structures", "narrow, U-shaped, starting several thousand kilometres up"]]}, "uafelectrojet": {"title": "Alaska Science Forum: Auroral electrojets", "url": "https://gi.alaska.edu/alaska-science-forum/auroral-electrojets", "kind": "Published typical values (science column)", "note": "University of Alaska Fairbanks Geophysical Institute. Typical, storm-dependent values; the current’s geometry is far more complex than a straight line.", "headers": ["Quantity", "Published description"], "rows": [["Direction and altitude", "mostly east–west, near 100 km"], ["Current", "as large as half a million amperes"]]}, "earthheat": {"title": "Earth’s surface heat flux (Davies and Davies, 2010)", "url": "https://se.copernicus.org/articles/1/5/2010/", "kind": "Published global estimate (peer-reviewed)", "note": "J. H. Davies and D. R. Davies, Solid Earth 1, 5–24 (2010). Abstract: “Our final preferred estimate is 47$\\pm$2 TW.” The continental figures are from their preferred analysis (Section 5).", "headers": ["Quantity", "Published value"], "rows": [["Total surface heat flow", "47 $\\pm$ 2 TW"], ["Continents (preferred analysis)", "13.8 TW, mean 73 mW/m²"]]}}, "weeks": [{"week": 2, "title": "Rain, oceans, pyramids, and reservoirs", "subtitle": "A Tale of Two Orders", "skills": ["Build Riemann sums on data grids and predict whether they over- or underestimate", "Reason about integrals without computing them, using sign, symmetry, linearity, and bounds", "Integrate piecewise and discontinuous functions by geometry, splitting the region where a formula changes", "Describe a region in both orders, find where its boundaries meet, and reverse the order of integration", "Find volumes as $\\iint_D(\\text{top}-\\text{bottom})\\,dA$ and check them against known formulas"], "formulas": ["$\\displaystyle\\iint_R f\\,dA\\approx\\sum_{i,j}f(x_{ij}^*,y_{ij}^*)\\,\\Delta A$, with $(x_{ij}^*,y_{ij}^*)$ a sample point in each cell of area $\\Delta A$", "$\\displaystyle\\iint_R f\\,dA=\\int_a^b\\!\\!\\int_c^d f\\,dy\\,dx=\\int_c^d\\!\\!\\int_a^b f\\,dx\\,dy$ for continuous $f$ on $R=[a,b]\\times[c,d]$", "Type I region $D$: $a\\le x\\le b$, $g_1(x)\\le y\\le g_2(x)$, so $\\displaystyle\\iint_D f\\,dA=\\int_a^b\\!\\!\\int_{g_1(x)}^{g_2(x)}f\\,dy\\,dx$", "$m\\le f\\le M$ on $D$ $\\Rightarrow$ $m\\cdot\\text{Area}(D)\\le\\iint_D f\\,dA\\le M\\cdot\\text{Area}(D)$", "$\\displaystyle V=\\iint_D(\\text{top}-\\text{bottom})\\,dA$ when top $\\ge$ bottom on $D$"], "sources": ["imd_grid", "imd_terms", "cpc_oni", "inah_sun", "asce_gerd", "wiki_gerd", "nasa_ozone"], "problems": [{"title": "Weighing a monsoon storm on a 0.25° grid", "context": "When monsoon winds from the Arabian Sea hit the Western Ghats, the mountains along India’s west coast, they can drop more than 200 mm of rain in a day. To know how much water fell, not just the depth at one gauge, the India Meteorological Department (IMD) turns readings from almost 7,000 rain gauges into a grid of 0.25° cells, with one rainfall value per cell. Multiplying each cell’s depth by its area and adding up the results is a Riemann sum. How much water fell on a block of four cells? How well do two different Riemann sums estimate it, and what is the exact total in the model?", "model": "The grid spacing, gauge count, and rainfall categories are published by IMD, while the rainfall pattern on the four cells is a model of one heavy-rain day, not data from the archive.", "sources": ["imd_grid", "imd_terms"], "work": ["Sketch the $2\\times2$ block with its axes, and explain where $\\Delta A\\approx730$ km$^2$ comes from.", "Before (a): predict whether the upper-right sum will over- or underestimate, from how $d$ changes in $x$ and $y$.", "Mark the upper-right and midpoint sample points, and classify the four midpoint depths with IMD’s terms.", "After (c): explain in one sentence what $A(x)=\\int_0^2 d(x,y)\\,dy$ measures, and draw it as a cross-section of the solid under the graph of $d$.", "After (c): confirm the exact volume by integrating in the other order.", "Explain whether the midpoint sum over- or underestimated, using the shape of $d$ in $x$."], "questions": [{"prompt": "Using the upper-right corner of each cell as its sample point, find the Riemann sum for the rain volume over the block, in millions of cubic meters.", "expected": "620*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["Sample d at the upper-right corner of each cell, add the four depths, and multiply by the cell area of about 730 km².", "The corners are (1, 1), (1, 2), (2, 1), and (2, 2). Then convert: 1 mm of rain on 1 km² is 1000 m³, or 0.001 million m³."], "id": "w02-p1-a", "label": "a"}, {"prompt": "Using the midpoint of each cell as its sample point, find the Riemann sum for the rain volume over the block, in millions of cubic meters.", "expected": "430*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["Sample d at the center of each cell instead of a corner.", "The midpoints are (0.5, 0.5), (0.5, 1.5), (1.5, 0.5), and (1.5, 1.5); convert with mm × km² × 0.001 = millions of m³."], "id": "w02-p1-b", "label": "b"}, {"prompt": "Use an iterated integral of $d$ to find the exact rain volume over the block in the model, in millions of cubic meters.", "expected": "440*730/1000", "units": "million m³", "kind": "number", "tolerance": 1e-05, "hints": ["In cell units, integrate d over [0, 2] × [0, 2]; each unit square of the (x, y)-plane is one cell of 730 km².", "Integrate in y first; you will need ∫₀² x² dx = 8/3."], "id": "w02-p1-c", "label": "c"}], "solution": ["Cell area: a degree of latitude is about 111.2 km, and a degree of longitude is shorter by the factor $\\cos(\\text{latitude})$. Each cell is $0.25^\\circ$ of latitude, $0.25\\times111.2\\approx27.8$ km, by $0.25^\\circ$ of longitude, $27.8\\cos19^\\circ\\approx26.3$ km, so $\\Delta A\\approx730$ km$^2$. Measuring $x$ and $y$ in cell widths makes one unit square of the $(x,y)$-plane one cell. Since 1 mm of rain on 1 km$^2$ is 1000 m$^3$, a total in mm·cells times 0.73 gives millions of m$^3$.", "Prediction and upper-right sum (a): $d=50+30x^2+20y$ increases in both $x$ and $y$ on the block, so the upper-right corner gives the largest value on every cell, and the upper-right sum must overestimate. Its heights are $d(1,1)=100$, $d(1,2)=120$, $d(2,1)=190$, and $d(2,2)=210$ mm, so the sum is $620\\times0.73=452.6$ million m$^3$.", "Midpoint sum (b): the midpoint heights are $67.5$, $87.5$, $127.5$, and $147.5$ mm, which IMD would call heavy, heavy, very heavy, and very heavy. The sum is $430\\times0.73=313.9$ million m$^3$.", "Exact volume (c): the inner integral $A(x)=\\int_0^2(50+30x^2+20y)\\,dy=140+60x^2$ is the area of the cross-section of the solid at fixed $x$, that is, the rain volume per unit of east–west width. Then $\\int_0^2(140+60x^2)\\,dx=280+160=440$ mm·cells, so $V=440\\times0.73=321.2$ million m$^3$.", "Other order: integrating in $x$ first gives $\\int_0^2(50+30x^2+20y)\\,dx=180+40y$, and $\\int_0^2(180+40y)\\,dy=360+80=440$ mm·cells, the same total.", "Midpoint error: the midpoint sum is low by $10\\times0.73=7.3$ million m$^3$, about 2%. Midpoints integrate the linear $20y$ term exactly, but $30x^2$ is convex, and the average of a convex function over a cell is at least its value at the cell’s midpoint. So for a day like this one, a grid that samples cell centers would slightly undercount the water that fell."], "reflection": "IMD’s grid stores one value per 0.25° cell, at the grid point in its center. Which Riemann sum is a gridded rainfall product effectively computing, and where would it be most biased?", "extension": false, "id": "w02-p1", "discussionSolution": "It is effectively a midpoint sum, and it is most biased where the rain pattern curves most sharply. One value per cell, attached to the cell’s center, makes a gridded total a midpoint sum. Midpoint sums are exact for parts of the rainfall that vary linearly across a cell, so the bias comes from curvature: near a sharp rain peak (concave down) they overestimate, and in a dip between rain bands (convex) they underestimate. Over the steep Western Ghats, where rainfall can rise and fall sharply within a few cells, a 0.25° grid is least reliable.", "modelSpec": {"data": ["IMD grid: $0.25^\\circ\\times0.25^\\circ$ cells, built from 6955 rain gauges", "IMD terms for 24-hour rainfall: heavy 64.5–115.5 mm, very heavy 115.6–204.4 mm, extremely heavy ≥ 204.5 mm"], "assume": ["The block is a $2\\times2$ set of cells near $19^\\circ$N on the windward side of the Western Ghats.", "Each cell is treated as a rectangle of about 27.8 km $\\times$ 26.3 km, so $\\Delta A\\approx730$ km$^2$.", "Rain depth increases eastward toward the mountains and slightly northward, following one formula for one heavy-rain day."], "model": ["Rain depth: $d(x,y)=50+30x^2+20y$ mm", "$x$ = cell widths east of the block’s west edge, $y$ = cell widths north of its south edge, with $0\\le x\\le2$ and $0\\le y\\le2$", "Rain volume: $V=\\iint d\\,dA$, where 1 mm of rain on 1 km$^2$ is 1000 m$^3$"]}, "photo": {"alt": "Monsoon clouds spilling over forested ridges of the Western Ghats near Panchgani, Maharashtra, at sunset", "credit": "Cpangarkar", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Monsoon_clouds_in_Western_ghats.jpg", "file": "w02-p1.jpg"}, "figure": {"alt": "A two-by-two block of grid cells shaded by modeled rain depth, darker toward the east, with contour lines at 80, 120, 160, and 200 mm, crosses at the upper-right corner of each cell, and dots at the cell centers", "caption": "The model: rain depth $d(x,y)$ (mm) over four IMD cells of about 730 km$^2$ each, with $x$ and $y$ in cell widths. Crosses mark the upper-right sample points and dots the midpoints. Notice that the depth grows mostly with $x$, toward the mountains.", "file": "w02-p1"}}, {"title": "Is it El Niño? Reading the Niño 3.4 box", "context": "El Niño, a periodic warming of the tropical Pacific Ocean, shifts rain and drought from Peru to Indonesia. To decide whether one is under way, NOAA forecasters watch a single number: the average sea-surface temperature anomaly (the difference from normal) over a rectangle of ocean called the Niño 3.4 box. An average of $+0.5$ °C or more signals El Niño conditions. An average over a region is an integral divided by the region’s area, so you can learn a lot about it without computing. For three model anomaly maps, you will find the sign of the average, compute one average exactly, and bound one that has no elementary antiderivative.", "model": "The box, the $+0.5$ °C threshold, and the ONI values are published by NOAA, while the three anomaly maps are models chosen to illustrate the reasoning, not observed fields.", "sources": ["cpc_oni"], "work": ["Sketch $B$ in scaled coordinates, and shade where $T_1$ is warm and where it is cold.", "Before (a): without integrating, explain the sign of $I_1$ by comparing the warm and cold parts along each horizontal line $y=$ constant.", "Before (b): explain which terms of $T_2$ integrate to zero over $B$, and why, by pairing the points $(x,y)$ and $(-x,y)$, or $(x,y)$ and $(x,-y)$.", "For (c): with no antiderivative, prove bounds $m\\le T_3\\le M$ on $B$ and conclude that $m\\le I_3\\le M$.", "After (c): decide whether the lower bound alone proves that $T_3$ is an El Niño state."], "questions": [{"prompt": "For the developing-El Niño snapshot $T_1=1.5(x+0.3)(1-y^2)$, the Niño 3.4 index $I_1$ is", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Look along one horizontal line y = constant at a time, and compare the cold piece with the warm piece.", "T₁ is cold only for x < −0.3, and the factor 1 − y² is never negative, so it cannot change the sign on any horizontal line."], "options": ["Positive", "Negative", "Zero, because $T_1$ changes sign", "Impossible to tell without computing"], "id": "w02-p2-a", "label": "a"}, {"prompt": "For the anomaly map $T_2=0.9+1.6x^3-0.8y+0.6(1-x^2)$, find the index $I_2=\\frac14\\iint_B T_2\\,dA$, in °C.", "expected": "0.9+0.6*(2/3)", "units": "°C", "kind": "number", "tolerance": 1e-05, "hints": ["Over the symmetric box, the x³ and y terms cancel: pair (x, y) with (−x, y), or with (x, −y).", "The constant 0.9 averages to itself, and the average of 1 − x² over −1 ≤ x ≤ 1 is 1 − 1/3."], "id": "w02-p2-b", "label": "b"}, {"prompt": "For the warm pool $T_3=3e^{-(x^2+y^2)/2}$, find the best constant lower bound: the largest $m$ with $T_3\\ge m$ everywhere on the box $B$, in °C.", "expected": "3*exp(-1)", "units": "°C", "kind": "number", "tolerance": 1e-05, "hints": ["T₃ is smallest where x² + y² is largest on the box, at the corners.", "So −(x² + y²)/2 is at least −1, and the exponential is increasing."], "id": "w02-p2-c", "label": "c"}], "solution": ["Setup: in scaled coordinates, $x=$ (degrees east of $145^\\circ$W)$/25$ and $y=$ latitude$/5^\\circ$, so the box is $B=[-1,1]\\times[-1,1]$, with area 4, and $I=\\frac14\\iint_B T\\,dA$. Equal-area weighting is fine, because $\\cos(\\text{latitude})\\ge0.996$ over $\\pm5^\\circ$ of latitude.", "Sign of $I_1$ (a): on each line $y=c$ with $|c|<1$, the cold part $-1\\le x<-0.3$ is a triangle of base $0.7$ and depth $1.5(0.7)(1-c^2)$. The warm part $-0.3<x\\le1$ is a triangle of base $1.3$ and height $1.5(1.3)(1-c^2)$. The warm triangle is larger on every line, so $I_1>0$. (Exactly, $I_1=1.5(0.3)(2/3)=0.3$ °C, which is positive but still below the $0.5$ °C threshold.)", "Symmetry and linearity (b): $1.6x^3$ is odd in $x$ and $-0.8y$ is odd in $y$, and the box is symmetric in both, so these terms integrate to 0. By linearity, $I_2=0.9+0.6\\cdot\\frac12\\int_{-1}^1(1-x^2)\\,dx=0.9+0.6\\cdot\\frac23=1.3$ °C.", "Bounds (c): on $B$, $0\\le x^2+y^2\\le2$, so $-1\\le-(x^2+y^2)/2\\le0$. Because $e^s$ is increasing, $3e^{-1}\\le T_3\\le3$, so the best lower bound is $m=3e^{-1}\\approx1.10$ °C, reached at the corners. Multiplying by the area 4 gives $4(3e^{-1})\\le\\iint_BT_3\\,dA\\le12$, so $1.10\\le I_3\\le3$ °C.", "Interpretation: the lower bound alone shows $I_3>0.5$ °C, so $T_3$ is an El Niño state, with no antiderivative needed. A sharper bound uses $e^{-s}\\ge1-s$, which gives $T_3\\ge3(1-x^2/2)(1-y^2/2)$, whose average is $3(5/6)^2\\approx2.08$ °C. A numerical value is $I_3\\approx2.20$ °C."], "reflection": "The ONI reached 2.6 °C in Nov–Jan 2015/16. Using $T_1$ as an example, explain how a large positive box average can hide parts of the box that were colder than normal. Why do forecasters still find the average useful?", "extension": false, "id": "w02-p2", "discussionSolution": "A large positive average can hide cold water because the average is a signed integral divided by the area, so warm and cold regions cancel. In $T_1$, the western part of the box ($x<-0.3$) is colder than normal even though the index is positive. Forecasters still use the box average because the atmosphere responds to broad, large-scale warming, and averaging smooths out small eddies that matter little for that response.", "modelSpec": {"data": ["Niño 3.4 box: $5^\\circ$N–$5^\\circ$S, $120^\\circ$–$170^\\circ$W", "El Niño threshold: $+0.5$ °C", "Oceanic Niño Index (ONI): 2.6 °C (Nov–Jan 2015/16), 2.4 °C (1997/98), 2.0 °C (2023/24)"], "assume": ["The index is the plain area average of the anomaly over the box; weighting by latitude would change it by less than 0.4%.", "The three anomaly maps $T_1,T_2,T_3$ (in °C) are models, not observed fields."], "model": ["Scaled coordinates: $x=(\\text{degrees east of }145^\\circ\\text{W})/25$ and $y=\\text{latitude}/5^\\circ$, so the box is $B=[-1,1]\\times[-1,1]$", "Index: $I=\\dfrac{1}{4}\\iint_B T\\,dA$ (°C)", "$T_1=1.5(x+0.3)(1-y^2)$, $T_2=0.9+1.6x^3-0.8y+0.6(1-x^2)$, $T_3=3e^{-(x^2+y^2)/2}$"]}, "photo": {"alt": "NOAA world map of sea-surface temperature differences from average in November 2015, with a long band of warm water along the equator in the eastern Pacific", "credit": "NOAA", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:El_Ni%C3%B1o_in_November_2015.png", "file": "w02-p2.jpg"}, "figure": {"alt": "Left: a map of the tropical Pacific with the Niño 3.4 box drawn from 170°W to 120°W and from 5°S to 5°N, west of South America. Right: the same box in scaled coordinates from −1 to 1, split by the vertical line x = −0.3 into a narrow cold strip on the left and a wider warm part on the right", "caption": "Left: the Niño 3.4 box in the tropical Pacific. Right: the box $B$ in scaled coordinates, showing where the snapshot $T_1$ is cold ($x<-0.3$) and warm ($x>-0.3$).", "file": "w02-p2"}}, {"title": "The Pyramid of the Sun, smooth and stepped", "context": "The Pyramid of the Sun at Teotihuacan, near Mexico City, was raised in the first or second century CE from earth and stone, in four great stepped levels. Archaeologists at INAH, Mexico’s national institute of anthropology and history, have published its height, its base, and the volume of its solid body. How much material is in it? You will compare three models: a smooth pyramid, a staircase that fits inside it, and a staircase that wraps around it. The staircases are jumpy, piecewise-constant functions, and they show how the integral of such a function is defined.", "model": "INAH archaeologists publish the height, base, number of levels, and solid volume, while the square base, flat faces, and equal-height steps with vertical walls are modeling choices.", "sources": ["inah_sun"], "work": ["Sketch the base split along its diagonals $y=\\pm x$, and explain why: on each piece, $\\max(|x|,|y|)$ is a single formula. Which formula holds where?", "For (a): integrate $h$ over one piece, then check with the tetrahedron above $|y|\\le x\\le112$, with vertices $(0,0,0)$, $(0,0,66)$, $(112,\\pm112,0)$ and volume $\\frac13\\cdot$(base area)$\\cdot$(height).", "Before (b): write the inscribed staircase as $h_{\\text{low}}=16.5\\,\\lfloor4(1-\\max(|x|,|y|)/112)\\rfloor$, sketch its top view, and list every point where it is discontinuous (do not miss the summit).", "Explain why $h_{\\text{low}}$ is integrable.", "After (c): with $n$ equal steps, write (upper sum $-$ lower sum) as a function of $n$, and explain why it tends to 0."], "questions": [{"prompt": "Find the volume $V=\\iint h\\,dA$ of the smooth pyramid model, in cubic meters.", "expected": "4/3*66*112^2", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["By symmetry, the diagonals split the base into 8 congruent triangles; on 0 ≤ y ≤ x ≤ 112, h = 66(1 − x/112).", "On that triangle, integrate in y first: the inner integral just multiplies the height by the slice length x."], "id": "w02-p3-a", "label": "a"}, {"prompt": "Find the volume of the inscribed staircase $h_{\\text{low}}$, the four-level model that fits inside the smooth pyramid, in cubic meters.", "expected": "16.5*(168^2+112^2+56^2)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Treat the staircase as stacked square slabs 16.5 m thick. Level k (k = 1, 2, 3, 4) reaches out to where the smooth face is at height 16.5k, the top of that level.", "The side lengths of the levels are 168, 112, 56, and 0 m; the top level shrinks to a point."], "id": "w02-p3-b", "label": "b"}, {"prompt": "Find the volume of the circumscribed staircase, the four-level model that wraps around the smooth pyramid, in cubic meters.", "expected": "16.5*(224^2+168^2+112^2+56^2)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Level k now reaches out to where the smooth face is at height 16.5(k − 1), the bottom of that level.", "The side lengths of the levels are 224, 168, 112, and 56 m."], "id": "w02-p3-c", "label": "c"}], "solution": ["Setup: with the origin under the summit, $h(x,y)=66\\big(1-\\max(|x|,|y|)/112\\big)$ on $[-112,112]^2$. The diagonals $y=\\pm x$ split the square into 8 congruent triangles. On the four where $|y|\\le|x|$ (east and west), $\\max(|x|,|y|)=|x|$; on the four where $|x|\\le|y|$ (north and south), it is $|y|$. On $0\\le y\\le x\\le112$ it is simply $x$.", "Smooth volume (a): $\\int_0^{112}\\!\\int_0^{x}66(1-x/112)\\,dy\\,dx=66\\int_0^{112}(x-x^2/112)\\,dx=66\\cdot\\frac{112^2}{6}=137{,}984$ m$^3$, so $V=8\\times137{,}984=1{,}103{,}872$ m$^3$, about 1.10 million m$^3$.", "Tetrahedron check: the piece over $|y|\\le x\\le112$ is two of these triangles. Its base triangle has area $\\frac12(224)(112)=112^2$, so its volume is $\\frac13(112^2)(66)=275{,}968=2\\times137{,}984$ m$^3$, as expected.", "Discontinuities: $h_{\\text{low}}$ is piecewise constant. It is $49.5$ m on the square $\\max(|x|,|y|)\\le28$ (except the summit), $33$ m out to $56$, $16.5$ m out to $84$, and $0$ beyond. It jumps across the square outlines $\\max(|x|,|y|)=28,56,84$, and at the single point $(0,0)$, where $\\lfloor4\\rfloor=4$ gives $66$ m while all nearby values are $49.5$ m.", "Integrability and inscribed volume (b): $h_{\\text{low}}$ is bounded, and its discontinuities lie on three square outlines and one point, which have zero area, so it is integrable. Its integral is a sum of slabs: $16.5(168^2+112^2+56^2)=724{,}416$ m$^3$.", "Circumscribed volume (c): its slabs have sides $224$, $168$, $112$, and $56$ m, so its volume is $16.5(224^2+168^2+112^2+56^2)=1{,}552{,}320$ m$^3$. The two staircases are a lower and an upper sum for $h$. With $n$ equal steps their volumes differ by exactly one slab $224$ m wide and $66/n$ m thick, so upper $-$ lower $=\\frac{66}{n}\\cdot224^2\\to0$, and both staircases converge to the smooth volume.", "Model check: the published “a little over 1,175,000 m$^3$” lies between the two staircases and about 6% above the smooth pyramid, consistent with a flat top and steep walls. Because volume is proportional to height, heights from 63 m to 75 m would change the smooth estimate from about $1.05$ to $1.25$ million m$^3$."], "reflection": "Published heights for the pyramid range from about 63 m to 75 m. How much does that range change the smooth-model volume, and is the change bigger or smaller than the difference between the smooth and stepped models?", "extension": false, "id": "w02-p3", "discussionSolution": "The height range changes the smooth volume by only about 0.1 million m³ either way, which is smaller than the difference between the smooth and stepped models. Volume is proportional to height, so 63 m to 75 m moves the smooth estimate from about 1.05 to 1.25 million m³, about 9% either side of its value at 69 m. That is much smaller than the 0.38 to 0.45 million m³ between the smooth pyramid and either staircase, but comparable to the 0.07 million m³ between the smooth model and the published 1.175 million m³. With many levels, the staircases would close in on the smooth pyramid and the height uncertainty would dominate.", "modelSpec": {"data": ["Height today: 66.00 m", "Base: 224.00 m", "Architectural levels: 4", "Solid volume: a little over 1,175,000 m³"], "assume": ["The base is a square 224 m on a side, centered at the origin under the summit.", "In the smooth model, four flat faces rise from the edges of the base to the summit.", "In the staircase models, the 4 levels have equal height 16.5 m and vertical walls; one staircase fits inside the smooth pyramid and one wraps around it."], "model": ["Smooth height: $h(x,y)=66\\big(1-\\max(|x|,|y|)/112\\big)$ m on $[-112,112]^2$, with $x,y$ in meters", "Level $k$ ($k=1,\\ldots,4$) of a staircase is a square slab from height $16.5(k-1)$ m to $16.5k$ m", "Volume: $V=\\iint h\\,dA$ (m$^3$)"]}, "photo": {"alt": "The Pyramid of the Sun at Teotihuacan seen from the plaza, showing its stacked levels with visitors on the summit", "credit": "Daniel Case", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Pyramid_of_the_Sun,_Teotihuacan,_from_path_to_parking_lot.jpg", "file": "w02-p3.jpg"}, "figure": {"alt": "Left: side profile of the smooth pyramid, 224 m wide and 66 m high, with a solid four-level staircase inside it and a dashed four-level staircase around it. Right: top view of the square base with both diagonals drawn and one of the eight triangles shaded", "caption": "The models, to scale in meters. Side view: the smooth pyramid between the inscribed and circumscribed four-level staircases. Top view: the base split along its diagonals into 8 triangles, with the triangle $0\\le y\\le x$ shaded.", "file": "w02-p3"}}, {"title": "Filling the Grand Ethiopian Renaissance Dam", "context": "The Grand Ethiopian Renaissance Dam (GERD) on the Blue Nile is 145 m high and feeds a 5,150 MW hydropower plant. When full, its lake covers about 1,874 km² of flooded valleys and holds 74 billion m³ of water. Can a simple model of the lake’s shape, built from a few published numbers, predict that volume? You will describe the lake’s outline in two ways, compute its area and volume, and compare with the published value. The Blue Nile also carries a substantial sediment load, so you will also find the average sediment concentration in the water at the dam, an integral that works in only one order.", "model": "The area, volume, and dam height come from ASCE and the depth at the dam and reservoir length are secondary values, while the valley shape and the sediment profile are assumed.", "sources": ["asce_gerd", "wiki_gerd"], "work": ["Sketch $D$: find where each shoreline curve meets the dam and where the two curves meet each other, and which curve is on top (use a test point).", "Describe $D$ as a Type I region ($x$ outside) and as a Type II region ($y$ outside).", "Compute $\\iint_D 1\\,dA$ and $\\iint_D(1-x^2-|y|)\\,dA$ in both orders, and confirm that the answers agree.", "Explain which order was easier, and why.", "Before (c): explain why integrating $e^{-4z^2}$ over the dam cross-section sounding by sounding (vertical lines, $z$ inside) fails, and reverse the order."], "questions": [{"prompt": "In the Type II description of $D$ ($y$ outside, $x$ inside), the upper limit for $x$ is a function of $y$. Evaluate it at $y=0.36$: in scaled units (a fraction of $L$), how far upstream does the lake reach along that line?", "expected": "sqrt(1-0.36)", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Solve the shoreline equation |y| = 1 − x² for x.", "Keep the root with x ≥ 0, because the lake lies upstream of the dam."], "id": "w02-p4-a", "label": "a"}, {"prompt": "Use the model and the published area of 1,874 km² to estimate the reservoir’s volume $V$, in km³.", "expected": "8/15*(3/4*1874)*0.14", "units": "km³", "kind": "number", "tolerance": 1e-05, "hints": ["The volume is LWH times a scaled integral of the depth profile, so first find LW from the published area.", "In scaled units the area integral is 4/3, so (4/3)LW = 1874 km²; then multiply LW by H = 0.14 km and by the scaled volume integral."], "id": "w02-p4-b", "label": "b"}, {"prompt": "Find the average of $e^{-4z^2}$ over the water in the dam cross-section $\\{(y,z):|y|\\le z\\le1\\}$. This is the mean sediment concentration as a fraction of $c_0$.", "expected": "(1-exp(-4))/4", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Reverse the order: at height z, the water spans −z ≤ y ≤ z.", "After the y-integral, substitute u = 4z². The cross-section has area 1 in scaled units."], "id": "w02-p4-c", "label": "c"}], "solution": ["Sketch and intersections: the shorelines $y=\\pm(1-x^2)$ meet the dam $x=0$ at $y=\\pm1$ and meet each other at $x=1$, the upstream tip. At the test point $x=\\tfrac12$, the curves give $y=0.75$ and $y=-0.75$, so $y=1-x^2$ is the top curve.", "Two descriptions (a): Type I is $0\\le x\\le1$, $-(1-x^2)\\le y\\le1-x^2$. Type II is $-1\\le y\\le1$, $0\\le x\\le\\sqrt{1-|y|}$, because $|y|\\le1-x^2\\iff x\\le\\sqrt{1-|y|}$ when $x\\ge0$. At $y=0.36$ the upper limit is $\\sqrt{0.64}=0.8$, so the lake reaches $0.8L$ upstream along that line.", "Both orders: the area is $\\int_0^1 2(1-x^2)\\,dx=\\frac43=2\\int_0^1\\sqrt{1-y}\\,dy$. For the volume factor in Type I, let $c=1-x^2$; then $\\int_{-c}^{c}(c-|y|)\\,dy=c^2$, and $\\int_0^1(1-x^2)^2\\,dx=1-\\frac23+\\frac15=\\frac8{15}$. In Type II, $\\int_0^{\\sqrt{1-y}}(1-y-x^2)\\,dx=\\frac23(1-y)^{3/2}$ for $y\\ge0$, and $2\\int_0^1\\frac23(1-y)^{3/2}\\,dy=\\frac8{15}$, which agrees. Type I is easier: it needs only polynomials, with no square roots.", "Volume (b): the real area $\\frac43LW=1874$ km$^2$ gives $LW=1405.5$ km$^2$, so $V=\\frac8{15}LWH=\\frac8{15}(1405.5)(0.14)\\approx104.9$ km$^3$. Equivalently, $V=\\frac25AH$, so the model’s mean depth is $0.4H=56$ m.", "Model check: the published 74 km$^3$ means a real mean depth of $74/1874\\approx0.0395$ km $=39.5$ m, only $0.28H$. Real reservoirs flood many shallow side valleys that the smooth model ignores, so the model overestimates the volume by about 40%.", "Sediment (c): sounding by sounding, $\\int_{-1}^1\\int_{|y|}^1e^{-4z^2}\\,dz\\,dy$ needs an antiderivative of $e^{-4z^2}$, which is not elementary. Reversed, $\\int_0^1\\int_{-z}^{z}e^{-4z^2}\\,dy\\,dz=\\int_0^1 2ze^{-4z^2}\\,dz=\\frac{1-e^{-4}}4\\approx0.245$. The cross-section has area $\\int_{-1}^1(1-|y|)\\,dy=1$, so the mean concentration is about $0.245\\,c_0$: on average, the water at the dam carries about a quarter of the concentration at the deepest point."], "reflection": "The model gives about 105 km³, but the published volume is 74 km³. Which assumption is most responsible, and how would you change the bed shape to fix it while keeping the same area and the same depth at the dam?", "extension": false, "id": "w02-p4", "discussionSolution": "The assumed bed shape is most responsible. The smooth bed rises steadily away from the deepest point at the dam, so most of $D$ is fairly deep. Real reservoirs fill branching valleys whose side arms are shallow, so their mean depth is a smaller fraction of the maximum. A depth of $H(1-x^2-|y|)^p$ with $p>1$ keeps the same shoreline $D$, the same area, and the same 140 m at the dam, but makes most of the lake shallower: $p=2$ gives a mean depth of $0.23H\\approx32$ m, so $p\\approx1.5$ roughly matches the published 74 km³.", "modelSpec": {"data": ["Reservoir area when full: about 1,874 km²", "Storage at full capacity: 74 billion m³ = 74 km³", "Dam height: 145 m; depth at the dam: about 140 m (secondary)", "Reservoir length: up to 246 km (secondary)"], "assume": ["Plan coordinates are scaled: $x$ = distance upstream $/L$ and $y$ = distance across the valley $/W$, with the dam on the line $x=0$.", "The river bed rises like $x^2$ going upstream and like $|y|$ toward the banks, and the depth at the dam is $H=140$ m $=0.14$ km.", "At the dam, sediment concentration falls with height above the deepest point of the bed as $c=c_0e^{-(\\text{height}/70\\text{ m})^2}$."], "model": ["Water depth: $H(1-x^2-|y|)$ where this is positive; the lake is $D=\\{(x,y):x\\ge0,\\ |y|\\le1-x^2\\}$", "Area: $A=LW\\iint_D1\\,dA$; volume: $V=LWH\\iint_D(1-x^2-|y|)\\,dA$", "Dam cross-section, with $z$ = height above the deepest point $/H$: water fills $|y|\\le z\\le1$, with concentration $c_0e^{-4z^2}$"]}, "photo": {"alt": "False-color ASTER satellite image of the GERD reservoir filling: cyan water in a branching valley, vegetation in red, the dam at upper left", "credit": "NASA/METI/AIST/Japan Space Systems, and U.S./Japan ASTER Science Team", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Grand_Ethiopian_Renaissance_Dam_(ASTER).jpg", "file": "w02-p4.jpg"}, "figure": {"alt": "Left: plan view of the scaled lake, bounded by two parabolic shorelines that leave the dam line and close at an upstream tip. Right: V-shaped water cross-section at the dam, with the water surface across the top and brown shading that is darkest near the bottom of the V", "caption": "The model in scaled coordinates. Left: the lake $D$ upstream of the dam at $x=0$. Right: the V-shaped water cross-section at the dam, between the bed $z=|y|$ and the surface $z=1$, shaded by sediment concentration, which is highest near the deepest point.", "file": "w02-p4"}}, {"title": "Measuring the Antarctic ozone hole on a grid", "context": "Every southern spring, a hole opens in the ozone layer over Antarctica. NASA defines the hole as the region where total ozone is 220 Dobson units (DU) or lower; a Dobson unit measures the total amount of ozone in the column of air above a point. NASA reports the hole’s area each day from satellite maps, and on 21 September 2023 it reached its largest area that year, 26.0 million km². A computer finds that area by adding up grid cells, so the answer depends on which cells count. How far apart are the lower and upper cell counts on a coarse grid, and how fast does the gap close as the cells shrink?", "model": "NASA publishes the 220 DU definition, the 2023 maximum area, and the 2023 minimum ozone, while the circular hole and the 1000 km square grid are models.", "sources": ["nasa_ozone"], "work": ["Find the radius $r$ of the hole from its area.", "Draw the circle on a grid of 1000 km cells, with the South Pole at a grid corner. Shade the cells entirely inside the hole and, in another color, those that touch it.", "Explain why the area of the hole, $\\iint\\chi\\,dA$, lies between the two cell counts.", "Explain where $\\chi$ is discontinuous and why the gap must shrink to 0 as the cells shrink."], "questions": [{"prompt": "With 1000 km cells, find the lower sum: the total area of the cells that lie entirely inside the hole, in million km².", "expected": "16", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["By symmetry, count the cells in one quarter of the grid and multiply by 4.", "A cell lies entirely inside when its corner farthest from the pole is within r ≈ 2.88 thousand km of the pole."], "id": "w02-p5-a", "label": "a"}, {"prompt": "With 1000 km cells, find the upper sum: the total area of the cells that meet the hole, even partly, in million km².", "expected": "36", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["A cell meets the hole when its corner nearest the pole is closer than r to the pole.", "In one quarter, even the cell from (2, 2) to (3, 3) counts, because 2² + 2² = 8 < r² ≈ 8.28."], "id": "w02-p5-b", "label": "b"}, {"prompt": "Repeat with 500 km cells, and find (upper sum) $-$ (lower sum), in million km².", "expected": "11", "units": "million km²", "kind": "number", "tolerance": 1e-05, "hints": ["Each cell now has area 0.25 million km². The gap is the total area of the cells that meet the hole but are not entirely inside.", "In one quarter, 20 of the 500 km cells lie entirely inside; count the cells that meet the hole with the nearest-corner test."], "id": "w02-p5-c", "label": "c"}], "solution": ["Radius: $\\pi r^2=26.0$ gives $r=\\sqrt{26.0/\\pi}\\approx2.877$ thousand km, so $r^2\\approx8.28$. In the model, $O=99+121(x^2+y^2)/r^2$ DU equals 220 DU exactly when $x^2+y^2=r^2$, so the 220 DU contour is the circle of radius $r$.", "1000 km cells: in one quarter, the cell $[i,i+1]\\times[j,j+1]$ lies inside when its far corner does, $(i+1)^2+(j+1)^2\\le8.28$. That holds for $(i,j)=(0,0),(0,1),(1,0),(1,1)$, so the lower sum is $4\\times4=16$ million km$^2$. The cell meets the hole when its near corner is inside, $i^2+j^2<8.28$, which holds for all 9 cells with $i,j\\le2$, so the upper sum is $4\\times9=36$ million km$^2$.", "500 km cells: one quarter has 20 cells inside and 31 meeting the hole (80 and 124 in all), so the lower and upper sums are $20$ and $31$ million km$^2$, and the gap falls from $20$ to $11$ million km$^2$. The gap is the area of the cells crossed by the 220 DU contour, roughly (perimeter)$\\times$(cell size), so it tends to 0 as the cells shrink.", "Integrability: $\\chi$ is bounded and is discontinuous only on the contour, a curve of zero area, so it is integrable, and every Riemann sum converges to $\\pi r^2=26.0$ million km$^2$. A computer’s cell count therefore approaches the true area of the hole as the grid gets finer."], "reflection": "NASA’s maps count a cell as “in the hole” when the ozone value reported for that cell is at most 220 DU. Is that more like the lower sum, the upper sum, or a midpoint sum? Why does the choice matter less on a fine grid?", "extension": true, "id": "w02-p5", "discussionSolution": "It is most like a midpoint sum of $\\chi$: a cell crossed by the contour counts only when its sample point happens to be inside the hole. Such a sum always lies between the lower and upper sums, and all three differ only on cells crossed by the contour, whose total area shrinks with the cell size. On a fine grid that difference is a small fraction of the 26 million km².", "modelSpec": {"data": ["Ozone hole: the region with total ozone ≤ 220 DU", "2023 maximum hole area: 26.0 million km² (21 September)", "2023 minimum ozone: 99 DU (3 October)"], "assume": ["The hole is a circle centered on the South Pole, drawn on a flat map.", "Ozone rises with distance from the pole according to the formula below.", "The grid is made of square cells, with the pole at a grid corner."], "model": ["Ozone: $O(x,y)=99+121(x^2+y^2)/r^2$ DU, with $x,y$ in thousands of km from the pole", "Hole: $O\\le220\\iff x^2+y^2\\le r^2$, where $\\pi r^2=26.0$ million km$^2$", "Area of the hole: $\\iint\\chi\\,dA$, where $\\chi=1$ in the hole and $\\chi=0$ outside"]}, "figure": {"alt": "A circle of radius about 2.9 thousand km centered on the South Pole, drawn over a six-by-six grid of 1000 km squares with axes marked from −3 to 3 thousand km", "caption": "The model hole: the 220 DU contour, a circle of area 26.0 million km² centered on the South Pole, on a grid of 1000 km cells with the pole at a grid corner.", "file": "w02-p5"}}]}, {"week": 3, "title": "Dunes, tides, glaciers, and wind", "subtitle": "Life Is Like a Box of Integrals", "skills": ["Read a region from its limits and reverse the order, including curved (parabolic, cubic, sine) boundaries", "Split a region where a boundary formula changes, and combine a sum of integrals into one", "Set up triple integrals over boxes and other solids, finding bounds the problem leaves unstated", "Project a solid onto each coordinate plane and compare the resulting integrals", "Write iterated limits as an inequality chain, and reorder triple integrals that cannot be done as written"], "formulas": ["$\\displaystyle\\iint_D f\\,dA=\\int_a^b\\!\\!\\int_{g_1(x)}^{g_2(x)}f\\,dy\\,dx=\\int_c^d\\!\\!\\int_{h_1(y)}^{h_2(y)}f\\,dx\\,dy$ for continuous $f$, when $D$ can be described both ways", "$\\displaystyle\\iiint_E f\\,dV=\\iint_D\\Big(\\int_{\\text{floor}}^{\\text{ceiling}}f\\,dz\\Big)dA$, where $D$ is the shadow of $E$ in the $xy$-plane", "Centroid heights: $\\bar y=\\dfrac1A\\displaystyle\\iint_D y\\,dA$ for a region, $\\bar z=\\dfrac1V\\displaystyle\\iiint_E z\\,dV$ for a solid"], "sources": ["pilat", "noaa", "aquarium", "khumbu", "turkana", "threegorges"], "problems": [{"title": "The sand mountain of Pilat", "context": "The Dune du Pilat, on France’s Atlantic coast near Bordeaux, is the tallest sand dune in Europe: a wall of sand about 110 m high and 2.9 km long that creeps 1 to 5 m into the pine forest every year. The sea wind pushes sand up the dune’s gentle seaward side, the windward face. At the top, the crest, the sand avalanches down the steep forest side, called the slip face. A slice across the dune is a region between two curves. Where is the crest? How much sand does each meter of dune hold, and how high above the base is the center of that sand?", "model": "Width, length, height, and sand volume are published; the parabola-and-line cross-section, its flat base at sea level, and the slip-face angle are model choices.", "sources": ["pilat"], "work": ["Sketch the cross-section, and draw one horizontal slice (order $dx\\,dy$) and one vertical slice (order $dy\\,dx$).", "After (a): Show the quadratic you solved for the crest, and explain which root you reject.", "Check that the slip face slopes at about $34^\\circ$, the angle at which dry sand avalanches.", "Explain why the order $dy\\,dx$ needs two integrals: say where to split and why.", "Before (c): A geologist computes the first moment as \\[\\int_0^4\\!\\!\\int_0^{\\sqrt x/2}y\\,dy\\,dx+\\int_4^{5.5}\\!\\!\\int_0^{(5.5-x)/1.5}y\\,dy\\,dx.\\] Sketch both pieces on one picture, and combine them into one integral in the order $dx\\,dy$."], "questions": [{"prompt": "Find the crest, where the windward face $x=4y^2$ meets the slip face $x=5.5-1.5y$. Enter $(x,y)$ in model units.", "expected": ["4", "1"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["The crest is the point that lies on both curves.", "Setting 4y² = 5.5 − 1.5y gives 8y² + 3y − 11 = 0; one root is negative, below the ground."], "id": "w03-p1-a", "label": "a"}, {"prompt": "Find the area of the cross-section, in square meters. (This is also the volume of sand, in cubic meters, per meter of dune length.)", "expected": "41/12*110^2", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["In the order dx dy, a horizontal slice at height y runs from x = 4y² to x = 5.5 − 1.5y.", "Integrate for 0 ≤ y ≤ 1, then multiply by 110² to convert square model units to square meters."], "id": "w03-p1-b", "label": "b"}, {"prompt": "Find the height of the cross-section’s centroid above the base, in meters.", "expected": "15/41*110", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The centroid height is the first moment ∬ y dA divided by the area; the geologist’s sum is that first moment.", "Combined, the first moment is ∫₀¹ y(5.5 − 1.5y − 4y²) dy. Divide by the area in model units, then convert with 1 unit = 110 m."], "id": "w03-p1-c", "label": "c"}], "solution": ["Crest: setting $4y^2=5.5-1.5y$ gives $8y^2+3y-11=0$, which factors as $(y-1)(8y+11)=0$. So $y=1$ or $y=-11/8$. Reject the negative root: it lies below the ground, where the extended curves cross. The crest is $(4,1)$, which is 440 m inland and 110 m high.", "Slip-face angle: the slip face drops 1 unit over 1.5 units, so it slopes at $\\tan^{-1}(2/3)\\approx33.7^\\circ$, close to the $34^\\circ$ at which dry sand avalanches.", "Area in the order $dx\\,dy$: a horizontal slice at height $y$ runs from the windward face $x=4y^2$ to the slip face $x=5.5-1.5y$ (test $y=\\tfrac12$: $1<4.75$, so the order is right). So \\[A=\\int_0^1(5.5-1.5y-4y^2)\\,dy=5.5-0.75-\\tfrac43=\\tfrac{41}{12}\\] square units. One square unit is $110^2$ m$^2$, so $A\\approx41{,}342$ m$^2$: about 41,342 m$^3$ of sand per meter of dune.", "Area in the order $dy\\,dx$: a vertical slice has top $\\min\\!\\big(\\tfrac{\\sqrt x}2,\\tfrac{5.5-x}{1.5}\\big)$, and the formula changes at the crest, $x=4$. So we split there: \\[A=\\int_0^4\\tfrac{\\sqrt x}2\\,dx+\\int_4^{5.5}\\tfrac{5.5-x}{1.5}\\,dx=\\tfrac83+\\tfrac34=\\tfrac{41}{12},\\] the same area.", "Combining the geologist’s integrals: the two pieces are the windward and forest-side parts of the same region, so their sum is one integral in the order $dx\\,dy$: \\[\\int_0^1\\!\\!\\int_{4y^2}^{5.5-1.5y}y\\,dx\\,dy=\\int_0^1(5.5y-1.5y^2-4y^3)\\,dy=2.75-0.5-1=\\tfrac54.\\]", "Centroid height: $\\bar y=\\dfrac{5/4}{41/12}=\\dfrac{15}{41}\\approx0.366$ units, or about 40.2 m above the base. A triangle with the same three corners has its centroid at $1/3$ of the height. The windward face bulges seaward of the straight line from toe to crest, which adds sand at mid-height and lifts the centroid a little."], "reflection": "The model cross-section times the 2.9 km length gives about 120 million m³, more than twice the published 55 million m³. Which modeling choice is most to blame? And how much sand must cross each meter of the crest per year for the dune to advance 1 m?", "extension": false, "id": "w03-p1", "discussionSolution": "The flat base at sea level is most to blame. The published height of about 110 m is the height of the crest, but the model fills everything below the crest with sand down to sea level; if the dune sits on higher ground, its sand is much thinner. The model also ignores how the dune tapers at its ends. To advance 1 m, the whole cross-section must move 1 m: about 41,000 m³ of sand per meter of dune per year in the model, or about 19,000 m³ if we scale to the published volume (55 million m³ ÷ 2,900 m).", "modelSpec": {"data": ["Width: 600 m; length: 2,900 m", "Height: about 110 m", "Sand volume: 55 million m³", "Advance toward the forest: 1 to 5 m per year"], "assume": ["The cross-section is the same along the whole length of the dune.", "The dune sits on a flat base at sea level.", "One model unit is 110 m, both across and up.", "The windward face is a parabola, and the slip face is a straight line."], "model": ["Cross-section: the region bounded by the windward face $x=4y^2$, the slip face $x=5.5-1.5y$, and the base $y=0$", "$x$ = distance inland from the dune’s seaward toe, $y$ = height above the base, both in model units"]}, "photo": {"alt": "Aerial view of the Dune du Pilat: a long bank of pale sand between the Atlantic Ocean and a pine forest", "credit": "Mtu33260", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:DunePyla2.jpg", "file": "w03-p1.jpg"}, "figure": {"alt": "Cross-section of the dune drawn to scale: a curved windward face rising from the sea side to the crest and a straight, steeper slip face down to the forest side, with one horizontal slice across the region and one vertical slice on each side of the crest", "caption": "The model cross-section, to scale (1 unit = 110 m). The horizontal slice runs from the windward face to the slip face. The two vertical slices have different tops, one on each side of the crest.", "file": "w03-p1"}}, {"title": "Monterey Bay: a tank, a tide pool, and a hot mussel", "context": "The Monterey Bay Aquarium pumps seawater from the bay into its exhibits, including the Open Sea tank. In the model, the tank’s water is warmer than a target temperature near the top and cooler near the floor. Just outside the aquarium’s walls, mussels live on rocks in the intertidal zone, the strip of shore that the tide covers and uncovers twice a day. NOAA publishes long-term average water levels for Monterey, such as mean tide level and mean high water. Is the tank’s water warmer or cooler than the target overall? How long is a mussel underwater at each high tide, and how much heat does it build up while the tide is out?", "model": "The tank’s size and capacity and the Monterey tidal datums are published; the tank’s temperature profile, the sine-shaped tide, and the mussel’s warming rate are assumptions.", "sources": ["aquarium", "noaa"], "work": ["After (a): Explain why $\\iiint_B1\\,dV$ is the tank’s volume, and compare it with the published 1.2 million gallons ($1$ ft$^3\\approx7.48$ gal).", "Before (b): Predict the sign of $\\iiint_B(T-T_0)\\,dV$ from where the water is warmer or cooler than $T_0$, and explain why all six orders of integration give the same value.", "Before (c): Sketch the region of the band-average integral in the $\\theta y$-plane (a mussel at height $y$ is underwater while $\\sin\\theta>y$), write it in the other order, and explain why the reversed integral is easier.", "Prove, by changing the order of integration, that the heat dose is $D=\\int_0^\\tau(\\tau-s)\\,r(s)\\,ds$.", "Explain the factor $\\tau-s$ in words, and check the identity when $r$ is constant."], "questions": [{"prompt": "Find the volume $\\iiint_B1\\,dV$ of the tank model $B$, in cubic feet.", "expected": "90*52*35", "units": "ft³", "kind": "number", "tolerance": 1e-05, "hints": ["The tank is a box: integrate 1 over 0 ≤ x ≤ 90, 0 ≤ y ≤ 52, 0 ≤ z ≤ 35.", "On a box, the triple integral of 1 is length × width × height."], "id": "w03-p2-a", "label": "a"}, {"prompt": "Find $\\iiint_B (T-T_0)\\,dV$ over the tank model $B$, in °C·ft³.", "expected": "90*52*0.1*(35^2/2-20*35)", "units": "°C·ft³", "kind": "number", "tolerance": 1e-05, "hints": ["The integrand depends only on z, so the x and y integrals just give a factor of 90 × 52.", "Compute 0.1 ∫₀³⁵ (z − 20) dz. Expect a negative number: the cool layer is thicker than the warm one."], "id": "w03-p2-b", "label": "b"}, {"prompt": "Mussels are spread evenly in height between mean tide level and mean high water ($0\\le y\\le1$). Find their average time underwater during one high tide, in hours.", "expected": "2*12.42/(2*pi)", "units": "h", "kind": "number", "tolerance": 1e-05, "hints": ["Reverse the order: for 0 ≤ θ ≤ π/2, the height runs from 0 to sin θ.", "The band has scaled height 1, so the integral is already the average, in radians of phase; 1 radian is 12.42/(2π) hours."], "id": "w03-p2-c", "label": "c"}], "solution": ["Tank volume: integrating 1 over the box adds up every small volume $dV$, so $\\iiint_B1\\,dV=90\\cdot52\\cdot35=163{,}800$ ft$^3$. That is about 1.225 million gallons, within about 2% of the published 1.2 million gallons; the real tank is not a perfect box.", "Sign and order: $T-T_0=0.1(z-20)$ is positive above $z=20$ and negative below. The cool layer is 20 ft thick and the warm layer only 15 ft, so predict a negative total. On a box with a continuous integrand, all six orders give the same value (Fubini’s theorem).", "Tank integral: the integrand separates, so \\[\\iiint_B(T-T_0)\\,dV=90\\cdot52\\cdot0.1\\int_0^{35}(z-20)\\,dz=468(612.5-700)=-40{,}950\\] °C·ft$^3$. Dividing by the volume, the water averages 0.25 °C below the target.", "Tide setup: the amplitude is $A=(1.412-0.333)/2\\approx0.54$ m, and $0.873+0.54\\approx1.412$, so $y=1$ is MHW. The tide height is symmetric about $\\theta=\\pi/2$, so a mussel at height $y$ is underwater for $2\\int_{\\arcsin y}^{\\pi/2}d\\theta$ radians per high tide.", "Reversing the order: the region is $0\\le\\theta\\le\\pi/2$, $0\\le y\\le\\sin\\theta$, so \\[2\\int_0^1\\!\\!\\int_{\\arcsin y}^{\\pi/2}d\\theta\\,dy=2\\int_0^{\\pi/2}\\!\\!\\int_0^{\\sin\\theta}dy\\,d\\theta=2\\int_0^{\\pi/2}\\sin\\theta\\,d\\theta=2\\text{ rad}.\\] In the original order, the inner integral leaves $\\int\\arcsin y\\,dy$, which needs integration by parts.", "In hours: 2 radians of phase is $2\\cdot12.42/(2\\pi)\\approx3.95$ h. On average, a mussel in the band is underwater for about 4 h of each 12.42 h tide cycle.", "Heat dose: the region is $0\\le s\\le t\\le\\tau$. For fixed $s$, the variable $t$ runs from $s$ to $\\tau$, so \\[D=\\int_0^\\tau\\!\\!\\int_s^\\tau r(s)\\,dt\\,ds=\\int_0^\\tau(\\tau-s)\\,r(s)\\,ds.\\] In words: warming at time $s$ keeps the mussel warmer for the remaining $\\tau-s$ hours. For constant $r$, both sides give $r\\tau^2/2$."], "reflection": "Mussels high on the shore spend less time underwater and face longer, hotter low tides. Using the arcsin formula for time underwater, explain why a small step up the rock near mean high water costs much more underwater time than the same step near mean tide level.", "extension": false, "id": "w03-p2", "discussionSolution": "Because the time underwater falls more and more steeply as $y$ approaches 1. The time underwater per tide is $\\pi-2\\arcsin y$ radians, and its derivative $-2/\\sqrt{1-y^2}$ has size 2 at mean tide level ($y=0$) but grows without bound as $y$ approaches mean high water ($y=1$). So near the top of the band, each centimeter higher removes far more underwater time than the same step near mean tide level.", "modelSpec": {"data": ["Open Sea tank: 90 ft across, 52 ft front to back, 35 ft tall", "Open Sea capacity: 1,200,000 US gallons", "Monterey tidal datums above MLLW (mean lower low water): MHW (mean high water) 1.412 m, MTL (mean tide level) 0.873 m, MLW (mean low water) 0.333 m"], "assume": ["The tank is a box $B=[0,90]\\times[0,52]\\times[0,35]$ ft, with $z$ measured up from the floor.", "The water temperature $T$ depends only on height: $T-T_0=0.1(z-20)$ °C, where $T_0$ is the target temperature.", "The tide is a sine wave about MTL, with amplitude $A=(\\text{MHW}-\\text{MLW})/2\\approx0.54$ m and period 12.42 h.", "A mussel is underwater whenever the water level is above it."], "model": ["Tide height above MTL: $A\\sin\\theta$, with phase $\\theta$ in radians (1 rad $=12.42/(2\\pi)$ h)", "Scaled height $y=(\\text{height}-\\text{MTL})/A$; the band from MTL to MHW is $0\\le y\\le1$", "Average time underwater in that band, in radians of phase: $2\\displaystyle\\int_0^1\\!\\!\\int_{\\arcsin y}^{\\pi/2}d\\theta\\,dy$", "Mussel heat dose after $\\tau$ hours out of water: $D=\\displaystyle\\int_0^\\tau\\!\\!\\int_0^t r(s)\\,ds\\,dt$ (°C·h), where $r(s)$ is its warming rate (°C/h) $s$ hours after the tide leaves it"]}, "photo": {"alt": "Visitors silhouetted against the tall window of the Open Sea exhibit at the Monterey Bay Aquarium, with schools of fish in blue water", "credit": "Bill Abbott", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Open_Sea_exhibit_at_Monterey_Bay_Aquarium_2011.jpg", "file": "w03-p2.jpg"}, "figure": {"alt": "Left: side view of the Open Sea tank as a box, with a warmer upper layer above z = 20 ft and a cooler lower layer below it. Right: one high tide drawn as a sine curve for tidal phase from 0 to pi, with a dashed horizontal line at mussel height y and the part of the curve above that line shaded as under water", "caption": "Left: the tank model, warmer than $T_0$ above $z=20$ ft and cooler below. Right: one high tide in scaled units; a mussel at height $y$ is underwater while the curve $\\sin\\theta$ is above the dashed line.", "file": "w03-p2"}}, {"title": "The ice tongue below Everest", "context": "Climbers bound for Everest pitch their tents at Base Camp on the Khumbu Glacier, a river of ice about 17 km long that flows down from the mountain and melts away at 4,900 m. Below the Khumbu Icefall, a steep and broken stretch of the glacier, the ice forms a long tongue: the glacier’s lowest part, which rests in a U-shaped valley and thins to nothing at its end. How much ice is in the tongue? How much ground does it cover on a map, and how high above the bottom of the valley does its ice sit on average?", "model": "The glacier’s length and elevations are published (secondary source); the tongue’s length, width, and thickness, the parabolic valley, and the flat sloping ice surface are assumptions.", "sources": ["khumbu"], "work": ["Find the bounds on $x$ and $y$ that the model leaves unstated: the ice lies between $z=y^2$ and $z=1-x$, with $x\\ge0$ and no other bounds given.", "Sketch the shadow $D$ of the ice on the $xy$-plane, and name the floor and the ceiling over it.", "Sketch the shadows on the $yz$-plane and on the $xz$-plane, and state the inner limits over each.", "Write the volume integral in all three ways, and say which projection gives the easiest integral.", "After (a): Evaluate the scaled volume two ways, and confirm that the answers agree."], "questions": [{"prompt": "Find the volume of ice in the model tongue, in cubic kilometers.", "expected": "10*0.5*0.3*8/15", "units": "km³", "kind": "number", "tolerance": 1e-05, "hints": ["Project onto the yz-plane: for each (y, z) with y² ≤ z ≤ 1, x runs from 0 to 1 − z.", "The scaled volume is 8/15; multiply by L·W·H = 10 km × 0.5 km × 0.3 km."], "id": "w03-p3-a", "label": "a"}, {"prompt": "Find the area of the tongue’s footprint on the map (its shadow $D$ in the $xy$-plane), in square kilometers.", "expected": "10*0.5*4/3", "units": "km²", "kind": "number", "tolerance": 1e-05, "hints": ["The shadow is where the floor is below the ceiling: y² ≤ 1 − x.", "In scaled units its area is ∫₀¹ 2√(1 − x) dx; multiply by L·W to get square kilometers."], "id": "w03-p3-b", "label": "b"}, {"prompt": "Find the average height of the ice above the lowest line of the valley floor (the height of the solid’s centroid), in meters.", "expected": "3/7*300", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["The average height is ∭ z dV divided by the volume, both in scaled units.", "Projecting onto the xy-plane, the inner integral of z is ((1 − x)² − y⁴)/2. At the end, divide by 8/15 and multiply by H = 300 m."], "id": "w03-p3-c", "label": "c"}], "solution": ["Hidden bounds and the $xy$-shadow: $y^2\\le z\\le1-x$ forces $y^2\\le1-x$, so $x\\le1$ and $|y|\\le1$. The shadow is $D=\\{0\\le x\\le1,\\ -\\sqrt{1-x}\\le y\\le\\sqrt{1-x}\\}$, with floor $z=y^2$ and ceiling $z=1-x$, so \\[V=\\int_0^1\\!\\!\\int_{-\\sqrt{1-x}}^{\\sqrt{1-x}}(1-x-y^2)\\,dy\\,dx=\\int_0^1\\tfrac43(1-x)^{3/2}\\,dx=\\tfrac8{15}.\\]", "Other projections: on the $yz$-plane the shadow is $\\{y^2\\le z\\le1\\}$, and $0\\le x\\le1-z$ over it, so \\[V=\\int_{-1}^1\\!\\!\\int_{y^2}^1(1-z)\\,dz\\,dy=\\int_{-1}^1\\tfrac{(1-y^2)^2}2\\,dy=\\tfrac8{15}.\\] On the $xz$-plane the shadow is the triangle $0\\le z\\le1-x$, and $|y|\\le\\sqrt z$ over it, so $V=\\int_0^1\\!\\int_0^{1-x}2\\sqrt z\\,dz\\,dx$.", "Comparison: the $yz$ projection is easiest because it needs only polynomials. It agrees with the $xy$ projection: both give $\\tfrac8{15}$.", "Real size: $V=LWH\\cdot\\tfrac8{15}=10(0.5)(0.3)\\tfrac8{15}=0.8$ km$^3$ of ice. Footprint: $LW\\int_0^12\\sqrt{1-x}\\,dx=5\\cdot\\tfrac43\\approx6.67$ km$^2$.", "Average height: with $c=\\sqrt{1-x}$, \\[\\iiint z\\,dV=\\int_0^1\\!\\!\\int_{-c}^{c}\\tfrac{(1-x)^2-y^4}{2}\\,dy\\,dx=\\int_0^1\\tfrac45c^5\\,dx=\\tfrac45\\cdot\\tfrac27=\\tfrac8{35}.\\] So $\\bar z=\\tfrac{8/35}{8/15}=\\tfrac37$ of $H$: the ice’s centroid sits about 129 m above the valley’s lowest line."], "reflection": "Glaciologists measure thickness at a few points with radar and the surface everywhere from satellites. Which of your three projections matches that kind of data best, and why?", "extension": false, "id": "w03-p3", "discussionSolution": "The xy-projection matches it best. Satellites give the surface (the ceiling) over every map point, and radar gives the thickness (ceiling minus floor), which is exactly the inner integral over the shadow D. The yz-projection was easiest for this model, but it needs the down-glacier length of ice at each height, which neither instrument measures directly.", "modelSpec": {"data": ["Length of the main Khumbu Glacier: about 17 km", "Elevation of the terminus (lower end): 4,900 m", "Elevation of the source: 7,600 m"], "assume": ["The model covers only the lower tongue, below the Khumbu Icefall.", "The tongue is $L=10$ km long; at its upper end it has half-width $W=0.5$ km and center thickness $H=300$ m.", "Across the valley, the floor is a parabola; the ice surface is a flat, tilted plane.", "Coordinates follow the valley, so the valley floor has no down-glacier slope in these coordinates."], "model": ["Scaled coordinates: $x=$ distance down-glacier$/L$, $y=$ distance across$/W$, $z=$ height above the floor’s lowest line$/H$", "Ice: the solid between the parabolic valley floor $z=y^2$ and the flat ice surface $z=1-x$, with $x\\ge0$", "Real volume $=LWH\\times$(scaled volume)"]}, "photo": {"alt": "The debris-covered Khumbu Glacier filling a valley below snowy Himalayan peaks, seen between Lobuche and Gorak Shep with hikers in the foreground", "credit": "Faj2323", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:120410_Khumbu_Glacier_Pano.jpg", "file": "w03-p3.jpg"}, "figure": {"alt": "Three-dimensional sketch of the glacier tongue: the ice lies between a parabolic valley floor and a flat ice surface that slopes down toward the end of the tongue, with several cross-sections across the valley that shrink down-glacier", "caption": "The model ice tongue in scaled coordinates, between the floor $z=y^2$ and the surface $z=1-x$. The shaded cross-sections are slices at fixed $x$.", "file": "w03-p3"}}, {"title": "How much power does Lake Turkana’s wind give?", "context": "In the desert east of Lake Turkana in northern Kenya, a low-level jet (a fast stream of wind near the ground) is funneled between two mountains. The Lake Turkana Wind Power project sits in its path: 365 turbines, the largest wind farm in sub-Saharan Africa when it was built. Below a turbine’s rated speed, its power grows like the cube of the wind speed, so a farm’s average output depends on the whole spread of wind speeds, not just the average speed. The average output divided by the rated output is the capacity factor. What is the farm’s capacity factor, and how much energy does it make in a year? Engineers write the answer as integrals, and not all of them can be done in the order written.", "model": "The turbine count and rating, the average wind speed, and the estimated production are published; the Weibull wind model with shape 3, the rated speed, and the cube-law power curve are assumptions.", "sources": ["turkana"], "work": ["Before (a): Sketch the region of integral 1 in the $xp$-plane, then reverse the order (watch the cube-root boundary; no rectangle limits), and substitute.", "Write the region of integral 2 as one chain $0\\le\\square\\le\\square\\le\\square\\le1$, and explain why it cannot be done in the order written.", "Project that region onto the $xy$-plane, and name its floor and ceiling.", "Before (b): Reorder integral 2 with $x$ outermost, and describe the cross-section at fixed $x$.", "Write one more valid order, $dy\\,dz\\,dx$.", "Say which given integral you could have done as written."], "questions": [{"prompt": "Evaluate integral 1: the farm’s average output from winds below the rated speed, as a fraction of its rated output.", "expected": "(1-exp(-1.47)*(1+1.47))/1.47", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Reverse the order: for fixed x, p runs from 0 to x³, so the reversed integral is ∫₀¹ x³ f(x) dx.", "Substitute u = 1.47x³; then ∫ u e^(−u) du needs integration by parts."], "id": "w03-p4-a", "label": "a"}, {"prompt": "Reorder integral 2 with $x$ outermost. Enter the integrand of the outer $x$-integral as a function of $x$, without the factor 6 and with the number 1.47 for $a$.", "expected": "x^2/2*exp(-1.47*x^3)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["At fixed x, the chain leaves 0 ≤ z ≤ y ≤ x: a triangle in the yz-plane.", "The integrand does not depend on y or z, so the inner double integral is (triangle area) × exp(−1.47x³)."], "id": "w03-p4-b", "label": "b"}, {"prompt": "Use the capacity factor from integral 2 to estimate the farm’s annual energy, in GWh.", "expected": "310*8.76*(1-exp(-1.47))/1.47", "units": "GWh", "kind": "number", "tolerance": 1e-05, "hints": ["Substitute u = 1.47x³ in 6 ∫₀¹ (x²/2) exp(−1.47x³) dx to find the capacity factor.", "Annual energy = capacity factor × 310 MW × 8760 h, and 1 GWh = 1000 MWh."], "id": "w03-p4-c", "label": "c"}], "solution": ["Integral 1: the limits $0\\le p\\le1$, $\\sqrt[3]p\\le x\\le1$ describe the region below $p=x^3$ for $0\\le x\\le1$. Reversed, \\[\\int_0^1\\!\\!\\int_0^{x^3}f(x)\\,dp\\,dx=\\int_0^1x^3f(x)\\,dx=\\int_0^13ax^5e^{-ax^3}\\,dx.\\] With $u=ax^3$ this is \\[\\frac1a\\int_0^a ue^{-u}\\,du=\\frac{1-e^{-a}(1+a)}a\\approx0.294.\\]", "Integral 2 as a chain: $0\\le z\\le1$, $z\\le y\\le1$, and $y\\le x\\le1$ combine into $0\\le z\\le y\\le x\\le1$. As written, the innermost $\\int_y^1e^{-ax^3}\\,dx$ has no elementary antiderivative. Shadow on the $xy$-plane: $0\\le y\\le x\\le1$, with floor $z=0$ and ceiling $z=y$.", "Reordering with $x$ outermost: \\[\\int_0^1\\!\\!\\int_0^x\\!\\!\\int_0^y e^{-ax^3}\\,dz\\,dy\\,dx,\\] because the cross-section at fixed $x$ is the triangle $0\\le z\\le y\\le x$, of area $x^2/2$. Another valid order is $\\int_0^1\\!\\int_0^x\\!\\int_z^x e^{-ax^3}\\,dy\\,dz\\,dx$.", "Doable as written: integral 1 could also be done in its original order, since its inner integral is $e^{-ap}-e^{-a}$. Integral 2 could not.", "Capacity factor and energy: $CF=6\\int_0^1\\frac{x^2}2e^{-ax^3}\\,dx=\\frac{1-e^{-a}}a\\approx0.524$. So the farm makes about $0.524\\times310\\text{ MW}\\times8760\\text{ h}\\approx1{,}423$ GWh a year, close to the published estimate of 1,440 GWh."], "reflection": "At the average wind speed of 11 m/s, a turbine rated at 14 m/s would make (11/14)³ ≈ 49% of its rated power. Why is the model capacity factor larger, and which feature of the wind distribution would make it larger still?", "extension": false, "id": "w03-p4", "discussionSolution": "Because power grows like the cube of the speed, and the cube is convex: averaging it over the spread of speeds gives more than the cube of the average (Jensen’s inequality), since windy hours add much more than calm hours take away. Even with the cube capped at the rated power, the model capacity factor is 52%, not 49%. More time near or above 14 m/s (a larger Weibull scale, or a narrower spread centered above the rated speed) would raise it further.", "modelSpec": {"data": ["Turbines: 365 Vestas V52, 0.850 MW each", "Installed capacity: 310 MW", "Average wind speed: 11 m/s", "Estimated production: 1,440 GWh per year"], "assume": ["Wind speeds follow a Weibull distribution of shape 3: $P(\\text{speed}>v)=e^{-(v/c)^3}$, with $c=12.3$ m/s so that the mean is 11 m/s.", "Each turbine makes $0.850\\,(v/14)^3$ MW below its rated speed of 14 m/s, and 0.850 MW above it.", "No turbine ever sits idle in light wind or shuts down in strong wind (no cut-in or cut-out speed)."], "model": ["Scaled speed $x=v/14$: $P(\\text{scaled speed}>x)=e^{-ax^3}$ with $a=(14/12.3)^3\\approx1.47$, so the density is $f(x)=3ax^2e^{-ax^3}$", "Integral 1 (below-rated share of the rated output): $\\displaystyle\\int_0^1\\!\\!\\int_{\\sqrt[3]p}^{1}f(x)\\,dx\\,dp$", "Integral 2 (capacity factor, average output ÷ rated output): $CF=6\\displaystyle\\int_0^1\\!\\!\\int_z^1\\!\\!\\int_y^1e^{-ax^3}\\,dx\\,dy\\,dz$"]}, "photo": {"alt": "A row of wind turbines on a flat gravel plain at the Lake Turkana Wind Power site in Sarima, Kenya, with a worker in a safety vest in the foreground", "credit": "Andrew Owuor", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Wind_Turbines_in_Sarima_Kenya.jpg", "file": "w03-p4.jpg"}, "figure": {"alt": "Left: the model probability that the wind speed exceeds v, falling from 1 toward 0 as v increases, with the 11 m/s mean marked. Right: the model power per turbine, rising as the cube of the wind speed up to 0.850 MW at the rated speed of 14 m/s and flat after that", "caption": "The wind model. Left: the chance that the wind speed exceeds $v$, with the mean of 11 m/s marked. Right: the power curve of one turbine, which levels off at 0.850 MW above the rated speed of 14 m/s.", "file": "w03-p4"}}, {"title": "Lifting ships at the Three Gorges", "context": "At China’s Three Gorges Dam on the Yangtze River, the world’s largest ship lift works like an elevator for boats. Ships of up to 3,000 tons float into a basin, a tank of water, which is then raised straight up 113 m. The real lift is balanced by counterweights, heavy masses that move down as the basin moves up, so its motors do only a small part of the lifting. The start must also be smooth: a sudden change in acceleration, called jerk, is felt as a jolt by passengers and cargo. How much water is in the basin? How much energy would the lift need without counterweights, and how far does the basin rise while it speeds up?", "model": "The basin size, lift height, and largest ship size are published (secondary source); ignoring the counterweights and the smooth-start jerk profile are assumptions.", "sources": ["threegorges"], "work": ["Before (a): Describe the water in the basin as a box, and compute its volume as $\\iiint1\\,dV$.", "Write the region of the position integral $x(T)$ as an inequality chain.", "Reorder with $u$ outermost, and show that $x(T)=\\int_0^T\\frac{(T-u)^2}{2}\\,j(u)\\,du$.", "Check this formula with a constant jerk $j_0$."], "questions": [{"prompt": "Find the mass of water in the basin, in tonnes (1 m³ of water has a mass of 1 tonne).", "expected": "120*18*3.5", "units": "t", "kind": "number", "tolerance": 1e-05, "hints": ["The basin is a box 120 m × 18 m × 3.5 m.", "Volume in m³ equals mass in tonnes."], "id": "w03-p5-a", "label": "a"}, {"prompt": "Without counterweights, how much energy would it take to lift the full basin of water plus a 3,000 t ship through 113 m? Give megawatt-hours.", "expected": "(120*18*3.5+3000)*1000*9.81*113/(3.6*10^9)", "units": "MWh", "kind": "number", "tolerance": 1e-05, "hints": ["Work = (total mass) × g × height, with g = 9.81 m/s².", "Convert tonnes to kilograms, and use 1 MWh = 3.6 × 10⁹ J."], "id": "w03-p5-b", "label": "b"}, {"prompt": "With the smooth-start jerk profile, how far has the basin risen when it reaches full speed at $T=10$ s? Give meters.", "expected": "0.2*pi/100*1000*(pi^2-4)/(2*pi^3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Find j₀ from the full speed: integrating the jerk twice gives a speed of j₀T²/π at time T.", "Use your reordered formula. With w = u/T, the integral ∫₀¹ (1 − w)² sin(πw) dw equals (π² − 4)/π³."], "id": "w03-p5-c", "label": "c"}], "solution": ["Basin volume: the water fills the box $[0,120]\\times[0,18]\\times[0,3.5]$ m, so $\\iiint1\\,dV=120\\cdot18\\cdot3.5=7560$ m$^3$, which is 7560 t of water.", "Energy: $(7560+3000)\\times10^3\\text{ kg}\\times9.81\\times113\\text{ m}\\approx1.17\\times10^{10}$ J, or about 3.25 MWh. Counterweights make the real lift nearly balanced, so its motors supply only a small part of this.", "Reordering: the chain is $0\\le u\\le s\\le t\\le T$. For fixed $u$, the pair $(s,t)$ ranges over the triangle $u\\le s\\le t\\le T$, of area $(T-u)^2/2$, so $x(T)=\\int_0^T\\frac{(T-u)^2}2j(u)\\,du$. Check: a constant jerk $j_0$ gives $j_0T^3/6$ both ways.", "Smooth start: with $j(u)=j_0\\sin(\\pi u/T)$, the speed at $T$ is $j_0T^2/\\pi=0.2$ m/s, so $j_0=0.2\\pi/100$ m/s$^3$ for $T=10$ s. Substituting $w=u/T$ and then $w\\to1-w$ turns $\\int_0^1(1-w)^2\\sin\\pi w\\,dw$ into $\\int_0^1w^2\\sin\\pi w\\,dw=\\frac{\\pi^2-4}{\\pi^3}$. So \\[x(T)=j_0T^3\\cdot\\frac{\\pi^2-4}{2\\pi^3}\\approx0.59\\text{ m}:\\] the basin rises only about 0.59 m of its 113 m while it speeds up."], "reflection": "If the basin instead reached 0.2 m/s with constant acceleration over the same 10 s, how far would it travel? Why does the smooth start cover less distance?", "extension": true, "id": "w03-p5", "discussionSolution": "It would travel 1 m: constant acceleration a = 0.2/10 = 0.02 m/s² gives a distance of aT²/2 = 1 m. The smooth start accelerates gently at first, so it spends more of the 10 s moving slowly and covers only about 0.59 m.", "modelSpec": {"data": ["Ship lift basin: 120 m × 18 m × 3.5 m of water", "Vertical lift: 113 m", "Largest ships lifted: 3,000 tons"], "assume": ["There are no counterweights (the real lift is counterbalanced).", "Smooth start from rest: jerk $j(u)=j_0\\sin(\\pi u/T)$ for $0\\le u\\le T=10$ s, reaching full speed 0.2 m/s at time $T$."], "model": ["Position: $x(T)=\\displaystyle\\int_0^T\\!\\!\\int_0^t\\!\\!\\int_0^s j(u)\\,du\\,ds\\,dt$ (integrate jerk to get acceleration, then speed, then position)", "Constants: $g=9.81$ m/s²; water has a mass of 1 tonne per m³"]}, "figure": {"alt": "Graphs of jerk, acceleration, speed, and position against time for the first 10 seconds of the ship lift’s smooth start, each scaled so its maximum is 1", "caption": "The smooth start over the first 10 s: jerk, acceleration, speed, and position, each scaled to its maximum. Speed and position grow slowly at first.", "file": "w03-p5"}}]}, {"week": 4, "title": "Maps that reshape the plane", "subtitle": "Stretch Marks: How Maps Distort Area", "skills": ["Map rectangles and squares edge by edge under linear, polar, and nonlinear maps", "Decide whether a map is one-to-one and onto, with an inverse or a counterexample", "Compute Jacobians, including the polar factor r, and use |J| as the local area scale", "Change variables in a double integral, transforming the region, integrand, and area element together", "Choose between forward and inverse Jacobians and check the hypotheses of the theorem"], "formulas": ["$\\iint_D f\\,dx\\,dy=\\iint_{D^*}f(T(u,v))\\,\\left|\\dfrac{\\partial(x,y)}{\\partial(u,v)}\\right|du\\,dv$, when $T$ is $C^1$ and one-to-one from $D^*$ onto $D$ except possibly on a set of zero area", "$\\dfrac{\\partial(x,y)}{\\partial(u,v)}=x_uy_v-x_vy_u$; for the inverse map, $\\dfrac{\\partial(u,v)}{\\partial(x,y)}=1\\Big/\\dfrac{\\partial(x,y)}{\\partial(u,v)}$ at corresponding points", "A linear map $T(\\mathbf u)=A\\mathbf u$ multiplies every area by $|\\det A|$; in polar coordinates, $dA=r\\,dr\\,d\\theta$"], "sources": ["kspivot", "graphene", "neowise", "boxmuller", "snyder", "unareas"], "problems": [{"title": "Crop circles on the Kansas plains", "context": "Seen from the air, the farmland of western Kansas is covered with green circles. Each circle is watered by a center pivot: a long sprinkler pipe on wheels that rotates around a well at its center. Center pivots water about 90% of the irrigated acreage in Kansas. As the pipe turns, each nozzle along it sweeps out a ring of the field. The outer nozzles sweep much larger rings than the inner ones, so the nozzles cannot all be the same size. How much water must each nozzle deliver so that the whole field gets the same depth, and what share of the water goes to the outer half of the pipe?", "model": "The 128-acre area and 650 gpm flow come from a published worked example; the full circle, uniform depth, 10 ft nozzle spacing, and 24-hour turn are assumptions.", "sources": ["kspivot"], "work": ["Sketch the image of $[1100,L]\\times[0,\\pi/12]$ under $T$: the ground the outer span $1100\\le r\\le L$ waters in one hour. Say what each of the four edges of the rectangle becomes.", "After (a): Explain why the points where $T$ is not one-to-one do not spoil $\\iint_D dA=\\int_0^{2\\pi}\\!\\int_0^L r\\,dr\\,d\\theta$.", "Before (b): Compute $\\partial(x,y)/\\partial(r,\\theta)$ from the $2\\times2$ determinant.", "Before (c): Predict whether the outer half of the pipe waters more or less than half of the field."], "questions": [{"prompt": "Where is the polar map $T$ not one-to-one on $D^*=[0,L]\\times[0,2\\pi]$? Choose the inputs $(r,\\theta)$ that have the same image as some other input.", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Look for two different inputs with the same output. What point does r = 0 give, whatever θ is?", "Compare T(r, 0) with T(r, 2π)."], "options": ["Only the inputs with $r=0$.", "All inputs with $r=0$ (they all give the pivot), and each pair $(r,0)$, $(r,2\\pi)$ (the same spoke).", "The inputs with $\\theta=\\pi$, which land on the negative $x$-axis.", "None: polar coordinates are one-to-one on this rectangle."], "id": "w04-p1-a", "label": "a"}, {"prompt": "The nozzle at distance $r$ ft from the pivot waters the ring $r-5\\le\\rho\\le r+5$ ft. For uniform depth, its flow is the system flow times (ring area)/(field area). Enter the nozzle’s flow in gpm as a function of r.", "expected": "650*20*pi*r/(128*43560)", "units": "gpm", "kind": "expression", "tolerance": 1e-05, "hints": ["The ring is the image of the rectangle [r − 5, r + 5] × [0, 2π] under the polar map, so its area is the double integral of ρ dρ dθ.", "The ring area is 20πr ft². The field is 128 × 43,560 ft², and the whole field shares 650 gpm."], "id": "w04-p1-b", "label": "b"}, {"prompt": "What fraction of the total flow goes to the nozzles on the outer half of the pipe, $L/2\\le r\\le L$?", "expected": "3/4", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Flow is proportional to the area watered, so compare areas.", "Compare the integral of r dr from L/2 to L with the integral of r dr from 0 to L."], "id": "w04-p1-c", "label": "c"}], "solution": ["Image of the outer span: The pipe turns $2\\pi/24=\\pi/12$ radians in one hour, and $L=\\sqrt{128\\cdot43{,}560/\\pi}\\approx1332$ ft. The edge $r=1100$ becomes an arc of radius 1100 ft and the edge $r=L$ an arc of radius $L$, both through $15^\\circ$. The edge $\\theta=0$ becomes the radial segment from 1100 ft to $L$ on the positive $x$-axis, and the edge $\\theta=\\pi/12$ becomes the matching segment at $15^\\circ$. The image is a curved wedge of an annulus, with area $\\tfrac{\\pi}{24}(L^2-1100^2)\\approx73{,}900$ ft$^2$.", "Jacobian: $\\dfrac{\\partial(x,y)}{\\partial(r,\\theta)}=\\det\\begin{pmatrix}\\cos\\theta&-r\\sin\\theta\\\\\\sin\\theta&r\\cos\\theta\\end{pmatrix}=r\\cos^2\\theta+r\\sin^2\\theta=r$.", "Where $T$ is not one-to-one: The whole edge $r=0$ collapses to the pivot, and the edges $\\theta=0$ and $\\theta=2\\pi$ land on the same spoke. Everywhere else $T$ is one-to-one. The repeated points form a single point and a segment, which have zero area, so the Change of Variables Theorem still gives $\\iint_D dA=\\int_0^{2\\pi}\\!\\int_0^L r\\,dr\\,d\\theta$. Equivalently, delete those edges from $D^*$ and nothing changes.", "Flow of one nozzle: The nozzle at distance $r$ waters $\\int_0^{2\\pi}\\!\\int_{r-5}^{r+5}\\rho\\,d\\rho\\,d\\theta=20\\pi r$ ft$^2$ of the $128\\cdot43{,}560$ ft$^2$ field. So it needs $650\\cdot20\\pi r/(128\\cdot43{,}560)\\approx0.00732\\,r$ gpm, which is linear in $r$: about 9.5 gpm at 1300 ft but only 0.7 gpm at 100 ft.", "Outer half: The outer half of the pipe gets $\\int_{L/2}^L r\\,dr\\Big/\\int_0^L r\\,dr=\\dfrac{L^2-L^2/4}{L^2}=\\dfrac34$ of the water, because the factor $r$ gives the outer rings more weight. So the outer half waters more than half of the field and must deliver three quarters of the 650 gpm, about 490 gpm."], "reflection": "The published guide says runoff problems usually appear at the outer edge of a pivot. Use the Jacobian factor $r$ to explain why the outer nozzles must put water on the ground faster.", "extension": false, "id": "w04-p1", "discussionSolution": "Because the area element is r dr dθ, the ring a nozzle waters grows in proportion to its distance r from the pivot. In one revolution a nozzle at radius r waters a ring of area 2πr times its width, and all nozzles finish their rings in the same time, so the outer nozzles must deliver water at a rate proportional to r. If the soil cannot absorb water that fast, the extra runs off, which is why runoff shows up at the outer edge first.", "modelSpec": {"data": ["Irrigated area in the worked example: $128$ acres, where $1$ acre $=43{,}560$ ft$^2$", "System flow: $650$ gallons per minute (gpm)", "Share of Kansas irrigated acreage watered by center pivots: about 90%"], "assume": ["The irrigated area is one full circle of radius $L$, so $\\pi L^2=128\\times43{,}560$ ft$^2$ and $L\\approx1332$ ft.", "Every part of the field receives the same depth of water.", "Nozzles are spaced $10$ ft apart, and each waters a ring $10$ ft wide centered on it.", "The pipe turns once every $24$ hours."], "model": ["Polar map $T(r,\\theta)=(r\\cos\\theta,\\ r\\sin\\theta)$ on $D^*=[0,L]\\times[0,2\\pi]$, with $r$ in feet and $\\theta$ in radians", "For uniform depth, the flow (gpm) each part of the pipe needs is proportional to the area it waters"]}, "photo": {"alt": "Satellite view of Kansas farmland packed with green center-pivot circles, some with pie-slice wedges missing, set in a grid of square fields", "credit": "NASA / USGS (Landsat)", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Landsat_sees_crops_in_Kansas.jpg", "file": "w04-p1.jpg"}, "figure": {"alt": "Left: the parameter rectangle in the r-theta plane, with r from 0 to L and theta from 0 to 2 pi, and a small shaded rectangle at r from 1100 to L and theta from 0 to pi over 12 whose four edges have different colors. Right: the circular field drawn to scale, with faint rings, the pivot at the center, the sprinkler pipe, and the matching shaded curved wedge at the outer edge, its edges in the same colors", "caption": "The polar map $T$ sends the rectangle $D^*$ in the $(r,\\theta)$-plane (left) onto the circular field (right). The shaded rectangle $[1100,L]\\times[0,\\pi/12]$ is the ground the outer span waters in one hour; matching colors show where each of its edges goes.", "file": "w04-p1"}}, {"title": "Graphene: a hammock one atom thick", "context": "Graphene is a single layer of carbon atoms arranged in a honeycomb pattern. In 2004, Andre Geim and Konstantin Novoselov in Manchester peeled such layers off graphite, the material in pencil lead, and they won the 2010 Nobel Prize in Physics for it. The Nobel committee pictured a 1 m² graphene hammock that could hold a cat yet weigh less than one of the cat’s whiskers. The honeycomb is built by repeating one tile, the unit cell, which holds two atoms. How large is that cell, and how many atoms are in the hammock?", "model": "The carbon–carbon distance, cell area, and density are published values; the perfect, flat, defect-free lattice is the model.", "sources": ["graphene"], "work": ["Map the four corners of the unit square under $T$, sketch the cell $T([0,1]^2)$, and write the matrix $A$ of $T$.", "Show that the four lines bounding the cell, $y=0$, $y=\\tfrac{\\sqrt3}{2}a$, $y=\\sqrt3\\,x$, and $y=\\sqrt3\\,(x-a)$, become the sides of the square $0\\le u\\le1$, $0\\le v\\le1$ in $(u,v)$.", "After (b): Explain why $T$ is one-to-one and onto $\\mathbb R^2$. Compute $\\partial(u,v)/\\partial(x,y)$ for $T^{-1}$ and check that it equals $1/\\det A$.", "Count the carbon atoms in a 1 m² hammock, using the cell area from (a)."], "questions": [{"prompt": "Find the area, in nm², of one unit cell of graphene, the image of the unit square under T.", "expected": "3*sqrt(3)/2*0.142^2", "units": "nm²", "kind": "number", "tolerance": 1e-05, "hints": ["T is linear, so the cell area is |det A| times the area of the unit square.", "With a = √3 × 0.142 nm, det A = (√3/2)a²."], "id": "w04-p2-a", "label": "a"}, {"prompt": "Measure $x$ and $y$ in units of $a$, so that $a=1$. Enter the inverse map $T^{-1}(x,y)=(u,v)$, which gives the lattice coordinates of the point $(x,y)$.", "expected": ["x-y/sqrt(3)", "2*y/sqrt(3)"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["With a = 1, T says x = u + v/2 and y = (√3/2)v. Solve this system for u and v.", "Solve y = (√3/2)v for v first, then use x = u + v/2 to find u."], "id": "w04-p2-b", "label": "b"}, {"prompt": "Which of these maps is not one-to-one on the whole plane?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["For each map, try to solve for (u, v) from (x, y). A map fails if some (x, y) has two different solutions.", "For S, add and subtract the two equations. For G, u = x comes first. Then check F the same way."], "options": ["$T(u,v)=(u+\\tfrac12v,\\ \\tfrac{\\sqrt3}{2}v)$, the lattice map", "$S(u,v)=(u+v,\\ u-v)$", "$F(u,v)=(u^2,\\ v)$", "$G(u,v)=(u,\\ v+u^3)$"], "id": "w04-p2-c", "label": "c"}], "solution": ["Corners and matrix: $a=\\sqrt3\\times0.142\\approx0.2460$ nm. The map $T(u,v)=u\\,\\mathbf a_1+v\\,\\mathbf a_2$ has matrix $A=\\begin{pmatrix}a&a/2\\\\0&\\tfrac{\\sqrt3}{2}a\\end{pmatrix}$. The corners go to $(0,0)\\mapsto(0,0)$, $(1,0)\\mapsto(a,0)$, $(1,1)\\mapsto(\\tfrac32a,\\tfrac{\\sqrt3}{2}a)$, and $(0,1)\\mapsto(\\tfrac a2,\\tfrac{\\sqrt3}{2}a)$, so the cell is a rhombus with $60^\\circ$ and $120^\\circ$ angles.", "Cell area: The unit square has area 1, so the cell has area $\\det A=\\tfrac{\\sqrt3}{2}a^2=\\tfrac{3\\sqrt3}{2}(0.142)^2\\approx0.0524$ nm$^2$, which matches the published 0.052 nm$^2$.", "Inverse, one-to-one, and onto: With $a=1$, solving $y=\\tfrac{\\sqrt3}{2}v$ gives $v=2y/\\sqrt3$, and then $x=u+v/2$ gives $u=x-y/\\sqrt3$. This formula works for every $(x,y)$, so $T$ is onto, and it gives only one $(u,v)$, so $T$ is one-to-one. Substituting it, the lines $y=0$ and $y=\\tfrac{\\sqrt3}{2}$ become $v=0$ and $v=1$, and the lines $y=\\sqrt3x$ and $y=\\sqrt3(x-1)$ become $u=0$ and $u=1$. The inverse has $\\partial(u,v)/\\partial(x,y)=1\\cdot\\tfrac{2}{\\sqrt3}-(-\\tfrac1{\\sqrt3})\\cdot0=\\tfrac{2}{\\sqrt3}$, which is $1/\\det A$ because $\\det A=\\tfrac{\\sqrt3}{2}$ when $a=1$.", "Which map fails: $S$ has inverse $u=\\tfrac{x+y}2$, $v=\\tfrac{x-y}2$, and $G$ has inverse $u=x$, $v=y-x^3$. The lattice map $T$ is one-to-one by the previous step. Only $F$ fails, because $F(1,0)=F(-1,0)=(1,0)$.", "Atoms in the hammock: One cell covers $0.0524$ nm$^2=5.24\\times10^{-20}$ m$^2$ and holds two atoms, so 1 m$^2$ holds $2/(5.24\\times10^{-20})\\approx3.8\\times10^{19}$ atoms. At the published 0.77 mg per m$^2$, the hammock weighs less than a milligram."], "reflection": "A sheet of graphene and a sheet of paper both cover 1 m². Why is the area of one cell, the determinant of one small linear map, the key number for weighing the graphene sheet, and why does this not work for the paper?", "extension": false, "id": "w04-p2", "discussionSolution": "Because graphene repeats one cell everywhere. A linear map stretches every region by the same factor |det A|, so every cell of the lattice has the same area, 0.052 nm², and holds two atoms. The number of atoms in a large sheet is twice its area divided by the cell area, and the mass follows. A sheet of paper has no single repeating cell, so no single determinant describes it.", "modelSpec": {"data": ["Carbon–carbon distance: $0.142$ nm", "Two carbon atoms per unit cell", "Area of the unit cell: $0.052$ nm$^2$", "Density: $0.77$ mg/m$^2$"], "assume": ["The graphene sheet is a perfect, flat lattice with no defects."], "model": ["Lattice spacing $a=\\sqrt3\\times0.142$ nm $\\approx0.246$ nm", "Lattice vectors $\\mathbf a_1=(a,0)$ and $\\mathbf a_2=(\\tfrac a2,\\tfrac{\\sqrt3}{2}a)$, in nm", "Linear map $T(u,v)=u\\,\\mathbf a_1+v\\,\\mathbf a_2$; the unit cell is $T([0,1]^2)$"]}, "photo": {"alt": "Grey-scale atomic force microscope image of graphene showing a regular hexagonal pattern of dark holes ringed by bright carbon atoms, with a 0.5 nm scale bar", "credit": "AFM real", "license": "CC0", "licenseUrl": "http://creativecommons.org/publicdomain/zero/1.0/deed.en/", "page": "https://commons.wikimedia.org/wiki/File:Carbon_atoms_in_graphene.jpg", "file": "w04-p2.jpg"}, "figure": {"alt": "Honeycomb lattice of carbon atoms joined by short bonds, with the lattice vectors a1 and a2 drawn as arrows from one corner and one rhombus-shaped unit cell shaded; a double arrow between two neighboring atoms is labeled 0.142 nm", "caption": "The graphene model: carbon atoms (dots) $0.142$ nm apart, the lattice vectors $\\mathbf a_1$ and $\\mathbf a_2$, and one unit cell $T([0,1]^2)$ (shaded), which contains two atoms.", "file": "w04-p2"}}, {"title": "Straightening the orbit of comet NEOWISE", "context": "In July 2020, comet NEOWISE was a naked-eye sight in the evening and morning skies of the Northern Hemisphere. On July 3 it passed its perihelion, the point of its orbit closest to the Sun, at only 0.29 AU. (One astronomical unit, 1 AU, is about 150 million km.) It then headed back out on an orbit so stretched that it is almost a parabola. By Kepler’s second law, the line from the Sun to the comet sweeps out area at a constant rate, so time can be measured as area. A map due to Levi-Civita turns such orbits into straight lines, which makes that area easy to compute. How many days after perihelion was the comet 1 AU from the Sun?", "model": "The perihelion distance, eccentricity, and perihelion date are published by JPL; the exact parabola and the neglect of the planets are simplifications.", "sources": ["neowise"], "work": ["Show that $T(-u,-v)=T(u,v)$, and say what this means for whether $T$ is one-to-one on the plane.", "Write $(u,v)=(\\varrho\\cos\\psi,\\varrho\\sin\\psi)$ and show that $T$ squares the distance from the origin and doubles the angle. Use this to explain why $T$ is one-to-one on the first quadrant and sends rays to rays.", "Find the image of each edge of the unit square $[0,1]^2$ and sketch it; for the two edges that become parabolas, eliminate the parameter. Check that the line $u=\\sqrt q$ becomes the comet’s parabola.", "Before (c): Find the vertices and side equations of the region $D^*$ that $T$ maps onto $D$, and choose an order of integration.", "Before (c): State the hypotheses of the Change of Variables Theorem and check each one."], "questions": [{"prompt": "Enter the Jacobian $\\dfrac{\\partial(x,y)}{\\partial(u,v)}$ of the Levi-Civita map $T(u,v)=(u^2-v^2,\\ 2uv)$ as a function of u and v.", "expected": "4*(u^2+v^2)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The Jacobian is the determinant x_u y_v − x_v y_u.", "x_u = 2u, x_v = −2v, y_u = 2v, y_v = 2u."], "id": "w04-p3-a", "label": "a"}, {"prompt": "Find the area, in AU², of the image $T([0,1]^2)$ of the unit square.", "expected": "8/3", "units": "AU²", "kind": "number", "tolerance": 1e-05, "hints": ["T is one-to-one on the square, so the area is the integral of the Jacobian from (a) over [0, 1] × [0, 1].", "Split 4(u² + v²) into two terms; the integral of 4u² over the square is 4/3."], "id": "w04-p3-b", "label": "b"}, {"prompt": "Using the area of D and Kepler’s second law, find how many days after perihelion the model comet is 1 AU from the Sun.", "expected": "0.2947*sqrt(0.7053/0.2947)*(2*0.2947+1)/3/(pi*sqrt(2*0.2947))*365.25", "units": "days", "kind": "number", "tolerance": 1e-05, "hints": ["The area of D is the integral of the Jacobian over D*, the triangle with vertices (0, 0), (√q, 0), (√q, √(1 − q)).", "Integrate 4(u² + v²) with v first, from 0 to ku where k = √((1 − q)/q). Then divide by the sweep rate π√(2q) AU² per year and convert to days."], "decimals": 1, "id": "w04-p3-c", "label": "c"}], "solution": ["Not one-to-one, but square and double: $T(-u,-v)=((-u)^2-(-v)^2,\\,2(-u)(-v))=T(u,v)$, so every point except the origin has two preimages, and $T$ is not one-to-one on $\\mathbb R^2$. In polar form, $u^2-v^2=\\varrho^2\\cos2\\psi$ and $2uv=\\varrho^2\\sin2\\psi$, so $T$ squares the radius and doubles the angle. On the first quadrant $0\\le\\psi\\le\\pi/2$, the doubled angle covers $[0,\\pi]$ only once, so $T$ is one-to-one there, and it sends the ray at angle $\\psi$ to the ray at angle $2\\psi$.", "Edges of the unit square: The edge $v=0$ goes to $(u^2,0)$, the segment $[0,1]$ of the $x$-axis, and the edge $u=0$ goes to $(-v^2,0)$, the segment $[-1,0]$. On the edge $u=1$, $x=1-v^2$ and $y=2v$, which gives $x=1-y^2/4$. On the edge $v=1$, $x=u^2-1$ and $y=2u$, which gives $x=y^2/4-1$. Both parabolas run over $0\\le y\\le2$ and have their focus at the origin, where the Sun sits. In general the line $u=c$ goes to $x=c^2-y^2/(4c^2)$, a parabola with focus at the origin and vertex $(c^2,0)$. So $u=\\sqrt q$ goes to the comet’s orbit, with perihelion $(q,0)$.", "Jacobian and area: $J=(2u)(2u)-(-2v)(2v)=4(u^2+v^2)$, which is positive except at the origin. Because $T$ is one-to-one on the square, the area of its image is $\\int_0^1\\!\\int_0^1 4(u^2+v^2)\\,du\\,dv=\\tfrac43+\\tfrac43=\\tfrac83$ AU$^2$.", "The region $D^*$ and the hypotheses: The squared distance from the Sun is $x^2+y^2=(u^2+v^2)^2$, so the distance is $u^2+v^2$. On the orbit $u=\\sqrt q$, a distance of 1 AU gives $v=\\sqrt{1-q}$. The Sun–perihelion segment comes from $v=0$, the orbit arc from $u=\\sqrt q$, and the Sun–comet segment from the ray $v=ku$ with $k=\\sqrt{(1-q)/q}$. So $D^*$ is the triangle with vertices $(0,0)$, $(\\sqrt q,0)$, and $(\\sqrt q,\\sqrt{1-q})$, described by $0\\le u\\le\\sqrt q$, $0\\le v\\le ku$; integrating in $v$ first needs only one double integral. Hypotheses: $T$ is $C^1$, it is one-to-one on the first quadrant, $T(D^*)=D$, and $J\\ne0$ except at one point.", "Time to reach 1 AU: The area of $D$ is $\\int_0^{\\sqrt q}\\!\\int_0^{ku}4(u^2+v^2)\\,dv\\,du=\\int_0^{\\sqrt q}4u^3(k+k^3/3)\\,du=q^2(k+k^3/3)=\\tfrac{qk(2q+1)}{3}$, which is about $0.2416$ AU$^2$ for $q=0.2947$. Dividing by the sweep rate $\\pi\\sqrt{2q}\\approx2.412$ AU$^2$/yr gives $0.1001$ yr $\\approx36.6$ days, so the model comet reaches 1 AU around August 9. JPL’s ephemeris gives 36.60 days, less than an hour later."], "reflection": "JPL’s ephemeris puts the real NEOWISE 1 AU from the Sun 36.60 days after perihelion, within an hour of the model. Yet the real orbit is an ellipse that takes about 6800 years to go around. Why does a parabola work so well here, and where would it fail badly?", "extension": false, "id": "w04-p3", "discussionSolution": "Near the Sun the ellipse and the parabola are almost the same curve, traveled at almost the same speed; far from the Sun they part ways. The speed is set by v² = GM(2/r − 1/a). With a ≈ 358 AU, the term 1/a ≈ 0.003 per AU is tiny next to 2/r ≥ 2 per AU, so inside 1 AU the two speeds differ by about 0.1% and the sweep rates agree almost exactly. Far out, the parabola escapes to infinity, while the real comet turns around about 717 AU from the Sun and returns in some 6800 years.", "modelSpec": {"data": ["Perihelion distance of NEOWISE: $0.29465$ AU, used as $q=0.2947$ AU", "Eccentricity: $0.99918$", "Time of perihelion: 2020 July 3.68"], "assume": ["The orbit is an exact parabola with the Sun at its focus.", "The pulls of the planets are ignored.", "By Kepler’s second law, the Sun–comet line sweeps area at the constant rate $\\pi\\sqrt{2q}$ AU$^2$ per year (using $GM_\\odot=4\\pi^2$ AU$^3$/yr$^2$).", "One year is $365.25$ days."], "model": ["Sun at the origin, perihelion at $(q,0)$, distances in AU", "Levi-Civita map $T(u,v)=(u^2-v^2,\\ 2uv)$ from the $uv$-plane to the $xy$-plane", "Swept region $D$: bounded by the Sun–perihelion segment, the orbit, and the Sun–comet segment at the moment the comet is $1$ AU from the Sun"]}, "photo": {"alt": "Comet NEOWISE against a starry sky, with a bright greenish head, a broad cream-colored dust tail, and a faint, narrow blue ion tail", "credit": "Davrou (David Rousseau)", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:2020-07-21_-_Neowise_-_D_Rousseau.jpg", "file": "w04-p3.jpg"}, "figure": {"alt": "Left: the uv-plane with the vertical line u equals root q. Right: the xy-plane with the Sun at the origin, the comet’s parabola opening to the left through perihelion, the dashed 1 AU circle, a segment from the Sun to the point where the comet is 1 AU away, and the shaded region D between the Sun–perihelion segment, the orbit, and that segment", "caption": "Left: the line $u=\\sqrt q$ in the $uv$-plane. Right: its image under $T$, the comet’s parabola with the Sun at its focus, together with the 1 AU circle (dashed) and the region $D$ swept from perihelion until the comet is 1 AU from the Sun.", "file": "w04-p3"}}, {"title": "How a computer makes bell curves", "context": "Weather ensembles, bank stress tests, and simulated particle collisions all need random numbers that follow the bell-shaped normal distribution. A computer’s basic random number generator, however, only produces numbers spread evenly (uniformly) between 0 and 1. In 1958 George Box and Mervin Muller published a short recipe that turns two uniform numbers into two independent normal numbers. Geometrically, the recipe bends the unit square onto the whole plane so that the points pile up into a two-dimensional bell curve. It is a change of variables. Why does it produce the bell curve, and how likely is a generated point to land within distance 2 of the center?", "model": "The Box–Muller formulas are published; treating the computer’s numbers as truly random and uniform is an idealization.", "sources": ["boxmuller"], "work": ["Write the inverse map $(x,y)\\mapsto(u,v)$ using polar coordinates of $(x,y)$.", "Find where $T$ fails to be one-to-one on $(0,1]\\times[0,1]$, explain why that is harmless, and describe $T(u,v)$ as $u\\to0$.", "Explain why the chance that $T(u,v)$ lands in a region $D$ is the area of its preimage $D^*$. Write that area as $\\iint_D\\left|\\partial(u,v)/\\partial(x,y)\\right|dx\\,dy$, transforming the region, integrand, and area element together.", "After (c): Explain why $X=\\sigma_1x$, $Y=\\sigma_2y$ multiplies areas by $\\sigma_1\\sigma_2$.", "After (c): Use this scaling, then polar coordinates, to show that the “2-sigma” ellipse $X^2/\\sigma_1^2+Y^2/\\sigma_2^2\\le4$ has the same probability as the disk in (c)."], "questions": [{"prompt": "Enter the forward Jacobian $\\dfrac{\\partial(x,y)}{\\partial(u,v)}$ of the Box–Muller map $T$ as a function of u and v. Keep its sign: it may be negative.", "expected": "-2*pi/u", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Write R = √(−2 ln u), so x = R cos(2πv) and y = R sin(2πv), and use dR/du = −1/(uR).", "x_u = −cos(2πv)/(uR) and x_v = −2πR sin(2πv). In x_u y_v − x_v y_u, the R cancels and cos² + sin² = 1."], "id": "w04-p4-a", "label": "a"}, {"prompt": "The generated points $(x,y)$ have probability density $\\left|\\dfrac{\\partial(u,v)}{\\partial(x,y)}\\right|$. Using part (a), enter this density as a function of x and y.", "expected": "exp(-(x^2+y^2)/2)/(2*pi)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The inverse Jacobian is the reciprocal of the forward Jacobian from (a); take its absolute value.", "Then write u in terms of x and y, using x² + y² = −2 ln u."], "id": "w04-p4-b", "label": "b"}, {"prompt": "What is the probability that a generated point $(x,y)$ lies within distance 2 of the origin, that is, in the disk $x^2+y^2\\le4$?", "expected": "1-exp(-2)", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["The probability is the area of the preimage of the disk. Which values of u give a radius √(−2 ln u) of at most 2?", "Or integrate the density from (b) in polar coordinates, from r = 0 to r = 2."], "id": "w04-p4-c", "label": "c"}], "solution": ["Inverse map: Since $x^2+y^2=-2\\ln u$, the inverse is $u=e^{-(x^2+y^2)/2}$ and $v=\\theta/(2\\pi)$, where $\\theta$ is the polar angle of $(x,y)$. The map is one-to-one except that $u=1$ sends every $v$ to the origin and the edges $v=0$ and $v=1$ give the same ray. These sets have zero area, so they do not affect any integral. As $u\\to0$ the radius $\\sqrt{-2\\ln u}\\to\\infty$, so the image is the whole plane and integrals over it are improper.", "Forward Jacobian: With $R=\\sqrt{-2\\ln u}$, $x_u=-\\dfrac{\\cos2\\pi v}{uR}$, $x_v=-2\\pi R\\sin2\\pi v$, $y_u=-\\dfrac{\\sin2\\pi v}{uR}$, and $y_v=2\\pi R\\cos2\\pi v$. So $\\dfrac{\\partial(x,y)}{\\partial(u,v)}=-\\dfrac{2\\pi}{u}(\\cos^22\\pi v+\\sin^22\\pi v)=-\\dfrac{2\\pi}{u}$. The minus sign means $T$ reverses orientation; area scaling uses $2\\pi/u$.", "Probability rule and density: The chance that $T(u,v)$ lands in $D$ is the area of the preimage $D^*$. Changing variables, that area is $\\iint_D\\left|\\dfrac{\\partial(u,v)}{\\partial(x,y)}\\right|dx\\,dy$, so the density is the absolute value of the inverse Jacobian. By the reciprocal rule, $\\left|\\dfrac{\\partial(u,v)}{\\partial(x,y)}\\right|=\\dfrac{u}{2\\pi}=\\dfrac{1}{2\\pi}e^{-(x^2+y^2)/2}=\\dfrac{e^{-x^2/2}}{\\sqrt{2\\pi}}\\cdot\\dfrac{e^{-y^2/2}}{\\sqrt{2\\pi}}$. This is a product of two standard normal densities, so $x$ and $y$ are two independent standard normal numbers.", "Probability within distance 2: $P=\\iint_{x^2+y^2\\le4}\\dfrac{e^{-(x^2+y^2)/2}}{2\\pi}\\,dA=\\int_0^{2\\pi}\\!\\int_0^2\\dfrac{e^{-r^2/2}}{2\\pi}\\,r\\,dr\\,d\\theta=1-e^{-2}\\approx0.865$. Equivalently, the preimage of the disk is the strip $e^{-2}\\le u\\le1$, which has area $1-e^{-2}$.", "The 2-sigma ellipse: The scaling $X=\\sigma_1x$, $Y=\\sigma_2y$ is a diagonal linear map with determinant $\\sigma_1\\sigma_2$, so it multiplies areas by $\\sigma_1\\sigma_2$, and it sends the disk $x^2+y^2\\le4$ onto the ellipse $X^2/\\sigma_1^2+Y^2/\\sigma_2^2\\le4$. The density of $(X,Y)$ is $\\dfrac{1}{2\\pi\\sigma_1\\sigma_2}e^{-(X^2/\\sigma_1^2+Y^2/\\sigma_2^2)/2}$; changing variables multiplies it by $\\sigma_1\\sigma_2$ and gives back the disk integral above, so the answer is again $1-e^{-2}$. A two-dimensional “2-sigma” ellipse holds only 86.5% of the points, not the familiar one-dimensional 95%."], "reflection": "The forward Jacobian in (a) is negative. Why does the probability density use its absolute value, and what would go wrong without it?", "extension": false, "id": "w04-p4", "discussionSolution": "Because probability, like area, cannot be negative. The sign of the Jacobian only records that the map reverses orientation: it flips the square over as it bends it. Without the absolute value the density would be negative everywhere, and the total probability would come out as −1.", "modelSpec": {"data": ["Box–Muller method: from uniform $u,v$ in $(0,1)$, $x=\\sqrt{-2\\ln u}\\cos2\\pi v$ and $y=\\sqrt{-2\\ln u}\\sin2\\pi v$"], "assume": ["The computer’s numbers are truly random, so $(u,v)$ is spread uniformly over the unit square and the probability of a set of inputs equals its area."], "model": ["Box–Muller map $T(u,v)=(x,y)$ on $(0,1]\\times[0,1]$", "Probability that $T(u,v)$ lies in a region $D$ $=$ area of the set of inputs $(u,v)$ that land in $D$"]}, "figure": {"alt": "Left: the unit square in the uv-plane with four colored vertical lines at u = 0.1, 0.3, 0.6, and 0.9 and two dashed horizontal lines at v = 0.125 and 0.25. Right: the xy-plane with four circles about the origin in the same colors, a dashed ray, and 400 faint sample points crowded near the origin and thinning out farther away", "caption": "The vertical lines $u=0.9,\\ 0.6,\\ 0.3,\\ 0.1$ in the square (left) become circles about the origin (right), and the dashed lines $v=0.125$ and $v=0.25$ become rays. The 400 sample points $T(u,v)$ crowd near the origin and thin out farther away.", "file": "w04-p4"}}, {"title": "Why Greenland looks as big as Africa", "context": "On the familiar Mercator world map, Greenland looks about as large as Africa. Yet the Democratic Republic of the Congo alone, on the equator, is slightly larger than Greenland. A map projection sends each point of the globe, given by its longitude and latitude, to a point of a flat map. Gerardus Mercator designed his projection so that sailors could steer by straight lines, and that choice stretches areas near the poles. By how much does the Mercator map enlarge areas at Greenland’s latitude, and can a different map keep areas true?", "model": "The projection formulas and national areas are published values; the spherical Earth and one representative latitude for each country are simplifications.", "sources": ["snyder", "unareas"], "work": ["Before (b): Explain why (map Jacobian)$/\\cos\\phi$ is the map’s areal scale factor, using the sphere’s area element $\\cos\\phi\\,d\\lambda\\,d\\phi$.", "Decide whether the Mercator map is one-to-one on $(-\\pi,\\pi)\\times(-\\pi/2,\\pi/2)$, and say what happens to the poles.", "After (a): Repeat the Jacobian calculation for the cylindrical equal-area map $x=\\lambda$, $y=\\sin\\phi$, and explain its name."], "questions": [{"prompt": "With $R=1$, enter the Mercator Jacobian $\\dfrac{\\partial(x,y)}{\\partial(\\lambda,\\phi)}$ as a function of phi.", "expected": "1/cos(phi)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["x = λ does not depend on φ, and y does not depend on λ, so the Jacobian is y_φ.", "Differentiate ln tan(π/4 + φ/2) with the chain rule, then use 2 sin A cos A = sin 2A."], "id": "w04-p5-a", "label": "a"}, {"prompt": "Using part (a), by what factor does the Mercator map multiply areas at latitude $72^\\circ$?", "expected": "1/cos(72*pi/180)^2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Divide the Jacobian by the sphere’s area factor cos φ.", "The ratio is sec² φ; evaluate it at φ = 72°."], "id": "w04-p5-b", "label": "b"}, {"prompt": "Treat all of Greenland as lying at latitude $72^\\circ$ and all of DR Congo at the equator. How many times larger than DR Congo does Greenland appear on the Mercator map?", "expected": "2166086/cos(72*pi/180)^2/2344858", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Multiply each true area by its areal scale factor, then divide.", "At the equator the factor is 1."], "id": "w04-p5-c", "label": "c"}], "solution": ["Mercator Jacobian: $x_\\lambda=1$, $x_\\phi=0$, $y_\\lambda=0$, and $y_\\phi=\\dfrac{\\tfrac12\\sec^2(\\pi/4+\\phi/2)}{\\tan(\\pi/4+\\phi/2)}=\\dfrac{1}{\\sin(\\pi/2+\\phi)}=\\sec\\phi$, so $J=\\sec\\phi$.", "Areal scale factor: A small patch of Earth has area about $\\cos\\phi\\,\\Delta\\lambda\\,\\Delta\\phi$, and its image on the map has area about $|J|\\,\\Delta\\lambda\\,\\Delta\\phi$. So the map multiplies areas by $\\sec\\phi/\\cos\\phi=\\sec^2\\phi$, as Snyder states; at $72^\\circ$ this is about 10.47. The map is one-to-one on the open rectangle, but $y\\to\\pm\\infty$ at the poles, so the poles never appear on the map.", "Greenland versus DR Congo: The apparent ratio is $\\dfrac{2{,}166{,}086\\times10.47}{2{,}344{,}858\\times1}\\approx9.7$. Greenland looks almost ten times larger than DR Congo, although it is about 8% smaller.", "Equal-area map: For $y=\\sin\\phi$, $J=\\cos\\phi$, exactly the sphere’s factor. The areal scale factor is 1 everywhere, so the map is equal-area, at the price of squashed shapes near the poles."], "reflection": "Mercator’s map preserves angles, which made it ideal for navigation. Can a map from the sphere to the plane preserve both angles and areas? What does the Jacobian say?", "extension": true, "id": "w04-p5", "discussionSolution": "No. A map that preserves angles stretches lengths equally in all directions at each point, by some factor k, so it multiplies area by k². Preserving area too would force k = 1, so the map would preserve all lengths. A sphere cannot be flattened without changing lengths, because its curvature is not zero, so every world map must trade shape against area.", "modelSpec": {"data": ["Surface area of Greenland: $2{,}166{,}086$ km$^2$", "Surface area of the Democratic Republic of the Congo: $2{,}344{,}858$ km$^2$", "Mercator (sphere): $x=R\\lambda$, $y=R\\ln\\tan(\\pi/4+\\phi/2)$", "Cylindrical equal-area (sphere): $x=R\\lambda$, $y=R\\sin\\phi$"], "assume": ["Earth is a sphere, and we take $R=1$.", "All of Greenland is treated as lying at latitude $72^\\circ$ N, and all of DR Congo at the equator."], "model": ["Map $(\\lambda,\\phi)\\mapsto(x,y)$ on $-\\pi<\\lambda<\\pi$, $-\\pi/2<\\phi<\\pi/2$, with longitude $\\lambda$ and latitude $\\phi$ in radians", "Sphere area element (with $R=1$): $\\cos\\phi\\,d\\lambda\\,d\\phi$"]}, "figure": {"alt": "Mercator grid of meridians and parallels; the parallels, drawn every 15 degrees, spread farther apart toward the poles. A band for the latitudes of Greenland, about 60 to 84 degrees north, and a band for the latitudes of DR Congo, about 5 degrees north to 13 degrees south, are shaded", "caption": "Mercator’s map with parallels every $15^\\circ$: equal steps in latitude take up more and more map height toward the poles. Shaded: the latitude bands of Greenland and of DR Congo.", "file": "w04-p5"}}]}, {"week": 5, "title": "Balance points and blind spots", "subtitle": "The Balancing Act", "skills": ["Find centers of mass of planar regions by symmetry, vertex averages, and moments", "Predict how a non-uniform density moves the balance point, then compute it", "Set up integrals over cones and balls in cylindrical and spherical coordinates, in more than one order", "Derive the volume factors r and ρ² sin φ, and use them for volumes, masses, and moments", "Evaluate improper integrals by exhaustion, and test power laws for convergence in one, two, and n dimensions"], "formulas": ["$\\bar x=\\dfrac{1}{M}\\iint x\\,\\delta\\,dA,\\quad \\bar y=\\dfrac{1}{M}\\iint y\\,\\delta\\,dA,\\quad M=\\iint\\delta\\,dA$", "Cylindrical: $dV=r\\,dr\\,d\\theta\\,dz$. Spherical: $x=\\rho\\sin\\phi\\cos\\theta,\\ y=\\rho\\sin\\phi\\sin\\theta,\\ z=\\rho\\cos\\phi$, with $\\rho\\ge0$ and $0\\le\\phi\\le\\pi$ measured down from the positive $z$-axis", "For $f\\ge0$: $\\iint_{\\mathbb R^2}f\\,dA=\\lim_{n\\to\\infty}\\iint_{D_n}f\\,dA$ for any regions $D_n$ that exhaust the plane"], "sources": ["gatewayarch", "earthfacts", "fmiradar", "walker1977", "taipeidamper"], "problems": [{"title": "The Gateway Arch balances on thin air", "context": "The Gateway Arch in St. Louis is a stainless-steel arch 630 feet tall and 630 feet wide. Each leg has a cross-section shaped like an equilateral triangle, 54 feet on a side at the ground and 17 feet at the top. An object’s center of mass is its balance point: the average position of all its mass. For a thin curved band like the arch, that point need not lie in the material at all. Where is the arch’s center of mass, and how do the thick bases of the legs move it?", "model": "The arch’s width, height, and leg taper are published, while the parabolic outlines and the thickness-weighted density are assumptions.", "sources": ["gatewayarch"], "work": ["Explain, without integrating, why $\\bar x=0$ for both densities.", "Locate the centroid of a leg’s cross-section, the equilateral triangle with vertices $(0,0)$, $(54,0)$, $(27,27\\sqrt3)$ (ft), by averaging the vertices, with no integrals.", "Before (b): Describe $A$ as (region under the outer parabola) minus (region under the inner parabola), and explain why its mass and moment are differences.", "Before (c): Predict whether weighting by leg thickness moves $\\bar y$ up or down from part (b).", "After (c): Sketch the arch with $\\bar y$ marked, and explain how a body can balance at a point where it has no material."], "questions": [{"prompt": "Start with one parabolic region of uniform density: the region under $y=h(1-x^2/w^2)$ and above $y=0$. Enter the height $\\bar y$ of its center of mass as a function of h and w.", "expected": "2*h/5", "units": "ft", "kind": "expression", "tolerance": 1e-05, "hints": ["With uniform density, ȳ = M_x/M, where M is the area and M_x = ∫ (1/2)(top height)² dx over [−w, w].", "The area is 4hw/3 and the moment is M_x = 8h²w/15."], "id": "w05-p1-a", "label": "a"}, {"prompt": "Using the mass and moment from part (a), find $\\bar y$, in feet above the ground, for the uniform arch region $A$.", "expected": "2/5*(630^2*315-613^2*261)/(630*315-613*261)", "units": "ft", "kind": "number", "tolerance": 1e-05, "hints": ["Subtract the inner region’s mass and moment from the outer region’s, then divide.", "Each region has mass 4hw/3 and moment 8h²w/15; use h = 630, w = 315 for the outer region and h = 613, w = 261 for the inner one."], "id": "w05-p1-b", "label": "b"}, {"prompt": "Now weight the arch by its leg thickness: density $\\delta=54-\\tfrac{37}{630}y$. Find $\\bar y$ for $A$, in feet above the ground.", "expected": "406441825784/1768433009", "units": "ft", "kind": "number", "tolerance": 1e-05, "hints": ["You need ∬ y^k dA over each parabolic region for k = 0, 1, 2; for the region under y = h(1 − x²/w²) these are 4wh/3, 8wh²/15, and 32wh³/105.", "Then M = 54·(k=0 term) − (37/630)·(k=1 term), with the inner region subtracted, and similarly for the moment."], "decimals": 1, "id": "w05-p1-c", "label": "c"}], "solution": ["Symmetry: the reflection $x\\mapsto-x$ maps $A$ to itself and leaves $\\delta$ unchanged, because $\\delta$ depends only on $y$. So $x\\delta$ is odd in $x$, its integral over $A$ is zero, and $\\bar x=0$ for both densities. Triangle centroid: averaging the vertices gives $\\big(\\tfrac{0+54+27}{3},\\tfrac{0+0+27\\sqrt3}{3}\\big)=(27,9\\sqrt3)\\approx(27,15.6)$ ft, one third of the way up from the base.", "One parabolic region: $M=\\int_{-w}^{w}h(1-\\tfrac{x^2}{w^2})\\,dx=\\tfrac43hw$ and $M_x=\\int_{-w}^{w}\\tfrac12h^2(1-\\tfrac{x^2}{w^2})^2\\,dx=\\tfrac{8}{15}h^2w$, so $\\bar y=\\tfrac25h$, whatever the width $w$.", "Arch as a difference: $A$ is the outer region with the inner region removed, so its mass and moment are differences. This gives $M_A=\\tfrac43(630\\cdot315-613\\cdot261)=51{,}276$ ft$^2$ and $M_{x,A}=\\tfrac8{15}(630^2\\cdot315-613^2\\cdot261)\\approx1.4372\\times10^7$ ft$^3$, so $\\bar y\\approx280.3$ ft.", "Thickness weighting: the legs are thickest at the ground, so the weighting favors low points and $\\bar y$ should drop. On each region, $\\iint y^k\\,dA$ equals $\\tfrac43wh,\\ \\tfrac8{15}wh^2,\\ \\tfrac{32}{105}wh^3$ for $k=0,1,2$. Subtracting the inner region, $M=\\iint_A(54-\\tfrac{37}{630}y)\\,dA$ and $M_x=\\iint_Ay(54-\\tfrac{37}{630}y)\\,dA$ give $\\bar y\\approx229.8$ ft, about 50 ft lower than in part (b).", "Interpretation: at $x=0$ the steel lies between 613 and 630 ft, so both balance points, $(0,280.3)$ and $(0,229.8)$ ft, sit in the empty space under the arch. The center of mass is an average of positions, and the average of points on a curved band can lie off the band."], "reflection": "The NPS also says there is concrete between the skins of the legs up to a height of 300 ft. Would that concrete move the balance point up or down, and why would an arch builder care where the weight is?", "extension": false, "id": "w05-p1", "discussionSolution": "Down. The concrete lies below 300 ft, and most of it sits well below the balance point of about 230 ft, so adding it pulls the balance point lower. A low center of mass makes a structure more stable against wind, and builders need to know where the weight is to size the foundations and to keep the half-built legs from tipping during construction.", "modelSpec": {"data": ["Outer width $630$ ft; maximum height $630$ ft", "Leg cross-section: equilateral triangle, $54$ ft per side at the base and $17$ ft at the top"], "assume": ["The outer edge is the parabola $y=630(1-x^2/315^2)$.", "The inner edge is the parabola $y=613(1-x^2/261^2)$, so the legs are 54 ft wide at the ground and 17 ft thick at the top.", "In part (c), the density is proportional to leg thickness, falling linearly from 54 at $y=0$ to 17 at $y=630$."], "model": ["The arch is the flat region $A$ between the two parabolas, above $y=0$; $x$ and $y$ are in feet, with $y$ the height above the ground", "Density: uniform in part (b); $\\delta=54-\\tfrac{37}{630}y$ in part (c)"]}, "photo": {"alt": "The stainless-steel Gateway Arch against a blue sky, its legs tapering toward the top, with visitors walking on a path beneath it", "credit": "Lewis Hulbert", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Gateway_Arch,_St._Louis.jpg", "file": "w05-p1.jpg"}, "figure": {"alt": "Front view of the model arch, drawn to scale: a tan band labeled A between two nested parabolas, 630 ft tall and 630 ft wide, with each leg 54 ft wide at the ground and 17 ft thick at the top. An inset shows the leg cross-section, an equilateral triangle with 54 ft sides.", "caption": "The model arch $A$, in feet: the band between the outer parabola $y=630(1-x^2/315^2)$ and the inner parabola $y=613(1-x^2/261^2)$. Inset: a leg’s cross-section at the base, an equilateral triangle with 54 ft sides. Notice how much empty space the band encloses.", "file": "w05-p1"}}, {"title": "Weighing Earth’s core without digging", "context": "No borehole has come anywhere near the center of Earth, which lies 6371 km below our feet. Yet two numbers measured from outside show that the center is far denser than surface rock. One is Earth’s mass. The other is its moment of inertia, which measures how hard it is to change a body’s spin; it is small when the mass sits close to the spin axis. Astronomers find it from how Earth’s spin axis responds to the pull of the Sun and Moon. What do these two numbers say about how Earth’s density changes with depth?", "model": "Earth’s mass, radius, mean density, and moment-of-inertia factor are published, while the smooth quadratic density profile is a model (the real Earth has distinct layers).", "sources": ["earthfacts"], "work": ["Explain why a small spherical box with sides $\\Delta\\rho$, $\\Delta\\phi$, $\\Delta\\theta$ has edges $\\Delta\\rho$, $\\rho\\,\\Delta\\phi$, and $\\rho\\sin\\phi\\,\\Delta\\theta$, and derive the volume factor $\\rho^2\\sin\\phi$.", "Explain why, for a density that depends only on $\\rho$, every mass or moment integral over the ball reduces to one $\\rho$-integral times an angular factor.", "After (b): Find $I/(MR^2)$ for a uniform ball. Is the measured 0.3308 bigger or smaller, and what does that say about where Earth’s mass is?", "Check the published data: compute the work per kilogram to lift a mass from the surface to infinity, $\\int_R^\\infty GM/r^2\\,dr$, explain why this improper integral converges, and recover the escape speed."], "questions": [{"prompt": "Measure distances in Earth radii, so Earth is the ball $\\rho\\le1$. Enter the mass of the ball with density $\\delta=a-b\\rho^2$ as a function of a and b.", "expected": "4*pi*(a/3-b/5)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Use spherical coordinates; for a density that depends only on ρ, the two angle integrals together contribute 4π.", "With dV = ρ² sin φ dρ dφ dθ, the radial integral is ∫₀¹ (a − bρ²)ρ² dρ."], "id": "w05-p2-a", "label": "a"}, {"prompt": "Enter the model’s moment-of-inertia factor $I/(MR^2)$ as a function of a and b, where $I$ is the moment of inertia about the spin axis (the $z$-axis) and $R=1$.", "expected": "2/3*(a/5-b/7)/(a/3-b/5)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The distance to the spin axis is ρ sin φ, so I = ∭ (a − bρ²)(ρ sin φ)² ρ² sin φ dρ dφ dθ.", "∫₀^π sin³φ dφ = 4/3; then divide I by the mass from part (a)."], "id": "w05-p2-b", "label": "b"}, {"prompt": "Choose a and b so that the model matches the published mean density, 5513 kg/m³ = 5.513 g/cm³, and the published moment-of-inertia factor, 0.3308. What central density a does the model give, in g/cm³?", "expected": "5.513/(1-3*0.79326608/5)", "units": "g/cm³", "kind": "number", "tolerance": 1e-05, "hints": ["The factor depends only on k = b/a; solve (2/3)(1/5 − k/7)/(1/3 − k/5) = 0.3308 for k.", "Mean density = M/V = 3(a/3 − b/5) = a(1 − 3k/5)."], "decimals": 1, "id": "w05-p2-c", "label": "c"}], "solution": ["Volume factor: the box’s edges are a radial step $\\Delta\\rho$, an arc $\\rho\\,\\Delta\\phi$ of a circle of radius $\\rho$, and an arc $\\rho\\sin\\phi\\,\\Delta\\theta$ of a circle of radius $\\rho\\sin\\phi$ (the distance to the $z$-axis). Multiplying them gives $dV=\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta$. For a density that depends only on $\\rho$, the angles separate and contribute $\\int_0^{2\\pi}\\!\\int_0^\\pi\\sin\\phi\\,d\\phi\\,d\\theta=4\\pi$.", "Mass and moment: $M=4\\pi\\int_0^1(a-b\\rho^2)\\rho^2\\,d\\rho=4\\pi(\\tfrac a3-\\tfrac b5)$. The squared distance to the spin axis is $\\rho^2\\sin^2\\phi$, so $I=\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^1(a-b\\rho^2)\\rho^4\\sin^3\\phi\\,d\\rho\\,d\\phi\\,d\\theta=\\tfrac{8\\pi}{3}(\\tfrac a5-\\tfrac b7)$, which gives $\\dfrac{I}{MR^2}=\\dfrac23\\cdot\\dfrac{a/5-b/7}{a/3-b/5}$.", "Uniform check: a uniform ball ($b=0$) gives $I/(MR^2)=0.4$. Earth’s $0.3308$ is smaller, so its mass is concentrated toward the center.", "Fitting the data: with $k=b/a$, the equation $\\tfrac23(\\tfrac15-\\tfrac k7)=0.3308(\\tfrac13-\\tfrac k5)$ gives $k\\approx0.7933$. The mean density is $M/V=a(1-\\tfrac35k)$, so $a=5.513/(1-0.6k)\\approx10.5$ g/cm$^3$ at the center and $a(1-k)\\approx2.2$ g/cm$^3$ at the surface, close to surface rock. A center this much denser than surface rock points to a heavy (iron) core.", "Escape check: $\\int_R^\\infty\\dfrac{GM}{r^2}\\,dr=\\lim_{T\\to\\infty}\\Big[-\\dfrac{GM}{r}\\Big]_R^T=\\dfrac{GM}{R}\\approx62.6$ km$^2$/s$^2$, that is, about $6.26\\times10^7$ J per kilogram. It is finite because the exponent 2 is greater than 1. Setting $\\tfrac12v^2=GM/R$ gives $v=\\sqrt{2\\times398{,}600/6371}\\approx11.19$ km/s, matching NASA’s 11.186 km/s."], "reflection": "Suppose gravity weakened like 1/r instead of 1/r². Could anything escape Earth? Which one-variable convergence fact decides?", "extension": false, "id": "w05-p2", "discussionSolution": "No. If the pull per kilogram fell like $1/r$, the work to reach distance $T$ would grow like $\\ln(T/R)$, without bound, so no finite launch speed would be enough. The deciding fact is that $\\int_1^\\infty r^{-p}\\,dr$ converges exactly when $p>1$; gravity’s $p=2$ is what makes escape possible.", "modelSpec": {"data": ["Radius $R=6371$ km; mass $5.9722\\times10^{24}$ kg; mean density $5513$ kg/m$^3$", "Moment of inertia factor $I/(MR^2)=0.3308$", "$GM=398{,}600$ km$^3$/s$^2$; escape velocity $11.186$ km/s"], "assume": ["Earth is a ball whose density depends only on the distance $\\rho$ from the center.", "The density is a quadratic function of $\\rho$."], "model": ["Density $\\delta(\\rho)=a-b\\rho^2$, with $\\rho$ in Earth radii ($0\\le\\rho\\le1$) and $a$, $b$ in g/cm$^3$", "$M$ is the mass and $I$ the moment of inertia about the spin axis (the $z$-axis)"]}, "figure": {"alt": "Cross-section of Earth through its axis, shaded green by the model density and darkest at the center. The angle phi is marked from the vertical z-axis, and a small spherical box has edges labeled delta rho and rho delta phi.", "caption": "Earth as a ball whose density depends only on $\\rho$; darker shading means denser. A small spherical box has edges $\\Delta\\rho$, $\\rho\\,\\Delta\\phi$, and $\\rho\\sin\\phi\\,\\Delta\\theta$, with the third edge pointing out of the page.", "file": "w05-p2"}}, {"title": "The radar’s blind cone", "context": "Finland’s weather radars scan the sky by turning their antennas in full circles, tilting up a little after each turn. The tilt above the horizon is called the elevation angle. In the Finnish schedule the steepest full-circle scan has a 45° elevation, so the air inside an upside-down cone directly above each radar is never sampled. This blind region is called the cone of silence. How much air is in it, how high is its center, and what fraction of the sky within the radar’s 100 km range does it hide? How would a different top tilt change these answers?", "model": "The 45° top elevation and the 100 km range are published, while the flat ground and straight-line beams are simplifications.", "sources": ["fmiradar"], "work": ["Sketch a side view and describe the blind region below height $h$ in cylindrical coordinates with $r$ innermost, then $z$ innermost.", "After (a): Check your volume with the cone volume $\\tfrac13\\pi R^2h$.", "After (b): For any top tilt $\\alpha$ (cone $z=r\\tan\\alpha$, $R=h\\cot\\alpha$), show that $\\bar z$ does not depend on $R$.", "Before (c): Write the cone $z=\\sqrt{x^2+y^2}$ as an equation in $\\phi$, and describe the blind region within 100 km in spherical coordinates.", "Explain why one radar sample’s volume, $\\Delta\\rho$ long and $\\Delta\\phi$ by $\\Delta\\theta$ wide, grows like $\\rho^2$."], "questions": [{"prompt": "With the 45° top tilt, find the volume of the blind region below height $h$, with $h$ in km. Enter it as a function of h.", "expected": "pi*h^3/3", "units": "km³", "kind": "expression", "tolerance": 1e-05, "hints": ["With a 45° top tilt the blind region is r ≤ z, so at height z it is a disk of radius z.", "Integrate r dr dθ dz with 0 ≤ r ≤ z, 0 ≤ z ≤ h, and 0 ≤ θ ≤ 2π."], "id": "w05-p3-a", "label": "a"}, {"prompt": "Treat the blind region below height $h$ as a solid of uniform density. Enter the height $\\bar z$ of its center of mass, in km, as a function of h.", "expected": "3*h/4", "units": "km", "kind": "expression", "tolerance": 1e-05, "hints": ["Slice the region horizontally: the slice at height z is a disk of area πz².", "The moment is the integral of z · πz² from 0 to h; divide it by the volume from part (a)."], "id": "w05-p3-b", "label": "b"}, {"prompt": "Within range 100 km, what fraction of the volume of the half-ball of sky above the radar ($\\rho\\le100$ km, $z\\ge0$) lies in the blind cone?", "expected": "1-sqrt(2)/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["In spherical coordinates the blind region is 0 ≤ ρ ≤ 100, 0 ≤ φ ≤ π/4, 0 ≤ θ ≤ 2π.", "The half-ball has the same ρ and θ limits but 0 ≤ φ ≤ π/2, so only the φ integrals differ."], "id": "w05-p3-c", "label": "c"}], "solution": ["Blind region: at a $45^\\circ$ top tilt the blind region is $z\\ge\\sqrt{x^2+y^2}$, that is, $r\\le z$. With $r$ innermost: $0\\le\\theta\\le2\\pi$, $0\\le z\\le h$, $0\\le r\\le z$. With $z$ innermost: $0\\le\\theta\\le2\\pi$, $0\\le r\\le h$, $r\\le z\\le h$.", "Volume: $V=\\int_0^{2\\pi}\\!\\int_0^h\\!\\int_0^z r\\,dr\\,dz\\,d\\theta=\\tfrac{\\pi h^3}{3}$ km$^3$, which matches $\\tfrac13\\pi R^2h$ with $R=h$.", "Center of mass: $\\bar z=\\dfrac{\\int_0^h z\\cdot\\pi z^2\\,dz}{\\pi h^3/3}=\\dfrac{3h}{4}$. For a top tilt $\\alpha$ the slice at height $z$ has area $\\pi z^2\\cot^2\\alpha$. The factor $\\cot^2\\alpha$ (equivalently $R^2/h^2$) cancels, so $\\bar z=3h/4$ for every $\\alpha$ and every $R$.", "Spherical description: $z=\\sqrt{x^2+y^2}$ becomes $\\rho\\cos\\phi=\\rho\\sin\\phi$, so $\\phi=\\pi/4$. The blind region within 100 km is $0\\le\\rho\\le100$, $0\\le\\phi\\le\\pi/4$, $0\\le\\theta\\le2\\pi$, with volume $V=\\tfrac{2\\pi}{3}100^3(1-\\tfrac{\\sqrt2}{2})\\approx6.1\\times10^5$ km$^3$. That is a fraction $1-\\tfrac{\\sqrt2}{2}\\approx0.293$ of the half-ball.", "Sample volume: a sample has edges $\\Delta\\rho$, $\\rho\\,\\Delta\\phi$, and $\\rho\\sin\\phi\\,\\Delta\\theta$, so its volume is about $\\rho^2\\sin\\phi\\,\\Delta\\rho\\,\\Delta\\phi\\,\\Delta\\theta$. At 100 km a sample is 100 times larger than at 10 km, so the radar averages over far more air at long range."], "reflection": "Most weather happens below about 10 km. Why does the blind cone matter more for a radar beside a city than for one far from people, and how can a network of overlapping radars fill it?", "extension": false, "id": "w05-p3", "discussionSolution": "Because the blind cone sits directly over the radar, a radar beside a city cannot see the storms right above the city: with a 45° top tilt, the cone is 20 km across at a height of 10 km. Neighboring radars see the same air from the side at low tilts, so radars spaced so that each blind cone lies inside the others’ coverage leave no gap.", "modelSpec": {"data": ["Highest elevation angle of the full-circle scans in the Finnish schedule: $45^\\circ$ (scan group C)", "Range of the group C scans: $100$ km"], "assume": ["The ground is flat and radar beams are straight lines.", "The radar sits at the origin, and $z$ is the height above it in km."], "model": ["Blind region (cone of silence): the points above the steepest beam, $z\\ge\\sqrt{x^2+y^2}$", "Part (c): the blind points within range $100$ km of the radar ($\\rho\\le100$)"]}, "photo": {"alt": "A water tower in Vantaa, Finland, rising above pine trees, with the white dome of a Finnish Meteorological Institute weather radar on its top; a playground in the foreground", "credit": "Paju", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Kaivokselan_tutka1.jpg", "file": "w05-p3.jpg"}, "figure": {"alt": "Side view, to scale, of the radar with its group C scan beams at elevations of 2, 7, 11, 15, 25, and 45 degrees out to 100 km. The unscanned cone above the 45 degree beams is shaded and labeled cone of silence.", "caption": "Side view of the Finnish scan group C (tilts 2°–45°, range 100 km). The shaded cone above the steepest, 45° beam is never sampled; in the model it is $z\\ge\\sqrt{x^2+y^2}$.", "file": "w05-p3"}}, {"title": "Starlight and city light at Lick Observatory", "context": "Lick Observatory, the University of California’s mountain-top observatory near San Jose, needs dark skies. In a 1977 paper, Lick astronomer Merle Walker reported how much the lights of Salinas brightened the night sky at sites 8 to 36 km from the city. He found that this sky glow fades with distance $D$ like $D^{-2.5}$. Astronomers also measure a star by adding up all the light in its blurred image on the camera. Both are improper integrals: integrals over a region that never ends, or of a function that blows up. When are such integrals finite, and how much does a dark zone around the observatory help?", "model": "Walker’s Salinas measurements and his $D^{-2.5}$ law are published, while the Gaussian star image and the evenly spread city lights are models.", "sources": ["walker1977"], "work": ["Check Walker’s law on his rows for 10.5 km and 16.9 km: compare the measured ratio with the $D^{-2.5}$ prediction.", "After (a): Camera pixels are squares, so astronomers often add up light over squares $[-s,s]^2$ instead of disks. Sandwich each square between two disks to show the square sums have the same limit, and explain why switching exhaustions is legal here.", "Factor the square integral to find $\\int_{-\\infty}^\\infty e^{-x^2}dx$.", "After (b): Redo part (b) on the punctured disk $0<x^2+y^2\\le1$. For which $b$ does it converge, and to what? Show that $b=1$ diverges at both ends.", "Compare with $\\int_0^1x^{-p}dx$ and $\\int_1^\\infty x^{-p}dx$, and complete: $1/|\\mathbf x|^s$ is integrable near the origin of $\\mathbb R^n$ exactly when $s<\\underline{\\quad}$.", "Classify $f=(x^2+y^2)^{-3/4}$: does its integral converge on the punctured disk, outside the unit disk, both, or neither?"], "questions": [{"prompt": "A star’s image on the camera has brightness $e^{-(x^2+y^2)}$ (arbitrary units). Enter the light collected inside a circular aperture of radius $r$ centered on the star, as a function of r.", "expected": "pi*(1-exp(-r^2))", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Use polar coordinates, calling the polar radius ρ because r is the aperture radius: ∫ from 0 to 2π ∫ from 0 to r of e^(−ρ²) ρ dρ dθ.", "Substitute w = ρ²."], "id": "w05-p4-a", "label": "a"}, {"prompt": "Suppose city lights are spread evenly over the plane outside a dark circle of radius 1 around the observatory, and the glow from lights at distance $D$ is proportional to $D^{-2b}$. For $b>1$, enter $\\iint_{x^2+y^2\\ge1}(x^2+y^2)^{-b}\\,dA$ as a function of b.", "expected": "pi/(b-1)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["In polar coordinates the integrand times r is r^(1−2b).", "Integrate from 1 to T, then let T → ∞."], "id": "w05-p4-b", "label": "b"}, {"prompt": "Use Walker’s law, $2b=2.5$. If the dark zone around the observatory grows from radius 10 km to 40 km, what is the ratio (new glow)/(old glow) for the evenly spread lights?", "expected": "1/2", "units": "", "kind": "number", "tolerance": 1e-05, "hints": ["Redo part (b) with inner radius a: the integral is proportional to a^(2−2b).", "Here 2 − 2b = −1/2."], "id": "w05-p4-c", "label": "c"}], "solution": ["Data check: Walker’s law predicts the ratio $(16.9/10.5)^{2.5}\\approx3.29$ between the two rows, and the table gives $1.91/0.59\\approx3.24$, so the law fits these rows well.", "Disk exhaustion: $\\iint_{D_r}e^{-(x^2+y^2)}dA=2\\pi\\int_0^re^{-\\rho^2}\\rho\\,d\\rho=\\pi(1-e^{-r^2})$, which tends to $\\pi$ as $r\\to\\infty$.", "Square exhaustion: the square $[-s,s]^2$ contains the disk of radius $s$ and sits inside the disk of radius $\\sqrt2s$. Because the integrand is positive, each square integral lies between $\\pi(1-e^{-s^2})$ and $\\pi(1-e^{-2s^2})$, and both bounds tend to $\\pi$. Switching exhaustions is legal because the integrand is positive; for integrands that change sign it can fail. On a square, $\\iint e^{-x^2}e^{-y^2}dA=\\big(\\int_{-s}^se^{-x^2}dx\\big)^2$, so $\\int_{-\\infty}^\\infty e^{-x^2}dx=\\sqrt\\pi$.", "Power laws in the plane: outside the unit disk, $2\\pi\\int_1^Tr^{1-2b}dr=\\dfrac{2\\pi}{2-2b}(T^{2-2b}-1)$, which tends to $\\dfrac{\\pi}{b-1}$ for $b>1$ and to $\\infty$ for $b<1$. On the punctured disk, $2\\pi\\int_\\varepsilon^1r^{1-2b}dr\\to\\dfrac{\\pi}{1-b}$ for $b<1$ and diverges for $b>1$. At $b=1$ the integrals are $2\\pi\\ln T$ and $2\\pi\\ln(1/\\varepsilon)$, so they diverge at both ends.", "Thresholds: in one variable, $\\int x^{-p}dx$ converges near 0 when $p<1$ and at infinity when $p>1$. In $\\mathbb R^n$ the volume factor $r^{n-1}$ turns $1/r^s$ into $r^{n-1-s}$, so the threshold is $s<n$ near the origin and $s>n$ at infinity. For $(x^2+y^2)^{-3/4}=r^{-3/2}$, $s=1.5<2$, so the integral converges on the punctured disk (to $4\\pi$) but not outside.", "Dark zone: with inner radius $a$ the glow is proportional to $\\dfrac{\\pi}{b-1}a^{2-2b}=4\\pi a^{-1/2}$ for $b=1.25$. Going from $a=10$ km to $a=40$ km multiplies it by $(40/10)^{-1/2}=\\tfrac12$. Because Walker’s exponent 2.5 is greater than 2, the total glow from all the lights is finite once the observatory has a dark zone; without one ($a\\to0$), the nearest lights would make it grow without bound."], "reflection": "If city glow fell only like D⁻², as light spreading through empty space without absorption does, what would happen to the total glow from lights spread over an endless plain, even with a dark zone around the observatory?", "extension": false, "id": "w05-p4", "discussionSolution": "It would be infinite. With exponent 2b = 2 (b = 1), the integral outside the dark zone is 2π ln(T/a), which grows without bound as the plain extends to radius T, so no dark zone could help. Real glow falls faster than D⁻² because the atmosphere scatters and absorbs light along the way; that faster fall, Walker’s exponent 2.5, is why distance protects observatories.", "modelSpec": {"data": ["Walker (1977): sky glow at $45^\\circ$ altitude toward Salinas falls with distance as $D^{-2.5}$", "Salinas measurements: glow $1.91$ at $10.5$ km and $0.59$ at $16.9$ km (natural sky $=1$)"], "assume": ["A star’s image on the camera has brightness $e^{-(x^2+y^2)}$, in units chosen so the image width is 1.", "City lights are spread evenly over the plane outside a dark circle of radius $a$ around the observatory, and their glows add."], "model": ["Star: total light $=\\iint_{\\mathbb R^2}e^{-(x^2+y^2)}\\,dA$", "Glow at the observatory $\\propto\\iint_{x^2+y^2\\ge a^2}(x^2+y^2)^{-b}\\,dA$, with $a$ the dark-zone radius in km and $2b=2.5$ for Walker’s law"]}, "photo": {"alt": "Aerial view looking east from above San Jose over dry, folded hills of the Diablo Range; the white domes of Lick Observatory are tiny specks on the summit of Mount Hamilton near the center", "credit": "Dicklyon", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Lick_Observatory_aerial.jpg", "file": "w05-p4.jpg"}, "figure": {"alt": "Log-log plot of Walker’s sky-glow measurements toward Salinas against distance from 8 to 36 km, with visual values as filled dots and blue values as open circles, both falling close to a straight line of slope minus 2.5.", "caption": "Walker’s 1977 measurements of sky glow toward Salinas (filled dots: visual; open circles: blue) on log–log axes, with a line $\\propto D^{-2.5}$. On these axes a power law is a straight line, here with slope $-2.5$.", "file": "w05-p4"}}, {"title": "The 660-tonne ball inside Taipei 101", "context": "Taipei 101 is a 508 m skyscraper in Taiwan. Near its top, between the 87th and 92nd floors, hangs a 660-tonne steel weight shaped like a ball. It is a tuned mass damper: when strong winds or earthquakes rock the tower, the heavy pendulum swings against the motion and calms it. The weight is built from stacked steel plates, but here we model it as a solid steel ball. How big must the ball be to have a mass of 660 tonnes, how hard is it to spin, and where is the center of mass of its lower half?", "model": "The 660-tonne mass and the floors are published, while treating the stacked steel plates as a solid ball of uniform steel is an assumption.", "sources": ["taipeidamper"], "work": ["Set up the ball’s volume in spherical coordinates.", "Set up its moment of inertia about the vertical axis, and explain the extra factor $\\sin^2\\phi$.", "Before (c): Give the spherical limits for the lower half of the ball.", "After (c): Explain why that center of mass lies less than $R/2$ below the center."], "questions": [{"prompt": "Model the damper as a solid steel ball with density 7850 kg/m³. Find the radius, in meters, of a ball with mass 660 t (660,000 kg).", "expected": "(3*660000/(4*pi*7850))^(1/3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["V = ∫₀^{2π}∫₀^π∫₀^R ρ² sin φ dρ dφ dθ = 4πR³/3.", "Set 7850 × V = 660,000 kg and solve for R."], "id": "w05-p5-a", "label": "a"}, {"prompt": "Find the moment of inertia of the ball about a vertical axis through its center, in t·m² (keep the mass in tonnes).", "expected": "2/5*660*(3*660000/(4*pi*7850))^(2/3)", "units": "t·m²", "kind": "number", "tolerance": 1e-05, "hints": ["The squared distance to the vertical axis is x² + y² = ρ² sin²φ.", "You should find I = (2/5)MR²; use M = 660 t and R from part (a)."], "id": "w05-p5-b", "label": "b"}, {"prompt": "How far below the center of the ball, in meters, is the center of mass of its lower half?", "expected": "3/8*(3*660000/(4*pi*7850))^(1/3)", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Use π/2 ≤ φ ≤ π; the depth below the center is −z = −ρ cos φ.", "For density 1, the moment of the depth is πR⁴/4 and the half-ball volume is 2πR³/3."], "id": "w05-p5-c", "label": "c"}], "solution": ["Radius: $V=\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^R\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta=\\tfrac43\\pi R^3$. Setting $7850V=660{,}000$ kg gives $R=\\big(\\tfrac{3\\cdot660{,}000}{4\\pi\\cdot7850}\\big)^{1/3}\\approx2.72$ m, so the ball is about 5.4 m across, more than a story tall.", "Moment of inertia: the squared distance to the vertical axis is $x^2+y^2=\\rho^2\\sin^2\\phi$, which is where the extra $\\sin^2\\phi$ comes from. Then $I=\\delta\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^R(\\rho\\sin\\phi)^2\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta=\\delta\\cdot2\\pi\\cdot\\tfrac43\\cdot\\tfrac{R^5}{5}=\\tfrac25MR^2\\approx1950$ t·m$^2$.", "Lower half: it is $0\\le\\rho\\le R$, $\\pi/2\\le\\phi\\le\\pi$, $0\\le\\theta\\le2\\pi$. Its depth moment is $\\int_0^{2\\pi}\\!\\int_{\\pi/2}^{\\pi}\\!\\int_0^R(-\\rho\\cos\\phi)\\rho^2\\sin\\phi\\,d\\rho\\,d\\phi\\,d\\theta=2\\pi\\cdot\\tfrac12\\cdot\\tfrac{R^4}4=\\tfrac{\\pi R^4}{4}$. Dividing by the volume $\\tfrac23\\pi R^3$ gives $\\tfrac38R\\approx1.02$ m below the center.", "Interpretation: the answer is less than $R/2$ because the half-ball is widest near the center, so more of its steel lies near the center than near the bottom."], "reflection": "The real damper is a stack of steel plates of different diameters, not a smooth solid ball. How would you set up its volume as a sum of cylinders, and why would the answer differ slightly from the ball’s?", "extension": true, "id": "w05-p5", "discussionSolution": "Treat each plate as a short cylinder, with volume π(radius)²(thickness), and add up the cylinders. The result is a stepped solid that only approximates a sphere: the corners of the steps add or remove a little steel compared with the smooth ball, so the volume, and hence the radius that gives 660 t, differs slightly from the solid-ball estimate.", "modelSpec": {"data": ["Mass of the pendulum weight: $660$ t ($660{,}000$ kg)", "Hangs between the 87th and 92nd floors of the 508 m tower"], "assume": ["The weight is a solid ball of uniform steel with density $7850$ kg/m$^3$."], "model": ["The ball is $\\rho\\le R$ in spherical coordinates (meters), with its center at the origin and the $z$-axis pointing up", "$I$ is the moment of inertia about the vertical $z$-axis; the lower half is the part with $z\\le0$"]}, "photo": {"alt": "The gold-colored tuned mass damper of Taipei 101 seen from above: a ball built from stacked circular steel plates, flat on top, hanging from thick cables with hydraulic dampers below", "credit": "Armand du Plessis", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Taipei_101_Tuned_Mass_Damper_2010.jpg", "file": "w05-p5.jpg"}, "figure": {"alt": "Schematic side view of a ball of radius R hanging on cables below the 92nd-floor level and above the 87th-floor level, with its center marked and its lower half shaded.", "caption": "The damper modeled as a solid steel ball of radius $R$ hanging between the 87th and 92nd floors (schematic). The lower half, used in part (c), is shaded.", "file": "w05-p5"}}]}, {"week": 6, "title": "Paths, work, and what depends on the route", "subtitle": "The Road Not Taken (Doesn’t Matter)", "skills": ["Parametrize curves, including hanging cables, and compute their speed", "Compute length, weight, and centroids with $ds$, independent of parametrization and direction", "Compute work and circulation with $\\mathbf F\\cdot d\\mathbf r$ and $P\\,dx+Q\\,dy$, and explain their signs", "Test for path independence, find potentials in 2D and 3D, and use the fundamental theorem", "Recognize when equal cross-partials still fail to give a potential"], "formulas": ["$\\int_C f\\,ds=\\int_a^b f(\\mathbf c(t))\\,\\|\\mathbf c^{\\prime}(t)\\|\\,dt$ (the same in either direction of travel)", "$\\int_C\\mathbf F\\cdot d\\mathbf r=\\int_C P\\,dx+Q\\,dy=\\int_a^b\\mathbf F(\\mathbf c(t))\\cdot\\mathbf c^{\\prime}(t)\\,dt$ (reversing $C$ flips the sign)", "$\\int_C\\nabla f\\cdot d\\mathbf r=f(\\mathbf c(b))-f(\\mathbf c(a))$ for any path $C$ from $\\mathbf c(a)$ to $\\mathbf c(b)$", "If $(P,Q)=\\nabla f$, then $\\partial P/\\partial y=\\partial Q/\\partial x$; the converse holds on a domain with no holes"], "sources": ["ggbridge", "ggbstatics", "acc", "everest", "stelvio", "earthgm", "lightning"], "problems": [{"title": "Weighing the Golden Gate’s main cable", "context": "Each of the Golden Gate Bridge’s two main cables is a bundle of 27,572 steel wires, 0.92 m across. Between the two towers, 1,280 m apart, each cable hangs in a smooth curve. Its sag, the drop from where it meets the towers to its lowest point at midspan, is 144 m. Because the cable curves, it is longer than the 1,280 m span, and its weight depends on that length. How long is one cable between the towers, how much does that part weigh, and how high is its centroid (its balance point)?", "model": "The span, sag, and cable weight are published; the parabolic shape and a constant weight per meter of cable are modeling assumptions.", "sources": ["ggbridge", "ggbstatics"], "work": ["Parametrize the main-span cable as $\\mathbf c(t)=(t,y(t))$ and give its $t$-interval.", "Parametrize the reversed cable, from the Marin tower to the San Francisco tower.", "Check that $\\Psi(u)=\\big(k\\sinh u,\\ \\tfrac k2\\sinh^2u\\big)$, $k=12800/9$ m, traces the same curve. Give its $u$-interval and show $\\|\\Psi^{\\prime}(u)\\|=k\\cosh^2u$.", "Explain why all three parametrizations give the same length and the same $\\int_C y\\,ds$.", "After (b): estimate the weight $\\int_C\\lambda\\,ds$ of the main-span cable, and explain why $\\int\\lambda\\,dx$ would underestimate it.", "After (c): the flat region between the cable and the line joining its two tops has centroid height $3h/5=86.4$ m. Explain why the cable’s centroid is so much lower."], "questions": [{"prompt": "Enter the speed $\\|\\mathbf c^{\\prime}(t)\\|$ of $\\mathbf c(t)=(t,\\,9t^2/25600)$ as a function of $t$.", "expected": "sqrt(1+(9*t/12800)^2)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["The speed is the length of the velocity vector c′(t).", "Differentiate: c′(t) = (1, 9t/12800). Then take its length."], "id": "w06-p1-a", "label": "a"}, {"prompt": "Find the length $L=\\int_C ds$ of the main-span cable, from tower to tower, to two decimal places.", "expected": "1321.97431941635", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["L is the integral of the speed from part (a), from t = −640 to t = 640.", "Substituting t = k sinh u turns the integrand into k cosh²u du; a calculator’s numerical integral also works."], "id": "w06-p1-b", "label": "b"}, {"prompt": "Using part (b), find $\\bar y$, the height of the cable’s centroid above its lowest point.", "expected": "49.2045532645424", "units": "m", "kind": "number", "tolerance": 1e-05, "hints": ["Compute ∫ y ds along the cable and divide by the length L from part (b).", "Along Ψ, y ds = (k²/2) sinh²u cosh²u du = (k²/8) sinh²(2u) du. Expect a little more than h/3 = 48 m."], "id": "w06-p1-c", "label": "c"}], "solution": ["Parametrization: with the origin at the cable’s lowest point, $y=144(x/640)^2=9x^2/25600$, so $\\mathbf c(t)=(t,9t^2/25600)$, $-640\\le t\\le640$. Then $\\mathbf c^{\\prime}(t)=(1,9t/12800)$, and the speed is $\\sqrt{1+(9t/12800)^2}$. It grows from 1 at midspan to $\\sqrt{1.2025}\\approx1.097$ at the towers.", "Same curve, three parametrizations: the reversed cable $\\mathbf c_2(t)=(-t,9t^2/25600)$, $-640\\le t\\le640$, has the same speed at each point, so every integral with respect to $ds$ is unchanged. For $\\Psi$, $y=\\tfrac k2\\sinh^2u=(k\\sinh u)^2/(2k)$ and $2k=25600/9$, so $\\Psi$ traces the same parabola for $|\\sinh u|\\le9/20$, that is, for $|u|\\le U=\\operatorname{arcsinh}(9/20)$. Its velocity $\\Psi^{\\prime}=(k\\cosh u,k\\sinh u\\cosh u)$ has length $k\\cosh u\\sqrt{1+\\sinh^2u}=k\\cosh^2u$. Each parametrization traces the cable exactly once, so $ds$ is the same arc-length element in all three.", "Length: \\[L=k\\int_{-U}^{U}\\cosh^2u\\,du=k\\,(U+\\sinh U\\cosh U)\\approx1321.97\\text{ m},\\] about 42 m more than the 1,280 m span.", "Centroid: \\[\\int_C y\\,ds=\\frac{k^2}{8}\\int_{-U}^{U}\\sinh^2(2u)\\,du=\\frac{k^2}{8}\\Big(\\frac{\\sinh4U}{4}-U\\Big)\\approx65047\\text{ m}^2,\\] so $\\bar y\\approx65047/1321.97\\approx49.20$ m. By symmetry, $\\bar x=0$.", "Weight: $\\int_C\\lambda\\,ds=48.7\\times1321.97\\approx64{,}380$ kN, about 6,560 t. The estimate $\\int\\lambda\\,dx=48.7\\times1280\\approx62{,}340$ kN is too small because $dx<ds$ wherever the cable slopes, so it misses the extra length near the towers.", "Why the cable’s centroid is low: the flat region is widest at the top, so most of its area sits high and its centroid is at $3h/5=86.4$ m. The cable’s weight is spread almost evenly in $x$, and most of the span is low, so its centroid is near the average height $h/3=48$ m. In all, one main-span cable is about 1,322 m long, weighs about 64,400 kN, and balances about 49 m above its lowest point."], "reflection": "The source gives the cable’s weight per horizontal meter. If the weight per meter of cable is constant, is the weight per horizontal meter also constant? If not, where along the span is it largest?", "extension": false, "id": "w06-p1", "discussionSolution": "No. The weight per horizontal meter is $\\lambda\\,ds/dx=\\lambda\\sqrt{1+(y^{\\prime})^2}$. It equals $\\lambda$ only at midspan, where the cable is horizontal, and grows to about $1.097\\lambda$ at the towers, where the cable is steepest. (For a real suspension bridge it is the deck’s load per horizontal meter that is nearly constant, which is why the cable hangs as a parabola.)", "modelSpec": {"data": ["Main span (tower to tower): $1280$ m", "Maximum sag of the main cable: $h=144$ m", "Cable weight: $48.7$ kN per horizontal meter", "Diameter of one main cable: $0.92$ m"], "assume": ["The main-span cable hangs as a parabola, lowest at midspan", "The weight per meter of cable is constant, $\\lambda=48.7$ kN/m. This matches the published value at midspan, where the cable is horizontal", "The cable is a curve: its 0.92 m thickness is ignored"], "model": ["Coordinates in meters, origin at the cable’s lowest point, $y$ up: $y=144\\,(x/640)^2$, $-640\\le x\\le640$", "Weight and centroid height: $W=\\int_C\\lambda\\,ds$, $\\ \\bar y=\\dfrac{\\int_C y\\,ds}{\\int_C ds}$"]}, "photo": {"alt": "Close-up of one orange-painted Golden Gate Bridge main cable against a blue sky, with a cable band and suspender ropes hanging from it", "credit": "Guillaume Paumier", "license": "CC BY-SA 3.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Cables_of_the_Golden_Gate_bridge_in_San_Francisco_66.jpg", "file": "w06-p1.jpg"}, "figure": {"alt": "Side view of the Golden Gate main span: two towers, a parabolic main cable that sags 144 m between them, vertical suspenders, and the deck", "caption": "The model: the main cable as the parabola $y=144\\,(x/640)^2$ between towers 1,280 m apart, with its lowest point at the origin. The vertical scale is doubled.", "file": "w06-p1"}}, {"title": "Sailing around Antarctica: with or against the current?", "context": "The Antarctic Circumpolar Current flows eastward all the way around Antarctica, pushed by strong westerly winds (winds that blow from the west). It is the only ocean current that circles the whole globe. A ship sailing around Antarctica can go east with the current or west against it. The circulation of the current around a loop, the line integral of its velocity around the loop, measures how strongly the water swirls around it. How large is the circulation around the voyage, how much time does riding the current save, and why does the direction of travel change some totals but not others?", "model": "The average current speed is published; the route along latitude 60° S, the uniform eastward speed, and the small northward drift are assumptions.", "sources": ["acc", "earthgm"], "work": ["Sketch the map: Antarctica, the circle $C$, and $\\mathbf u$ at eight points of $C$. Show that the eastward part of $\\mathbf u$ turns clockwise and the drift points away from the pole.", "Parametrize the westward voyage (counterclockwise on the map) and give its $t$-interval.", "Before (b): use your sketch, not an integral, to explain why the drift adds nothing to $\\oint_C\\mathbf u\\cdot d\\mathbf r$.", "After (c): explain why reversing the voyage flips the sign of $\\oint_C\\mathbf u\\cdot d\\mathbf r$ but not of $\\oint_C ds$ or $\\oint_C\\|\\mathbf u\\|\\,ds$.", "At speed $V$ through the water, a ship takes time $\\oint_C ds/(V+\\mathbf u\\cdot\\mathbf T)$, with $\\mathbf T$ the unit tangent. Show that this is about $L/V-(\\oint_C\\mathbf u\\cdot d\\mathbf r)/V^2$.", "Estimate the hours an eastward voyage at $V=20$ km/h saves over a westward one."], "questions": [{"prompt": "Find the length $L=\\oint_C ds$ of the voyage around $C$.", "expected": "6371*pi", "units": "km", "kind": "number", "tolerance": 1e-05, "hints": ["Parametrize the circle as c(t) = (ρ cos t, ρ sin t), 0 ≤ t ≤ 2π, and integrate the speed.", "The speed ‖c′(t)‖ is constant, equal to ρ = 3185.5 km."], "id": "w06-p2-a", "label": "a"}, {"prompt": "Find the circulation $\\oint_C\\mathbf u\\cdot d\\mathbf r$ for the westward voyage (counterclockwise on the map).", "expected": "-1.8*6371*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["Compute u(c(t))·c′(t) and integrate from 0 to 2π. The drift part is perpendicular to c′(t), so it gives zero.", "The eastward part gives the constant (1.8/ρ)(ρ sin t, −ρ cos t)·(−ρ sin t, ρ cos t). Expect a negative answer: the ship fights the current."], "id": "w06-p2-b", "label": "b"}, {"prompt": "Find $\\oint_C\\|\\mathbf u\\|\\,ds$ for the same westward voyage.", "expected": "1.8*sqrt(1.01)*6371*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["On the circle ‖u‖ is constant: the eastward and drift parts are perpendicular, with sizes 1.8 and 0.18 km/h.", "Multiply ‖u‖ by the length from part (a). This scalar integral takes no sign from the direction of travel."], "id": "w06-p2-c", "label": "c"}], "solution": ["Orientation and length: seen from above the South Pole, Earth turns clockwise, so eastward is clockwise on this map. The westward voyage is $\\mathbf c(t)=(\\rho\\cos t,\\rho\\sin t)$, $0\\le t\\le2\\pi$, with $\\rho=6371\\cos60^\\circ=3185.5$ km. Its speed is $\\|\\mathbf c^{\\prime}(t)\\|=\\rho$, so $L=\\oint_C ds=2\\pi\\rho=6371\\pi\\approx20{,}015$ km.", "Circulation: on the circle the drift $(0.18/\\rho)(x,y)$ points straight out and $\\mathbf c^{\\prime}(t)$ is tangent, so their dot product is zero at every point. The eastward part gives $\\frac{1.8}{\\rho}(\\rho\\sin t,-\\rho\\cos t)\\cdot(-\\rho\\sin t,\\rho\\cos t)=-1.8\\rho$, so \\[\\oint_C\\mathbf u\\cdot d\\mathbf r=-1.8(2\\pi\\rho)=-11467.8\\pi\\approx-36{,}027\\text{ km}^2/\\text{h}.\\] Going east (clockwise) gives $+36{,}027$ km$^2$/h, because reversing $\\mathbf c^{\\prime}$ flips the sign of each dot product.", "Scalar integral: $\\|\\mathbf u\\|=\\sqrt{1.8^2+0.18^2}=1.8\\sqrt{1.01}$ km/h everywhere on the circle, so $\\oint_C\\|\\mathbf u\\|\\,ds=1.8\\sqrt{1.01}\\,(6371\\pi)\\approx36{,}207$ km$^2$/h in either direction. The scalar integral counts the drift and ignores direction. The line integral ignores the drift and keeps direction.", "Time saved: since $1/(V+w)\\approx1/V-w/V^2$ for small $w=\\mathbf u\\cdot\\mathbf T$, the time is about $L/V-\\frac{1}{V^2}\\oint_C\\mathbf u\\cdot d\\mathbf r$. The circulation is $+36{,}027$ km$^2$/h going east and $-36{,}027$ km$^2$/h going west, so going east saves about $2(36{,}027)/20^2\\approx180$ hours. The exact times $L/(V\\pm1.8)$ differ by about 182 hours. A ship that rides the current around Antarctica arrives roughly a week sooner than one that fights it."], "reflection": "The line integral $\\oint\\mathbf u\\cdot d\\mathbf r$ has units of area per time (here km²/h). Why is it a natural measure of how strongly water swirls around a loop, while $\\oint\\|\\mathbf u\\|\\,ds$ is not?", "extension": false, "id": "w06-p2", "discussionSolution": "Because the line integral adds up only the part of the flow along the loop, with a sign. Flow that goes around the loop adds up, while flow that crosses the loop or reverses direction cancels. $\\oint\\|\\mathbf u\\|\\,ds$ counts every bit of motion as positive, so water drifting straight across the loop or sloshing back and forth would also make it large.", "modelSpec": {"data": ["Average speed of the Antarctic Circumpolar Current: $50$ cm/s $=1.8$ km/h", "The current flows from west to east (the West Wind Drift)", "Earth’s mean radius: $R=6371$ km"], "assume": ["The voyage follows latitude $60^\\circ$ S", "Along the voyage the current flows due east at $1.8$ km/h", "The current also drifts north, away from the pole, at $0.18$ km/h (0.05 m/s)"], "model": ["Map: Earth seen from directly above the South Pole, $x,y$ in km. The $60^\\circ$ S circle appears at its true radius $\\rho=R\\cos60^\\circ=3185.5$ km", "Surface current near the voyage, in km/h: $\\mathbf u(x,y)=\\dfrac{1.8}{\\rho}(y,\\,-x)+\\dfrac{0.18}{\\rho}(x,\\,y)$", "$C$: the circle $x^2+y^2=\\rho^2$"]}, "photo": {"alt": "A wave breaks over the bow of the icebreaker Polar Star as it crosses the Southern Ocean toward Antarctica, January 2015", "credit": "U.S. Coast Guard photo by Petty Officer 1st Class George Degener", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Waves_crashing_over_the_deck_of_the_coast_guard_cutter_Polar_Star.jpg", "file": "w06-p2.jpg"}, "figure": {"alt": "Map centered on the South Pole showing Antarctica, the 60 degree south voyage circle, and at eight points a long arrow along the circle (the current, turning clockwise) and a short arrow pointing outward (the drift)", "caption": "Seen from directly above the South Pole: the voyage circle $C$ of radius $\\rho=3185.5$ km, the eastward current (teal), and the northward drift (orange, exaggerated).", "file": "w06-p2"}}, {"title": "A sealed snack bag climbs Everest", "context": "Climbers notice that sealed snack bags puff up on the way to high camps: the air outside presses less, so the air inside expands. In October 1981, Chris Pizzo of the American Medical Research Expedition to Everest measured the air pressure on the summit. It was only one third of sea-level pressure. Physicists follow a gas on a pressure–volume diagram, where each point is a state of the gas and a path is a process that carries it from one state to another. Take a bag from sea level to the summit by two different processes. Which totals depend on the path: the work the air does, the change in its internal energy (the energy stored in its molecules’ motion), or the heat it absorbs?", "model": "The summit pressure is a published measurement; the bag’s volume, the temperatures, and both processes are assumptions.", "sources": ["everest"], "work": ["Parametrize both paths and give their intervals (path 2 has two pieces).", "Compute the energy integral $\\int_C\\tfrac52y\\,dx+\\tfrac52x\\,dy$ directly along both paths.", "Explain why unequal answers on two paths disprove path independence, while equal answers, as here, do not prove it.", "Check the cross-partials of the work field $(y,0)$ and of the heat field $(\\tfrac72y,\\tfrac52x)$.", "After (b): find the heat $Q$ absorbed along each path."], "questions": [{"prompt": "Find the work $W=\\int_C y\\,dx$ done by the air along path 1, the straight segment from A to B.", "expected": "1", "units": "L·atm", "kind": "number", "tolerance": 1e-05, "hints": ["Parametrize the segment from A to B and substitute into y dx.", "With x = 1 + 1.5t, y = 1 − 2t/3, 0 ≤ t ≤ 1, you get dx = 1.5 dt. Check with the area of the trapezoid under the segment."], "id": "w06-p3-a", "label": "a"}, {"prompt": "Find the work $W=\\int_C y\\,dx$ done by the air along path 2, from A to B.", "expected": "log(3)-1/6", "units": "L·atm", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate over each of the two pieces of path 2 and add.", "On the isotherm y = 1/x, so the first piece is the integral of dx/x from 1 to 3. On the constant-pressure piece x decreases from 3 to 2.5, so that piece is negative."], "id": "w06-p3-b", "label": "b"}, {"prompt": "Enter a potential $f(x,y)$ for the energy field $\\big(\\tfrac52y,\\ \\tfrac52x\\big)$.", "expected": "5*x*y/2", "units": "L·atm", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate (5/2)y with respect to x and add an unknown function g(y).", "Differentiate your result with respect to y and compare with (5/2)x to show g is constant."], "id": "w06-p3-c", "label": "c"}], "solution": ["Parametrizations: path 1 is $\\mathbf c(t)=(1+1.5t,\\,1-\\tfrac23t)$, $0\\le t\\le1$. Path 2 is $\\mathbf c(t)=(t,1/t)$, $1\\le t\\le3$, then $\\mathbf c(t)=(3-0.5t,\\,1/3)$, $0\\le t\\le1$. Both start at A $=(1,1)$ and end at B $=(2.5,1/3)$.", "Work: on path 1, $W=\\int_0^1(1-\\tfrac23t)(1.5)\\,dt=1$ L·atm. On path 2, $W=\\int_1^3\\frac{dt}{t}+\\int_0^1\\tfrac13(-0.5)\\,dt=\\ln3-\\tfrac16\\approx0.932$ L·atm. Different values with the same endpoints prove that $\\int y\\,dx$ depends on the path. The cross-partials confirm it: $\\partial_y(y)=1\\ne0=\\partial_x(0)$.", "Energy: on path 1, \\[\\tfrac52\\int_0^1\\big[(1-\\tfrac23t)(1.5)+(1+1.5t)(-\\tfrac23)\\big]dt=\\tfrac52\\int_0^1(\\tfrac56-2t)\\,dt=-\\tfrac5{12},\\] and on path 2, $\\tfrac52\\big[\\int_1^3(\\tfrac1t-\\tfrac1t)\\,dt+\\int_0^1(-\\tfrac16)\\,dt\\big]=-\\tfrac5{12}$. Agreement on two paths proves nothing by itself, because a third path could still disagree. The potential $f=\\tfrac52xy$ (with $f_x=\\tfrac52y$ and $f_y=\\tfrac52x$) proves it for every path: $\\Delta U=f(B)-f(A)=\\tfrac52(\\tfrac56-1)=-\\tfrac5{12}$ L·atm.", "Heat: $Q=\\Delta U+W$, so $Q_1=-\\tfrac5{12}+1=\\tfrac7{12}\\approx0.583$ L·atm and $Q_2=-\\tfrac5{12}+\\ln3-\\tfrac16\\approx0.515$ L·atm ($1$ L·atm $=101.325$ J). The heat field fails the test: $\\partial_y(\\tfrac72y)=\\tfrac72\\ne\\tfrac52=\\partial_x(\\tfrac52x)$. Internal energy is a state function: it depends only on the state of the gas. Heat and work are not. So the bag reaches the summit with the same internal energy either way, but the work it does and the heat it absorbs depend on the process."], "reflection": "On a pressure–volume diagram, an engine runs around a closed loop. What is $\\Delta U$ around any loop, and why can the work around the loop still be nonzero?", "extension": false, "id": "w06-p3", "discussionSolution": "$\\Delta U=0$ around any loop, because the energy field has the potential $U=\\tfrac52PV$ and the loop ends where it starts. The work $\\oint P\\,dV$ depends on the path, so around a loop it need not be zero. It equals the signed area enclosed by the loop (Green’s theorem, Week 9): the net work the engine delivers each cycle, supplied by the heat it absorbs.", "modelSpec": {"data": ["Summit pressure measured in October 1981: $253$ mm Hg", "One standard atmosphere: $760$ mm Hg, so the summit had $253/760=0.333$ atm"], "assume": ["At sea level the bag holds $1$ L of air at $1$ atm and $300$ K", "At the summit the air is at $1/3$ atm and $250$ K; the slack bag keeps the pressure inside equal to the pressure outside", "Air is an ideal diatomic gas, so $PV/T$ stays constant"], "model": ["Coordinates: volume $x=V$ (L), pressure $y=P$ (atm); energies in L·atm. Start A $=(1,1)$; summit B $=(2.5,\\,1/3)$", "Work done by the air: $W=\\int_C y\\,dx$. Heat absorbed: $Q=\\Delta U+W$", "Change in internal energy: $\\Delta U=\\int_C\\tfrac52y\\,dx+\\tfrac52x\\,dy$", "Path 1: the straight segment from A to B. Path 2: along the isotherm $xy=1$ from A to $(3,1/3)$, then at constant pressure $y=1/3$ to B"]}, "photo": {"alt": "Aerial view of the snow-covered summit pyramid of Mount Everest above surrounding Himalayan ridges", "credit": "shrimpo1967; derivative work by Papa Lima Whiskey 2", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Mount_Everest_as_seen_from_Drukair2_PLW_edit_Cropped.jpg", "file": "w06-p3.jpg"}, "figure": {"alt": "Pressure-volume diagram with states A and B, a straight path 1 between them, and a path 2 that follows a hyperbola down to the right and then a short horizontal segment back to B", "caption": "The two processes from A $=(1,1)$ to B $=(2.5,1/3)$, with volume $x$ and pressure $y$. Path 2 follows the isotherm $xy=1$, then the constant pressure $y=1/3$.", "file": "w06-p3"}}, {"title": "Forty-eight hairpins, one number", "context": "The 25 km road from Prato allo Stelvio, at 915 m, to the Stelvio Pass, 2,757 m high in the Italian Alps, climbs through 48 hairpin bends (sharp U-turns). Cyclists ride it from bottom to top. The whole way, Earth’s gravity pulls the rider toward Earth’s center, and the work it does measures the energy it takes from the rider on the climb. How much work does gravity do on a rider from Prato to the pass, and does all that twisting change the answer?", "model": "The elevations, Earth’s GM, and Earth’s radius are published; the rider’s mass, the spherical Earth, and the formula for the road are assumptions.", "sources": ["stelvio", "earthgm"], "work": ["Before (a): integrate $F_1$ with respect to $x$, carrying an unknown function $g(y,z)$. Then use $F_2$ and $F_3$ to show $g$ is constant.", "Explain why you never need $\\phi(t)$ or $\\lambda(t)$, and why the wiggle term in $h(t)$ does not matter.", "After (b): find the work gravity does on the descent from the pass to Prato.", "Compare your answer to (b) with the flat-Earth estimate $-mg\\,\\Delta h$, where $g=GM/R^2$.", "After (c): justify your choice with the potential from (a), and explain why it does not contradict how tired the rider is."], "questions": [{"prompt": "Enter a potential $f(x,y,z)$ for $\\mathbf F$, so that $\\nabla f=\\mathbf F$, writing the constant $GMm$ as $c$.", "expected": "c/sqrt(x^2+y^2+z^2)", "units": "J", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate the first component of F with respect to x, treating y and z as constants; substitute w = x² + y² + z².", "Check that the derivative of your answer with respect to z is −c z/(x² + y² + z²)^(3/2)."], "id": "w06-p4-a", "label": "a"}, {"prompt": "Find the work $\\int_C\\mathbf F\\cdot d\\mathbf r$ done by gravity on the rider along the hairpin road from Prato to the pass, in kJ.", "expected": "-1446.27683945079", "units": "kJ", "kind": "number", "tolerance": 1e-05, "hints": ["Use the fundamental theorem: the work is f(end) − f(start). Only the distances r = R + elevation from Earth’s center matter.", "Expect about −m g Δh, but compute with the inverse-square potential; the two differ in the fourth digit."], "id": "w06-p4-b", "label": "b"}, {"prompt": "A rider climbs from Prato to the pass, descends the far side to Bormio, and returns to Prato by another road. What is the total work done by gravity on this closed ride?", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The fundamental theorem gives f(end) − f(start). Where does a closed ride end?", "The rider’s effort goes into air drag, friction, and body heat, which are not gravity."], "options": ["0 J: gravity has a potential everywhere the rider can be, and the ride ends where it starts.", "Negative: the rider worked hard, so gravity’s total work must be negative.", "It depends on which roads make up the loop.", "Positive: descents are faster than climbs."], "id": "w06-p4-c", "label": "c"}], "solution": ["Potential: integrating $f_x=F_1=-c\\,x(x^2+y^2+z^2)^{-3/2}$ with respect to $x$ gives $f=c(x^2+y^2+z^2)^{-1/2}+g(y,z)$. Then $f_y=-c\\,y(x^2+y^2+z^2)^{-3/2}+g_y=F_2$ forces $g_y=0$, and $f_z=F_3$ forces $g_z=0$. So $f=c/\\sqrt{x^2+y^2+z^2}=GMm/r$, defined everywhere except Earth’s center.", "Why the road’s shape does not matter: by the fundamental theorem, the work is $f(\\mathbf c(1))-f(\\mathbf c(0))$, and $f$ depends only on $r=\\|\\mathbf c\\|=R+h$. Since $h(0)=915$ m and $h(1)=2757$ m (the wiggle term vanishes at both ends), $\\phi(t)$ and $\\lambda(t)$ never enter.", "Work: with $c=GMm=3.9860\\times10^{14}\\times80$ J·m, \\[W=c\\Big(\\frac1{6{,}373{,}757}-\\frac1{6{,}371{,}915}\\Big)\\approx-1{,}446{,}277\\text{ J}\\approx-1446.28\\text{ kJ}.\\] The descent reverses the path, so gravity does $+1446.28$ kJ of work on the way down.", "Flat-Earth check: $g=GM/R^2\\approx9.820$ m/s$^2$, and $-mg\\,\\Delta h=-80(9.820)(1842)\\approx-1447.11$ kJ. This differs by only 0.06%, because $g$ is slightly weaker at altitude.", "Closed rides: around a closed ride, $f$ ends where it starts, so gravity’s total work is $0$. The rider’s effort is lost to air drag, rolling friction, and body heat, which have no potential. On the climb itself, gravity takes about 1.45 MJ from the rider, however the road winds."], "reflection": "The field $(-y,x)/(x^2+y^2)$ on the plane with the origin removed has equal cross-partials but no potential. Gravity is also undefined at one point, Earth’s center, yet it has a potential. What is different?", "extension": false, "id": "w06-p4", "discussionSolution": "The domains differ. Equal cross-partials give a potential on a domain with no hole that a loop can wrap around. Space with one point removed has no such hole: any loop can slide off the missing point, and $f=GMm/r$ works everywhere except the center. The plane with one point removed does have one: a loop can circle the missing point, and there $(-y,x)/(x^2+y^2)$ has circulation $2\\pi$.", "modelSpec": {"data": ["Elevations: Prato allo Stelvio $915$ m; Stelvio Pass $2757$ m", "The 25 km road between them has 48 hairpins", "$GM=3.9860\\times10^{14}$ m$^3$/s$^2$; Earth’s radius $R=6{,}371{,}000$ m"], "assume": ["Rider plus bicycle: $m=80$ kg", "Earth is a non-rotating sphere, so a point at elevation $h$ is at distance $r=R+h$ from Earth’s center", "The road follows the formula below, whose wiggles stand in for the 48 hairpins"], "model": ["Gravity, origin at Earth’s center: $\\mathbf F=-GMm\\,(x,y,z)/(x^2+y^2+z^2)^{3/2}$ N", "Road, $0\\le t\\le1$: $\\mathbf c(t)=(R+h)(\\cos\\phi\\cos\\lambda,\\ \\cos\\phi\\sin\\lambda,\\ \\sin\\phi)$", "Elevation $h=915+1842t+15\\sin(2\\pi t)\\sin(48\\pi t)$ m", "Latitude in degrees: $\\phi=46.62-0.09t-0.003\\sin(48\\pi t)$", "Longitude in degrees: $\\lambda=10.59-0.14t+0.004\\sin(48\\pi t)$"]}, "photo": {"alt": "A motorcyclist rounds a stone-walled hairpin bend on the eastern ramp of the Stelvio Pass, with snowy mountains behind", "credit": "kallerna", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Stelvio_Pass_Bolzano_side_3.jpg", "file": "w06-p4.jpg"}, "figure": {"alt": "Left: plan view of a road zigzagging through many hairpin bends from Prato to the Stelvio Pass. Right: an arc of Earth’s surface with two lines from Earth’s center to the start and end of the road", "caption": "Left: the hairpin road model seen from above. Right: the only thing gravity’s work depends on, the distances $r_A=R+915$ m and $r_B=R+2757$ m from Earth’s center (not to scale).", "file": "w06-p4"}}, {"title": "Lightning’s magnetic loop", "context": "A typical lightning flash carries a current of about 30,000 amperes, and the Empire State Building in New York is struck about 23 times a year. The current in the lightning channel, the narrow path the flash follows, makes a magnetic field that circles the channel. Ampère’s law says that the circulation of this field around a closed loop, its line integral around the loop, depends only on the current passing through the loop, not on the loop’s shape. Test this with a circle and two squares. What is the circulation around a loop that surrounds the channel, and around one that does not?", "model": "The typical current and strike rate are published; the straight, steady vertical channel is an assumption.", "sources": ["lightning"], "work": ["After (b): use symmetry to add the four oriented edges of $S_1$, and compare the total with part (a).", "After (c): show that $\\partial B_1/\\partial y=\\partial B_2/\\partial x$ wherever $\\mathbf B$ is defined.", "Explain why $\\mathbf B$ is still not a gradient on the plane with the channel removed.", "Compute the circulation around $S_2$ by adding its four oriented edges."], "questions": [{"prompt": "Find $\\oint\\mathbf B\\cdot d\\mathbf r$ around the circle of radius 10 m centered on the channel, counterclockwise.", "expected": "12*pi", "units": "mT·m", "kind": "number", "tolerance": 1e-05, "hints": ["On the circle, B is tangent and points counterclockwise, with constant size 6/10 mT.", "Multiply that size by the circle’s length; the answer does not depend on the radius."], "id": "w06-p5-a", "label": "a"}, {"prompt": "Find $\\int\\mathbf B\\cdot d\\mathbf r$ along the right edge of $S_1$, from $(10,-10)$ to $(10,10)$.", "expected": "3*pi", "units": "mT·m", "kind": "number", "tolerance": 1e-05, "hints": ["On this edge x = 10 and dx = 0, so only B₂ dy = 60 dy/(100 + y²) counts.", "Use ∫ dy/(100 + y²) = (1/10) arctan(y/10)."], "id": "w06-p5-b", "label": "b"}, {"prompt": "Enter $\\partial B_2/\\partial x$ as a function of $x$ and $y$, where $B_2=6x/(x^2+y^2)$ is the second component of $\\mathbf B$.", "expected": "6*(y^2-x^2)/(x^2+y^2)^2", "units": "mT/m", "kind": "expression", "tolerance": 1e-05, "hints": ["Use the quotient rule on 6x/(x² + y²), treating y as a constant.", "Compare with ∂B₁/∂y for B₁ = −6y/(x² + y²); the two should agree."], "id": "w06-p5-c", "label": "c"}], "solution": ["Circle: on $\\mathbf c(t)=(10\\cos t,10\\sin t)$, $0\\le t\\le2\\pi$, the field is $\\mathbf B=0.6(-\\sin t,\\cos t)$ mT and $\\mathbf c^{\\prime}=10(-\\sin t,\\cos t)$, so the integrand is 6 and the circulation is $12\\pi\\approx37.70$ mT·m $=\\mu_0I$.", "Right edge of $S_1$: $\\int_{-10}^{10}\\frac{60}{100+y^2}\\,dy=6\\big[\\arctan(y/10)\\big]_{-10}^{10}=3\\pi$ mT·m. By the four-fold symmetry, each counterclockwise edge of $S_1$ gives $3\\pi$, so the total $12\\pi$ matches the circle.", "Cross-partials: $\\partial_x\\frac{6x}{x^2+y^2}=\\frac{6(y^2-x^2)}{(x^2+y^2)^2}=\\partial_y\\frac{-6y}{x^2+y^2}$. If $\\mathbf B=\\nabla f$ on the punctured plane, every closed loop would give 0, but the circle gives $12\\pi$. Equal cross-partials guarantee a potential only on a domain without holes.", "Square $S_2$: it does not enclose the channel. Its edges $x=40$ and $x=20$ give $6\\cdot2\\arctan(1/4)$ and $-6\\cdot2\\arctan(1/2)$, and the edges $y=-10$ and $y=10$ give $6[\\arctan(4)-\\arctan(2)]$ each. Since $\\arctan4=\\pi/2-\\arctan\\tfrac14$ and $\\arctan2=\\pi/2-\\arctan\\tfrac12$, the total is $0$. As Ampère’s law says, the circulation is $\\mu_0I$ for a loop around the channel and $0$ for a loop beside it, whatever the loop’s shape."], "reflection": "The cross-partial test missed that $\\mathbf B$ is not a gradient. What feature of the domain is responsible, and why does a square that does not surround the channel give zero?", "extension": true, "id": "w06-p5", "discussionSolution": "The hole. The domain, the plane with the channel removed, has a hole, so a loop can circle the current, and the cross-partial test is reliable only on a domain with no holes. A square beside the channel lies in a hole-free region, such as a half-plane, where $\\mathbf B$ has a potential (a multiple of the polar angle), so its circulation is zero.", "modelSpec": {"data": ["Typical lightning current: about $30{,}000$ A", "The Empire State Building is struck about 23 times a year"], "assume": ["The channel is a long, straight vertical line carrying a steady current $I=30{,}000$ A upward", "With $\\mu_0=4\\pi\\times10^{-7}$ T·m/A, the field constant is $\\mu_0I/(2\\pi)=6$ mT·m"], "model": ["In a horizontal plane, $x,y$ in meters, channel at the origin: $\\mathbf B=\\dfrac{6\\,(-y,\\ x)}{x^2+y^2}$ mT", "$S_1$: the square $|x|\\le10$, $|y|\\le10$. $S_2$: the square $20\\le x\\le40$, $|y|\\le10$. Both oriented counterclockwise"]}, "figure": {"alt": "Top view of circular magnetic field lines around a lightning channel, with a dashed circle and a square around the channel and a second square beside it", "caption": "Top view, with the current flowing up out of the page: field lines of $\\mathbf B$ around the channel, the circle of radius 10 m (dashed), and the squares $S_1$ and $S_2$.", "file": "w06-p5"}}]}, {"week": 7, "title": "Surfaces people build and measure", "subtitle": "Pride and Parametrization", "skills": ["Parametrize spheres, cylinders, graphs, and ruled surfaces, with their domains", "Identify a surface from its parametrization and describe its grid curves", "Find the parameters of a point, tangent vectors, normals, and tangent planes", "Compute surface area for graphs, polar domains, spheres, cones, and surfaces of revolution", "Distinguish coordinate singularities from geometric corners", "Explain why area does not depend on the parametrization"], "formulas": ["$\\mathbf N=\\Phi_u\\times\\Phi_v,\\quad dS=\\|\\mathbf N\\|\\,du\\,dv$; $\\Phi$ is regular where $\\mathbf N\\ne\\mathbf 0$", "$z=g(x,y):\\quad dS=\\sqrt{1+g_x^2+g_y^2}\\,dx\\,dy$", "$A=2\\pi\\int_a^b f(x)\\sqrt{1+f'(x)^2}\\,dx$ for $y=f(x)\\ge0$ rotated about the $x$-axis"], "sources": ["earth", "alma", "cooling", "zimbabwe", "iter"], "problems": [{"title": "How much of Earth is tropical?", "context": "The tropics are the belt of Earth between latitudes $23.44^\\circ$ S and $23.44^\\circ$ N. Latitude is the angle, measured at Earth’s center, between a place and the equator. The tropics are where the Sun can be directly overhead at some time of year, and their edge, $23.44^\\circ$, equals Earth’s axial tilt: the angle between its spin axis and the perpendicular to its orbit. On a globe the tropics look like a thin belt around the middle. How much of the planet do they really cover?", "model": "Earth’s radius and axial tilt are published values, while the perfect sphere (which ignores Earth’s slight polar flattening) and the enclosing cylinder are modeling constructions.", "sources": ["earth"], "work": ["Write $\\Phi(\\phi,\\theta)$ for the sphere, with $\\phi$ measured from the North Pole, and give its domain.", "Describe the grid curves ($\\theta$ fixed; $\\phi$ fixed) in geographic terms.", "Explain why this chart is not regular at the poles, even though Earth is not pointed there.", "Before (b): predict which of ten equally thick slabs, cut by parallel planes, has the most surface area.", "Find the lateral area of the cylinder $\\Psi(\\theta,z)=(R\\cos\\theta,R\\sin\\theta,z)$ between heights $z_1<z_2$."], "questions": [{"prompt": "For the sphere chart $\\Phi(\\phi,\\theta)$, with $\\phi$ measured from the North Pole and $R=6371$ km, enter $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|$ as a function of phi.", "expected": "6371^2*sin(phi)", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["Compute Φ_φ and Φ_θ, then their dot product and their lengths.", "The two tangent vectors are perpendicular, with lengths R and R sin φ."], "id": "w07-p1-a", "label": "a"}, {"prompt": "Two horizontal planes a distance h apart both cut the sphere. Find the area of the part of the sphere between them, with R = 6371 km and h in km. Enter it as a function of h.", "expected": "2*pi*6371*h", "units": "km²", "kind": "expression", "tolerance": 1e-05, "hints": ["Integrate the area element from (a) over the band, then change variable from φ to the height z.", "With z = R cos φ, the area element R² sin φ dφ dθ becomes R dz dθ."], "id": "w07-p1-b", "label": "b"}, {"prompt": "Using part (b), what fraction of Earth’s surface lies in the tropics? Enter the exact value or a decimal rounded to two places.", "expected": "sin(23.44*pi/180)", "units": "", "kind": "number", "tolerance": 0.002, "hints": ["The tropics are a band like the one in (b). Find its height h from the latitude 23.44°.", "The band runs from z = −R sin 23.44° to z = R sin 23.44°. Divide its area by the whole sphere’s area 4πR²."], "id": "w07-p1-c", "label": "c"}], "solution": ["Parametrization: $\\Phi(\\phi,\\theta)=(R\\sin\\phi\\cos\\theta,R\\sin\\phi\\sin\\theta,R\\cos\\phi)$ on $0\\le\\phi\\le\\pi$, $0\\le\\theta\\le2\\pi$. Fixing $\\theta$ gives a meridian (a line of longitude). Fixing $\\phi$ gives a parallel (the line of latitude $90^\\circ-\\phi$).", "Cross product: $\\Phi_\\phi=(R\\cos\\phi\\cos\\theta,R\\cos\\phi\\sin\\theta,-R\\sin\\phi)$ and $\\Phi_\\theta=(-R\\sin\\phi\\sin\\theta,R\\sin\\phi\\cos\\theta,0)$ are perpendicular, with lengths $R$ and $R\\sin\\phi$. So $\\|\\Phi_\\phi\\times\\Phi_\\theta\\|=R^2\\sin\\phi=6371^2\\sin\\phi$ km$^2$.", "The poles: the norm is zero at $\\phi=0$ and $\\phi=\\pi$ because all the meridians meet there, just as longitude is undefined at a pole. A different chart, such as the graph $z=\\sqrt{R^2-x^2-y^2}$ near the North Pole, is regular there, so the sphere itself is smooth.", "Band area: for a band $z_1\\le z\\le z_2$, substituting $z=R\\cos\\phi$ turns $R^2\\sin\\phi\\,d\\phi\\,d\\theta$ into $R\\,dz\\,d\\theta$. The area is $\\int_0^{2\\pi}\\!\\int_{z_1}^{z_2}R\\,dz\\,d\\theta=2\\pi R(z_2-z_1)=2\\pi Rh$, with $R=6371$ km.", "Cylinder and slabs: the cylinder has $\\|\\Psi_\\theta\\times\\Psi_z\\|=R$, so its band between $z_1$ and $z_2$ also has area $2\\pi R(z_2-z_1)$. This is Archimedes’ hat-box theorem. So all ten equally thick slabs have the same area, $4\\pi R^2/10$; the equatorial slab does not win.", "Tropics: the tropics have $h=2R\\sin23.44^\\circ$, so the fraction is $\\dfrac{2\\pi R\\cdot2R\\sin23.44^\\circ}{4\\pi R^2}=\\sin23.44^\\circ\\approx0.398$. Interpretation: almost 40% of Earth’s surface is tropical, even though the belt looks thin on a globe."], "reflection": "Lambert’s cylindrical equal-area map moves each point horizontally, straight away from Earth’s axis, onto the enclosing cylinder, then unrolls the cylinder flat. Why does that map show Greenland and Africa with correct relative areas, even though shapes near the poles look squashed?", "extension": false, "id": "w07-p1", "discussionSolution": "Because horizontal projection onto the cylinder preserves area. By the hat-box theorem every thin band keeps its area, and so does every longitude wedge of that band, so every region keeps its area. Shapes still distort: at latitude L, east–west lengths stretch by 1/cos L while north–south lengths shrink by cos L, and their product, the area factor, stays 1.", "modelSpec": {"data": ["Earth’s volumetric mean radius: $R=6371$ km", "Earth’s axial tilt: $23.44^\\circ$"], "assume": ["Earth is a perfect sphere. The real Earth is flattened at the poles by about 0.3%.", "The enclosing cylinder is an imaginary surface that touches the sphere all around the equator."], "model": ["Earth: the sphere $x^2+y^2+z^2=R^2$, $R=6371$ km, centered at Earth’s center with the positive $z$-axis through the North Pole", "Tropics: latitudes $23.44^\\circ$ S to $23.44^\\circ$ N. Latitude $L$ sits at height $z=R\\sin L$, so the tropics are the band $|z|\\le R\\sin23.44^\\circ$", "Enclosing cylinder: $x^2+y^2=R^2$, $-R\\le z\\le R$"]}, "photo": {"alt": "Earth seen from Apollo 17: Africa, the Arabian Peninsula, and Madagascar under swirling clouds, with the Antarctic ice cap at the bottom", "credit": "NASA / Apollo 17 crew", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:The_Earth_seen_from_Apollo_17.jpg", "file": "w07-p1.jpg"}, "figure": {"alt": "Side view through the poles: a circle (the sphere) inside a dashed square (the enclosing cylinder). A shaded horizontal band of height h = 2R sin 23.44° marks the tropics, and gray arrows point horizontally from the sphere out to the cylinder.", "caption": "The model, side view through the poles: Earth as a sphere of radius $R$, the tropics as a band of height $h=2R\\sin23.44^\\circ$, and the enclosing cylinder. The arrows show horizontal projection from the sphere out to the cylinder.", "file": "w07-p1"}}, {"title": "How much mirror does an ALMA antenna need?", "context": "ALMA, at 5000 m altitude in Chile’s Atacama Desert, links dozens of dish antennas into one radio telescope. Each 12 m dish is a curved mirror that reflects incoming radio waves to a single point, the focus. The mirror is built from many precisely shaped panels, so its builders need to know how much curved surface it has. That is more than the area of the flat 12 m circle across its rim, called the aperture. How much mirror surface does one dish have?", "model": "The diameter and focal length are published design values, while the perfect paraboloid with no central hole or panel gaps is a geometric idealization, not a manufacturing drawing.", "sources": ["alma"], "work": ["Parametrize the mirror as a graph over the disk, $(x,y,(x^2+y^2)/19.2)$, and with polar coordinates; give each domain.", "Decide whether the area should include the flat aperture disk.", "Before (c): rotate the profile $y=\\sqrt{19.2x}$, $0\\le x\\le1.875$, about the $x$-axis (the dish on its side) and set up $A=2\\pi\\int y\\sqrt{1+y'^2}\\,dx$.", "After (c): explain why this integral converges although $y'$ is unbounded at $x=0$, and check that it matches (b)."], "questions": [{"prompt": "Write the mirror as the graph $z=g(x,y)=(x^2+y^2)/19.2$. Enter the area factor $\\sqrt{1+g_x^2+g_y^2}$ as a function of $r=\\sqrt{x^2+y^2}$.", "expected": "sqrt(1+r^2/92.16)", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Differentiate g(x, y) = (x² + y²)/19.2 with respect to x and to y.", "g_x = x/9.6 and g_y = y/9.6. Then use x² + y² = r²."], "id": "w07-p2-a", "label": "a"}, {"prompt": "Find the area of the curved mirror surface over the disk r ≤ 6 m, not counting the flat aperture disk. Enter the exact value or round to two decimal places.", "expected": "2*pi*92.16/3*((1+36/92.16)^(3/2)-1)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Use polar coordinates: multiply the factor from (a) by r dr dθ, with 0 ≤ r ≤ 6 and 0 ≤ θ ≤ 2π.", "Substitute w = 1 + r²/92.16, so dw = 2r dr/92.16."], "id": "w07-p2-b", "label": "b"}, {"prompt": "In the surface-of-revolution setup (the profile $y=\\sqrt{19.2x}$, $0\\le x\\le1.875$, rotated about the $x$-axis), simplify the integrand $y\\sqrt{1+y'^2}$ as a function of x.", "expected": "sqrt(19.2*x+92.16)", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["Bring y inside the square root: y√(1 + y′²) = √(y² + y²y′²).", "Since y′ = 19.2/(2y), y²y′² = 19.2²/4. Then replace y² by 19.2x."], "id": "w07-p2-c", "label": "c"}], "solution": ["Two parametrizations: the graph form $(x,y,(x^2+y^2)/19.2)$ on the disk $x^2+y^2\\le36$, and the polar form $(r\\cos\\theta,r\\sin\\theta,r^2/19.2)$ on $0\\le r\\le6$, $0\\le\\theta\\le2\\pi$. Only the curved mirror counts. The flat aperture disk across the rim is open sky, not mirror.", "Area factor: $g_x=x/9.6$ and $g_y=y/9.6$, so $\\sqrt{1+g_x^2+g_y^2}=\\sqrt{1+r^2/92.16}$. In polar coordinates the area element $dx\\,dy$ also becomes $r\\,dr\\,d\\theta$.", "Area: substituting $w=1+r^2/92.16$ gives $A=2\\pi\\int_0^6 r\\sqrt{1+r^2/92.16}\\,dr=\\frac{2\\pi(92.16)}{3}\\Big[(1+\\tfrac{36}{92.16})^{3/2}-1\\Big]\\approx123.51$ m$^2$.", "Surface of revolution: with $y=\\sqrt{19.2x}$, the slope $y'=19.2/(2y)$ blows up at $x=0$. But $y\\sqrt{1+y'^2}=\\sqrt{y^2+92.16}=\\sqrt{19.2x+92.16}$ stays bounded, so the improper integral converges. It gives \\[A=2\\pi\\int_0^{1.875}\\sqrt{19.2x+92.16}\\,dx\\approx123.51\\ \\mathrm{m}^2,\\] the same area as before.", "Interpretation: area belongs to the surface, not to the parametrization. The dish needs about $123.5$ m$^2$ of mirror surface, about 9% more than the $36\\pi\\approx113.10$ m$^2$ aperture."], "reflection": "Two different parametrizations gave the same area. What would go wrong for the people ordering mirror panels if area depended on the parametrization?", "extension": false, "id": "w07-p2", "discussionSolution": "The amount of panel surface to order would depend on the engineer’s choice of coordinates, which is absurd. Area is a property of the surface itself: any two regular, one-to-one parametrizations are related by a change of variables whose Jacobian converts one area element exactly into the other.", "modelSpec": {"data": ["Primary mirror diameter: $12$ m", "Primary focal length: $f=4.8$ m (focal ratio $f/D=0.4$)", "Central hole: $0.75$ m across"], "assume": ["The mirror is a perfect paraboloid with its vertex at the origin and its axis along the $z$-axis.", "Panel gaps and the central hole are ignored, so the mirror covers the whole disk $r\\le6$ m."], "model": ["Mirror: $z=\\dfrac{r^2}{4f}=\\dfrac{r^2}{19.2}$ m over the disk $r\\le6$ m, where $r=\\sqrt{x^2+y^2}$ is the distance from the axis in meters", "Rim depth: $z=36/19.2=1.875$ m", "Rays parallel to the axis reflect through the focus $(0,0,4.8)$"]}, "photo": {"alt": "Two white ALMA dish antennas on the dry Chajnantor plateau in Chile, the nearer one tilted so the panels of its dish are visible", "credit": "Iztok Bončina / ALMA (ESO/NAOJ/NRAO)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Two_ALMA_antennas_on_Chajnantor_(ib-alma22).jpg", "file": "w07-p2.jpg"}, "figure": {"alt": "To-scale cross-section of the paraboloid mirror z = r²/19.2, 12 m across and 1.875 m deep at the rim, with vertical incoming rays reflecting to the focus 4.8 m above the vertex", "caption": "The model, cross-section through the dish axis: the paraboloid $z=r^2/19.2$ with a 12 m aperture and 1.875 m rim depth. Rays parallel to the axis reflect through the focus $(0,0,4.8)$.", "file": "w07-p2"}}, {"title": "Straight lines that build a curved cooling tower", "context": "Many power stations have tall concrete cooling towers with a narrow waist. In a natural-draft tower, warm air rises through the tall shell on its own, without fans. The tower at Niederaussem, Germany, was described in 2001 as the world’s tallest natural-draft cooling tower. It is 200 m high, yet its curved concrete shell is only about 24 cm thick. A waisted shape like this can be traced out entirely by straight lines. Which surface is it, which lines lie on it, and what is its tangent plane at a survey point?", "model": "Only the height and base diameter are published values, while the narrowest radius, its height, and the exact hyperboloid shape are assumed, since real towers are not exact hyperboloids.", "sources": ["cooling"], "work": ["Eliminate $t$ and $s$ to identify the surface by an equation in $x,y,z$. Check the base radius and the total height.", "Describe the grid curves with $s$ fixed and with $t$ fixed.", "For (a) and (b): show how you find the parameters of $P$, then compute $\\Phi_t$ and $\\Phi_s$ there.", "After (c): check your plane using the upper half as a graph, $z=c\\sqrt{(x^2+y^2)/a^2-1}$."], "questions": [{"prompt": "A survey marker sits on the shell at P = (38, 19, 40), in meters. Enter the parameters (t, s) of P, with 0 ≤ s < 2π.", "expected": ["0.5", "0"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Match the third coordinate first: z = ct.", "With t known, solve the x and y equations for cos s and sin s. The answer is not the polar angle of (38, 19)."], "id": "w07-p3-a", "label": "a"}, {"prompt": "Enter the normal vector $\\Phi_t\\times\\Phi_s$ at the marker $P$.", "expected": ["-3040", "-1520", "722"], "units": "m²", "kind": "vector", "tolerance": 1e-05, "hints": ["Differentiate Φ with respect to t and to s, then substitute the parameters from (a).", "At P you should get Φ_t = (0, 38, 80) and Φ_s = (−19, 38, 0)."], "id": "w07-p3-b", "label": "b"}, {"prompt": "Enter the tangent plane to the shell at P, solved for z as a function of x and y.", "expected": "(80*x+40*y-3040)/19", "units": "m", "kind": "expression", "tolerance": 1e-05, "hints": ["A plane through P with normal N is N · (X − P) = 0.", "Divide N by 38 to get (−80, −40, 19), then solve for z."], "id": "w07-p3-c", "label": "c"}], "solution": ["Identify the surface: $x^2+y^2=a^2[(\\cos s-t\\sin s)^2+(\\sin s+t\\cos s)^2]=a^2(1+t^2)$ and $t=z/c$, so $\\frac{x^2+y^2}{38^2}-\\frac{z^2}{80^2}=1$, a hyperboloid of one sheet. At $t=-\\sqrt3$ the radius is $38\\cdot2=76$ m, matching the base, and the height is $c(2.5-\\sqrt3+\\sqrt3)=200$ m.", "Grid curves: fixing $s$ gives $a(\\cos s,\\sin s,0)+t(-a\\sin s,a\\cos s,c)$, a straight line. Fixing $t$ gives a horizontal circle of radius $a\\sqrt{1+t^2}$. The curved shell is woven from straight lines, so straight reinforcing bars can follow it.", "Parameters of $P$: $z=40$ gives $t=0.5$. Then $\\cos s-0.5\\sin s=1$ and $\\sin s+0.5\\cos s=0.5$ force $s=0$, not the polar angle $\\arctan(1/2)$ of $(38,19)$.", "Tangent vectors and normal: $\\Phi_t=(-a\\sin s,a\\cos s,c)=(0,38,80)$ and $\\Phi_s=(-a(\\sin s+t\\cos s),a(\\cos s-t\\sin s),0)=(-19,38,0)$, so $\\mathbf N=(-3040,-1520,722)=38(-80,-40,19)$.", "Tangent plane: $-80(x-38)-40(y-19)+19(z-40)=0$, that is, $z=(80x+40y-3040)/19$. Graph check: $z_x=\\dfrac{c\\,x/a^2}{\\sqrt{(x^2+y^2)/a^2-1}}=\\dfrac{80}{19}$ and $z_y=\\dfrac{40}{19}$ at $P$, which gives the same plane.", "Interpretation: the shell is steep at the marker. Moving horizontally straight away from the axis, the plane rises $\\sqrt{80^2+40^2}/19\\approx4.7$ m per meter, a slope of about $78^\\circ$."], "reflection": "A second family, $\\big(a(\\cos s+t\\sin s),\\,a(\\sin s-t\\cos s),\\,ct\\big)$, traces the same surface. How many straight lines on the surface pass through each point, and why might builders care?", "extension": false, "id": "w07-p3", "discussionSolution": "Two: one from each family, so the hyperboloid is doubly ruled. Builders can therefore run straight reinforcing bars or formwork along the surface in two directions, making a curved shell from straight pieces.", "modelSpec": {"data": ["Height: $200$ m", "Base diameter: $152$ m, so base radius $76$ m", "Shell thickness: about $0.24$ m"], "assume": ["The shell is exactly the surface traced by $\\Phi$ below. Real towers only approximate this shape.", "The narrowest radius $a=38$ m and the vertical scale $c=80$ m are chosen to match the base radius and the height.", "Height $z$ is measured from the narrowest level, so the ground is at $z=-80\\sqrt3\\approx-138.6$ m."], "model": ["Shell: $\\Phi(t,s)=\\big(a(\\cos s-t\\sin s),\\ a(\\sin s+t\\cos s),\\ ct\\big)$, in meters", "Domain: $0\\le s\\le2\\pi$ ($s$ an angle in radians), $-\\sqrt3\\le t\\le2.5-\\sqrt3$ ($t$ dimensionless)", "$a=38$ m, $c=80$ m"]}, "photo": {"alt": "The tall concrete cooling tower of Niederaussem power station, Germany, slightly narrower near the top, beside power-station buildings under clouds", "credit": "Stodtmeister", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Kraftwerk_Niederau%C3%9Fem_Block_K_BoA_K%C3%BChlturm.jpg", "file": "w07-p3.jpg"}, "figure": {"alt": "Waisted hyperboloid tower drawn entirely as two crossing families of straight lines, with circles at the base, the waist, and the top, and the point P marked near the top", "caption": "The model surface drawn only with straight lines: teal lines come from $\\Phi$ and brown lines from the second family. Height 200 m, base radius 76 m, narrowest radius 38 m at $z=0$. The marker $P$ is orange.", "file": "w07-p3"}}, {"title": "The Conical Tower of Great Zimbabwe", "context": "Great Zimbabwe, a UNESCO World Heritage site, was the capital of a southern African kingdom that flourished between roughly the 11th and 15th centuries. Inside its walled Great Enclosure stands a solid Conical Tower, about 9 m tall, built of granite blocks without mortar, the paste that usually binds stones together. Its sloping side tapers toward the top, like a cone with its tip cut off. How much stone surface faces the outside world, and does the missing tip cause trouble for the parametrization?", "model": "The height and base diameter are published approximate values that vary by about a meter, while the top radius, the perfect cone shape, and the imaginary apex are assumed.", "sources": ["zimbabwe"], "work": ["Write the curved face as a graph $z=g(x,y)$ over its shadow in the $xy$-plane, and show that the area factor is constant.", "Explain why the curved area is a fixed multiple of the shadow’s area, as for a tilted plane.", "Decide whether a lime-wash estimate for the curved face should include the flat top disk.", "After (c): check with the cone formula $\\pi RL$, subtracting the missing tip."], "questions": [{"prompt": "For the cone $\\Phi(u,v)$ in the model, enter the normal vector $\\Phi_u\\times\\Phi_v$ as a function of u and v.", "expected": ["6*u*cos(v)", "6*u*sin(v)", "u"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Differentiate Φ with respect to u and to v.", "Φ_u = (cos v, sin v, −6) and Φ_v = (−u sin v, u cos v, 0). Check that the third component is positive."], "id": "w07-p4-a", "label": "a"}, {"prompt": "Where does Φ fail to be regular, and what does that mean for the tower?", "expected": "0", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Regularity fails exactly where the cross product is the zero vector.", "Its norm is u√37. Where is the apex, compared with the tower’s 9 m top?"], "options": ["Only at u = 0, the apex 7.5 m above the tower; the tower itself is regular everywhere.", "Along the top rim u = 1.25, where the tower is cut off.", "Along the seam v = 0, where the parametrization starts and ends.", "Nowhere: a cone has no special point."], "id": "w07-p4-b", "label": "b"}, {"prompt": "Find the area of the tower’s curved stone face, excluding the flat top disk.", "expected": "6*pi*sqrt(37)", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate ‖Φ_u × Φ_v‖ = u√37 over the tower’s part of the domain.", "Use 1.25 ≤ u ≤ 2.75 and 0 ≤ v ≤ 2π."], "id": "w07-p4-c", "label": "c"}], "solution": ["Graph form: the curved face is $z=16.5-6\\sqrt{x^2+y^2}$ over the annulus $1.25\\le\\sqrt{x^2+y^2}\\le2.75$. Then $g_x^2+g_y^2=36$, so the area factor is the constant $\\sqrt{37}$, and the curved area is $\\sqrt{37}$ times the shadow’s area, just as a tilted plane multiplies area by a constant.", "Normal vector: $\\Phi_u=(\\cos v,\\sin v,-6)$ and $\\Phi_v=(-u\\sin v,u\\cos v,0)$ give $\\mathbf N=(6u\\cos v,6u\\sin v,u)$, with $\\|\\mathbf N\\|=u\\sqrt{37}$, which is zero only at $u=0$.", "Regularity: the apex $u=0$ is a genuine geometric corner, since no parametrization gives it a tangent plane. But it lies at $z=16.5$ m, outside the $9$ m tower. The truncated tower is regular everywhere; its top and bottom circles are boundary edges.", "Area: $A=\\int_0^{2\\pi}\\int_{1.25}^{2.75}u\\sqrt{37}\\,du\\,dv=\\pi\\sqrt{37}\\,(2.75^2-1.25^2)=6\\pi\\sqrt{37}\\approx114.66$ m$^2$. This is $\\sqrt{37}$ times the shadow’s area $6\\pi$, as the graph form predicts.", "Cone-formula check: $\\pi RL-\\pi r\\ell=\\pi(2.75)(2.75\\sqrt{37})-\\pi(1.25)(1.25\\sqrt{37})=6\\pi\\sqrt{37}$, where $L$ and $\\ell$ are the slant lengths of the full cone and of the missing tip.", "Interpretation: about $115$ m$^2$ of curved stone faces outward. A lime-wash estimate for the curved face should leave out the flat top; including it would add $1.5625\\pi\\approx4.91$ m$^2$."], "reflection": "The sphere chart in the Earth problem also had a zero cross product at its poles. Why is that harmless for the sphere but a real corner for the cone?", "extension": false, "id": "w07-p4", "discussionSolution": "At a pole only the chart fails; at the apex the surface itself has a corner. Another chart of the sphere, such as a graph over the tangent plane at the pole, has a nonzero normal there, so the sphere is smooth. At the cone’s apex no parametrization gives a tangent plane, because normals from different sides point in different directions.", "modelSpec": {"data": ["Height: about $9$ m (30 ft)", "Base diameter: about $5.5$ m (18 ft), so base radius $2.75$ m", "Published descriptions differ by about a meter"], "assume": ["The tower is an exact truncated cone with top radius $1.25$ m.", "Its sloping side is extended upward to an imaginary apex, so one formula describes the whole cone."], "model": ["Full cone: $\\Phi(u,v)=(u\\cos v,\\ u\\sin v,\\ 16.5-6u)$, $0\\le u\\le2.75$, $0\\le v\\le2\\pi$, with $u$ the distance from the axis in meters and $v$ the angle around it", "Tower: the part with $1.25\\le u\\le2.75$, that is, $0\\le z\\le9$ m", "The radius shrinks $1.5$ m over the $9$ m height, so $z$ falls $6$ m per meter of radius"]}, "photo": {"alt": "The tapering stone Conical Tower inside the Great Enclosure at Great Zimbabwe, rising behind lower dry-stone walls and framed by trees", "credit": "Fanny Schertzer", "license": "CC BY 3.0", "licenseUrl": "https://creativecommons.org/licenses/by/3.0/", "page": "https://commons.wikimedia.org/wiki/File:Conical_tower_%E2%80%93_Great_Zimbabwe.jpg", "file": "w07-p4.jpg"}, "figure": {"alt": "Side view of the truncated cone tower, 9 m tall with base radius 2.75 m and top radius 1.25 m, its sides extended by dashed lines to an imaginary apex 7.5 m above the top", "caption": "The model: the tower is the truncated cone $1.25\\le u\\le2.75$, and the dashed lines extend it to the imaginary apex $u=0$, 7.5 m above the top.", "file": "w07-p4"}}, {"title": "The plasma ring inside ITER", "context": "ITER, the international fusion experiment under construction in southern France, will hold a plasma hotter than the Sun’s core inside a ring-shaped magnetic cage. Fusion means joining light atomic nuclei to release energy, and a plasma is a gas so hot that its atoms break apart into charged particles. The plasma ring has the shape of a torus, the surface of a doughnut. How much surface does the ring have, and how much more of it lies on the outer side, away from the central axis, than on the inner side?", "model": "The major and minor radii are published design values, while the circular cross-section is a simplification of the real D-shaped plasma.", "sources": ["iter"], "work": ["Describe the grid curves and what $R$ and $r$ measure.", "Before (a): show that $\\Phi_\\theta$ and $\\Phi_\\phi$ are perpendicular.", "After (b): interpret the area as (tube circumference) × (distance traveled by the tube’s center)."], "questions": [{"prompt": "For the torus $\\Phi(\\theta,\\phi)$ in the model, with $R=6.2$ m and $r=2$ m, enter $\\|\\Phi_\\theta\\times\\Phi_\\phi\\|$ as a function of phi.", "expected": "2*(6.2+2*cos(phi))", "units": "m²", "kind": "expression", "tolerance": 1e-05, "hints": ["Compute Φ_θ and Φ_φ and check that their dot product is zero.", "Their lengths are R + r cos φ and r."], "id": "w07-p5-a", "label": "a"}, {"prompt": "Find the total surface area of the model plasma torus.", "expected": "4*pi^2*6.2*2", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Integrate r(R + r cos φ) over both angles, each from 0 to 2π.", "The cos φ term integrates to zero."], "id": "w07-p5-b", "label": "b"}, {"prompt": "The outer half of the torus (cos φ > 0, farther from the central axis) and the inner half (cos φ < 0) have different areas. Enter the area of the outer half minus the area of the inner half.", "expected": "32*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["The outer half has −π/2 ≤ φ ≤ π/2 and the inner half π/2 ≤ φ ≤ 3π/2.", "Each half has area 2πr(πR ± 2r)."], "id": "w07-p5-c", "label": "c"}], "solution": ["Grid curves: fixing $\\theta$ gives a circle of radius $r$, a cross-section of the tube. Fixing $\\phi$ gives a horizontal circle of radius $R+r\\cos\\phi$. $R$ is the distance from the central axis to the tube’s center, and $r$ is the tube’s radius.", "Tangent vectors: $\\Phi_\\theta=(-(R+r\\cos\\phi)\\sin\\theta,(R+r\\cos\\phi)\\cos\\theta,0)$ and $\\Phi_\\phi=(-r\\sin\\phi\\cos\\theta,-r\\sin\\phi\\sin\\theta,r\\cos\\phi)$ have zero dot product and lengths $R+r\\cos\\phi$ and $r$. So the norm is $r(R+r\\cos\\phi)=2(6.2+2\\cos\\phi)$ m$^2$.", "Total area: $A=\\int_0^{2\\pi}\\!\\int_0^{2\\pi}r(R+r\\cos\\phi)\\,d\\phi\\,d\\theta=4\\pi^2Rr=(2\\pi r)(2\\pi R)=49.6\\pi^2\\approx489.5$ m$^2$. This is the tube’s circumference times the distance its center travels (Pappus’ theorem).", "Outer minus inner: the outer half has area $2\\pi r(\\pi R+2r)\\approx295.0$ m$^2$ and the inner half $2\\pi r(\\pi R-2r)\\approx194.5$ m$^2$, a difference of $8\\pi r^2=32\\pi\\approx100.5$ m$^2$. Interpretation: about 60% of the model plasma’s surface faces outward, because the outer side sweeps around a larger circle."], "reflection": "The same newsletter lists a plasma volume of 837 m³, while a circular torus with these radii has volume 2π²Rr² ≈ 490 m³. What feature of the real plasma explains the difference?", "extension": true, "id": "w07-p5", "discussionSolution": "Elongation: the real plasma is taller than it is wide. ITER’s plasma cross-section is D-shaped and about 1.7 times taller than it is wide, so it encloses much more volume than a circle of radius 2.0 m: 490 × 1.7 ≈ 833 m³, close to the published 837 m³. In this model the volume and the area happen to share the number 49.6π², because V = A·r/2 and r/2 = 1 m.", "modelSpec": {"data": ["Plasma major radius: $R=6.2$ m", "Plasma minor radius: $r=2.0$ m", "Plasma volume: $837$ m$^3$"], "assume": ["The plasma’s cross-section is a circle of radius $r$. The real one is D-shaped and taller than it is wide."], "model": ["Torus: $\\Phi(\\theta,\\phi)=\\big((R+r\\cos\\phi)\\cos\\theta,\\ (R+r\\cos\\phi)\\sin\\theta,\\ r\\sin\\phi\\big)$, in meters", "Domain: $0\\le\\theta\\le2\\pi$, $0\\le\\phi\\le2\\pi$"]}, "figure": {"alt": "Left: top view of the torus as a shaded ring around a dashed center circle of radius R = 6.2 m. Right: a cut through the axis showing two circular tube cross-sections of radius r = 2 m, with the angle φ marked", "caption": "The model: a circular tube of radius $r$ whose center runs around a circle of radius $R$. Left: top view. Right: a cut through the central axis, with the angle $\\phi$ measured around the tube.", "file": "w07-p5"}}]}, {"week": 8, "title": "What crosses a surface", "subtitle": "May the Flux Be With You", "skills": ["Evaluate scalar surface integrals, plain and weighted, on spheres, cylinders, and graphs", "Spot when an integrand cancels the area factor", "Choose an orientation and check it with the cross product $\\Phi_u\\times\\Phi_v$", "Compute flux with $\\mathbf n\\,dS$, with the graph element $(-g_x,-g_y,1)\\,dA$, and on spheres with $\\mathbf n=\\mathbf r/a$", "Interpret the sign of a flux, and compare the flux out of a closed surface with the volume inside"], "formulas": ["Scalar surface integral, for a parametrization $\\Phi:D\\to S$: $\\iint_S f\\,dS=\\iint_D f(\\Phi)\\,\\|\\Phi_u\\times\\Phi_v\\|\\,du\\,dv$", "Flux through $S$ oriented by $\\Phi_u\\times\\Phi_v$: $\\iint_S\\mathbf F\\cdot d\\mathbf S=\\iint_D\\mathbf F(\\Phi)\\cdot(\\Phi_u\\times\\Phi_v)\\,du\\,dv=\\iint_S\\mathbf F\\cdot\\mathbf n\\,dS$", "Graph $z=g(x,y)$ oriented upward: $d\\mathbf S=(-g_x,-g_y,1)\\,dA$. Sphere of radius $a$ centered at the origin: $dS=a^2\\sin\\phi\\,d\\phi\\,d\\theta$ and outward $\\mathbf n=\\mathbf r/a$"], "sources": ["tsi2011", "sunfacts", "earth", "noor1", "sentrough", "usgsrain", "bocci2012", "planck2018", "shoes2022", "pdgastro", "saharadust"], "problems": [{"title": "Weighing sunlight: the Sun’s power and Earth’s share", "context": "Above the atmosphere, a surface facing the Sun receives about 1361 watts on every square meter. This number, the total solar irradiance, is measured by radiometers on satellites. It is the starting point of climate energy budgets, which track how much of the Sun’s power reaches Earth. From this one number you can find the Sun’s total power output, called its luminosity. How much power does the Sun put out, how much of it does Earth intercept, and how much arrives on an average square meter of Earth, day side and night side together?", "model": "The irradiance, the Earth–Sun distance, and Earth’s radius are published; perfect inverse-square spreading, parallel rays at Earth, and a spherical Earth are assumptions.", "sources": ["tsi2011", "sunfacts", "earth"], "work": ["Before (a): Write the outward unit normal $\\mathbf n$ on the sphere $|\\mathbf r|=a$ centered on the Sun, and evaluate $\\mathbf F\\cdot\\mathbf n$ there without parametrizing.", "After (a): Explain why the flux is the same for every $a$, and what physical fact that expresses.", "Before (b): Set up the power Earth absorbs, $\\iint Sz/R\\,dS$ over the day hemisphere $z\\ge0$, using $dS=R^2\\sin\\phi\\,d\\phi\\,d\\theta$ with the correct range of $\\phi$.", "After (b): Interpret $\\iint z\\,dS\\big/\\iint 1\\,dS$ over a hemisphere as the height of the center of mass of a thin hemispherical shell.", "Compare that height with the solid half-ball’s $3a/8$, explain the difference, and say which one is the day-side average of $\\cos\\zeta$, where $\\zeta$ is the Sun’s angle from straight overhead."], "questions": [{"prompt": "Find the outward flux of $\\mathbf F$ through the sphere of radius $a$ centered on the Sun, in yottawatts ($1$ YW $=10^{24}$ W). Convert $d$ to meters first. Your answer should not depend on $a$.", "expected": "4*pi*149.6^2*1360.8/10^6", "units": "YW", "kind": "number", "tolerance": 1e-05, "hints": ["On this sphere F points along n = r/a, so F · n is the constant S d²/a².", "Multiply that constant by the sphere’s area 4πa², with d = 1.496e11 m."], "id": "w08-p1-a", "label": "a"}, {"prompt": "For the upper hemisphere $H$ ($z\\ge0$, curved part only) of the sphere of radius $a$ centered at the origin, find $\\iint_H z\\,dS$ as a function of $a$.", "expected": "pi*a^3", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["Use z = a cos φ and dS = a² sin φ dφ dθ; the upper hemisphere is 0 ≤ φ ≤ π/2.", "The φ-integral of cos φ sin φ from 0 to π/2 is 1/2."], "id": "w08-p1-b", "label": "b"}, {"prompt": "Using part (b) with $a=R$, find the solar power Earth absorbs per square meter, averaged over its whole surface (day side and night side together), in W/m$^2$.", "expected": "1360.8/4", "units": "W/m²", "kind": "number", "tolerance": 1e-05, "hints": ["The absorbed power is (S/R) times your part (b) answer with a = R.", "Divide that power by the area of the whole sphere, the integral of 1 dS, which is 4πR²."], "id": "w08-p1-c", "label": "c"}], "solution": ["Flux through a sphere: On $|\\mathbf r|=a$ the outward unit normal is $\\mathbf n=\\mathbf r/a$, and there $\\mathbf F=Sd^2\\,\\mathbf r/a^3$, so $\\mathbf F\\cdot\\mathbf n=Sd^2/a^2$ is constant. The flux is therefore $(Sd^2/a^2)(4\\pi a^2)=4\\pi d^2S=4\\pi(1.496\\times10^{11})^2(1360.8)\\approx3.827\\times10^{26}$ W $=382.71$ YW. This matches the published luminosity of $382.8$ YW.", "Why $a$ cancels: Every sphere around the Sun catches the same total power, because nothing between the spheres absorbs the light. This is energy conservation.", "Absorbed power: On the upper hemisphere of radius $a$, $z=a\\cos\\phi$ with $0\\le\\phi\\le\\pi/2$, so $\\iint_H z\\,dS=\\int_0^{2\\pi}\\!\\int_0^{\\pi/2}a\\cos\\phi\\,a^2\\sin\\phi\\,d\\phi\\,d\\theta=\\pi a^3$. With $a=R$, \\[\\iint_H\\frac{Sz}{R}\\,dS=\\frac SR\\,\\pi R^3=S\\pi R^2\\approx1.735\\times10^{17}\\text{ W}\\] for $R=6.371\\times10^6$ m. This is exactly the sunlight crossing a flat disk of radius $R$, the disk of Earth’s shadow.", "Center of mass: The shell’s area is $\\iint_H1\\,dS=2\\pi a^2$, so the center of mass of a thin hemispherical shell is at height $\\pi a^3/(2\\pi a^2)=a/2$. Bands of equal height on a sphere have equal area, so the shell’s mass is spread evenly in height. The solid half-ball’s center of mass, at $3a/8$, is lower because most of its volume sits near the flat base. Since $\\cos\\zeta=z/R$ on Earth’s day side, the day-side average of $\\cos\\zeta$ is the shell’s value $\\tfrac12$, not $\\tfrac38$.", "Global average: Averaging over the whole sphere means dividing by its area $\\iint 1\\,dS=4\\pi R^2$ (an area, not the volume $\\tfrac43\\pi R^3$). This gives $S\\pi R^2/(4\\pi R^2)=S/4=340.2$ W/m$^2$, the “about 340 W/m$^2$” of climate energy budgets."], "reflection": "A planet orbits twice as far from the Sun as Earth does. Without computing a new integral, what irradiance does it receive, and which part of your work justifies the answer?", "extension": false, "id": "w08-p1", "discussionSolution": "About 340 W/m², one quarter of S. The flux through every sphere centered on the Sun is the same luminosity L, so at distance 2d the irradiance is L/(4π(2d)²) = S/4. Part (a) justifies this: the flux does not depend on the radius, because nothing between the spheres absorbs light.", "modelSpec": {"data": ["Total solar irradiance at Earth’s distance: $S=1360.8$ W/m$^2$", "Mean Earth–Sun distance: $d=149.6\\times10^6$ km", "Earth’s mean radius: $R=6371$ km", "Published luminosity of the Sun (for checking): $382.8\\times10^{24}$ W"], "assume": ["Sunlight spreads out equally in all directions, and nothing between the Sun and Earth absorbs it.", "Near Earth the Sun is so far away that its rays are parallel.", "Earth is a perfect sphere."], "model": ["Sunlight (W/m$^2$), with the Sun at the origin: $\\mathbf F(\\mathbf r)=Sd^2\\,\\dfrac{\\mathbf r}{|\\mathbf r|^3}$", "Near Earth, with Earth’s center at the origin and the Sun in the $+z$ direction: $\\mathbf F=(0,0,-S)$; Earth is the sphere $x^2+y^2+z^2=R^2$", "Power absorbed per square meter at a day-side point ($z\\ge0$): $-\\mathbf F\\cdot\\mathbf n=Sz/R$ W/m$^2$"]}, "photo": {"alt": "The full disk of the Sun in ultraviolet light from NASA’s Solar Dynamics Observatory, with bright active regions and glowing magnetic loops", "credit": "NASA/SDO, ALMA (ESO/NAOJ/NRAO)", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Full_disk_of_the_Sun_(eso1703e-comparisona).jpg", "file": "w08-p1.jpg"}, "figure": {"alt": "Left: the Sun at the center of two concentric circles, labeled a1 and a2, crossed by the same straight rays pointing outward. Right: Earth as a circle with parallel vertical sunlight arriving from above; the upper half is highlighted as the day side, z at least 0, and the lower half is labeled night side", "caption": "The model. Left: the same radial rays cross every sphere of radius $a$ around the Sun, so each sphere catches the same total power. Right: near Earth the rays are parallel, $\\mathbf F=(0,0,-S)$, and they light only the day hemisphere $z\\ge0$.", "file": "w08-p1"}}, {"title": "How much sunlight do Noor’s mirrors catch?", "context": "Noor Ouarzazate I, on the edge of the Sahara in Morocco, is a 160 MW solar power plant that uses no solar panels. Instead, long curved mirrors called parabolic troughs track the Sun. Each trough’s cross-section is a parabola, so it focuses sunlight onto a pipe of hot oil running along its focal line. The plant’s mirror field is published by its aperture area, 1,308,000 m$^2$. The aperture of a trough is the flat opening across its top, which is smaller than the curved mirror itself. How much solar power do the mirrors catch, and why is it the aperture area, not the larger mirror area, that sets this power?", "model": "The plant’s size, aperture area, and trough dimensions are published; the strength of direct sunlight, perfect tracking, and the absence of losses are assumptions.", "sources": ["noor1", "sentrough"], "work": ["Sketch the cross-section $z=x^2/6.8$, $|x|\\le2.88$, with the focus and three vertical sunbeams, and draw the upward unit normal at $x=0$ and at the rim.", "After (a): Write $\\cos\\alpha$ as a function of $x$.", "Before (b): Write $\\iint_S f\\,dS$ over one 12 m module as a double integral over its shadow, including the factor $\\sqrt{1+g_x^2+g_y^2}$, and spot the cancellation before integrating.", "Set up the mirror area $\\iint_S1\\,dS$ of the same module, and decide without evaluating whether it is larger or smaller than the $5.76\\times12$ m$^2$ aperture.", "Decide whether $\\iint_S1\\,dS$ could ever be the volume of the trough, and say why."], "questions": [{"prompt": "For the mirror $z=g(x,y)=x^2/6.8$, enter the upward vector area element $(-g_x,-g_y,1)$, the vector that multiplies $dA$ in $d\\mathbf S$.", "expected": ["-x/3.4", "0", "1"], "units": "", "kind": "vector", "tolerance": 1e-05, "hints": ["Differentiate g with respect to x and with respect to y; the trough is straight along y.", "g_y = 0, so only g_x needs simplifying; keep +1 as the third component for the upward orientation."], "id": "w08-p2-a", "label": "a"}, {"prompt": "Direct sunlight of $900$ W/m$^2$ arrives along every trough’s axis of symmetry. Using the published aperture area of $1{,}308{,}000$ m$^2$, find the total solar power reaching all the mirrors of Noor I, in megawatts.", "expected": "900*1308000/10^6", "units": "MW", "kind": "number", "tolerance": 1e-05, "hints": ["On each trough, f times the square-root factor is the constant 900: the cosine cancels the area factor.", "So the power is 900 W/m² times the shadow area, which is the aperture area, summed over the whole field."], "id": "w08-p2-b", "label": "b"}, {"prompt": "Sunlight is the field $\\mathbf F=(0,0,-900)$ W/m$^2$, and $D$ is the shadow of one module in the $xy$-plane. Which integral gives the solar power, in watts, that hits that module’s mirror?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The vector (−g_x, −g_y, 1) dA already equals n dS: it includes the area factor.", "The option with the length of F ignores the angle, so it counts light at full strength even where it strikes the mirror at a slant."], "options": ["$-\\iint_D\\mathbf F\\cdot(-g_x,-g_y,1)\\sqrt{1+g_x^2+g_y^2}\\,dA$", "$\\iint_D\\|\\mathbf F\\|\\sqrt{1+g_x^2+g_y^2}\\,dA$", "$-\\iint_D\\mathbf F\\cdot(-g_x,-g_y,1)\\,dA$", "$-\\iint_D\\mathbf F\\cdot\\dfrac{(-g_x,-g_y,1)}{\\sqrt{1+g_x^2+g_y^2}}\\,dA$"], "id": "w08-p2-c", "label": "c"}], "solution": ["Normal and $\\cos\\alpha$: $g_x=2x/6.8=x/3.4$ and $g_y=0$, so $(-g_x,-g_y,1)=(-x/3.4,0,1)$. Dividing by its length gives the upward unit normal $\\mathbf n$, so $\\cos\\alpha=\\mathbf n\\cdot\\mathbf k=1/\\sqrt{1+x^2/11.56}$. This is $1$ at the bottom and about $0.76$ at the rim.", "Weighted integral: For one module, \\[\\iint_S f\\,dS=\\int_0^{12}\\!\\!\\int_{-2.88}^{2.88}\\frac{900}{\\sqrt{1+x^2/11.56}}\\sqrt{1+\\frac{x^2}{11.56}}\\,dx\\,dy=900(5.76)(12)\\approx62.2\\text{ kW}.\\] The cosine cancels the area factor: tilted mirror receives less light per square meter by exactly the factor by which there is more of it.", "Mirror area: The mirror area is $\\iint_S1\\,dS=12\\int_{-2.88}^{2.88}\\sqrt{1+x^2/11.56}\\,dx\\approx76.67$ m$^2$. That is about $11\\%$ more than the $69.12$ m$^2$ aperture, because the square-root factor exceeds $1$ away from $x=0$. It is an area in m$^2$, never a volume.", "Choosing the flux formula: Flux uses $\\mathbf F\\cdot d\\mathbf S=\\mathbf F\\cdot(-g_x,-g_y,1)\\,dA$ with no extra square root. Here that is $-900\\,dA$. The flux of downward light through the upward-oriented mirror is negative, so the minus sign in front turns it into absorbed power. The option with an extra root counts the area factor twice. The one with $\\|\\mathbf F\\|$ gives $900$ W/m$^2$ times the mirror area. The one that divides by the root uses the unit normal but leaves out the area factor in $dS$.", "Whole field: Summing over all modules, the power is $900$ W/m$^2$ times the total aperture area, $900\\times1{,}308{,}000$ W $=1177.2$ MW. The $160$ MW turbine rating is about $14\\%$ of this. The collected power depends only on the aperture, which is why the aperture area is the number that matters."], "reflection": "A trough turns about a single axis, its long axis, so the sunlight usually arrives at an angle $\\beta$ to the trough’s axis of symmetry, tilted along the trough’s length. Should the collected power then go up, go down, or stay the same, and which factor in your integral changes?", "extension": false, "id": "w08-p2", "discussionSolution": "It goes down, by the factor $\\cos\\beta$. With the light tilted along the trough, $\\mathbf F=900(0,\\sin\\beta,-\\cos\\beta)$ W/m$^2$, and since $g_y=0$, $-\\mathbf F\\cdot(-g_x,-g_y,1)=900\\cos\\beta$: the constant $900$ in the integrand becomes $900\\cos\\beta$. Only the component of sunlight along the aperture’s normal is collected, and this “cosine loss” is why trough fields track the Sun.", "modelSpec": {"data": ["Turbine capacity: $160$ MW", "Solar-field aperture area: $1{,}308{,}000$ m$^2$", "SENER trough (2007 design): aperture width $5.76$ m, focal length $1.70$ m, module length $12$ m"], "assume": ["Every trough is a perfect parabolic cylinder with the published SENER dimensions.", "Direct sunlight of $900$ W/m$^2$ arrives along each trough’s axis of symmetry (perfect tracking).", "Gaps, shading, dust, and reflection losses are ignored."], "model": ["Mirror of one module: $z=g(x,y)=\\dfrac{x^2}{4(1.70)}=\\dfrac{x^2}{6.8}$ over $-2.88\\le x\\le2.88$, $0\\le y\\le12$ (meters)", "Sunlight: $\\mathbf F=(0,0,-900)$ W/m$^2$; the focus is $1.70$ m above the vertex", "Sunlight per square meter of mirror: $f=900\\cos\\alpha$ W/m$^2$, where $\\alpha$ is the angle between the upward unit normal and the vertical"]}, "photo": {"alt": "Rows of parabolic trough mirrors of Noor Ouarzazate I and II stretching across the desert near Ouarzazate, Morocco", "credit": "Richard Allaway", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Noor_1_and_2_-_Ouarzazate_Solar_Power_Station_(48962353822).jpg", "file": "w08-p2.jpg"}, "figure": {"alt": "Cross-section of the parabolic trough, a U-shaped curve 5.76 m wide, with vertical sunbeams that reflect off the curve to the focus above its center. Orange arrows show the unit normal at the center, pointing straight up, and at the right rim, tilted toward the center", "caption": "Cross-section of one trough, to scale in meters: the mirror $z=x^2/6.8$, the $5.76$ m aperture, and the focus $1.70$ m above the vertex. Vertical sunbeams reflect to the focus. The orange arrows are upward unit normals $\\mathbf n$; at the rim, $\\mathbf n$ tilts away from the vertical by the angle $\\alpha$.", "file": "w08-p2"}}, {"title": "Walk or run to class in the rain?", "context": "A winter storm rolls in off Monterey Bay just as you leave a UC Santa Cruz lecture hall. Your next class is 100 m away, and you have no umbrella. Should you walk or run? Physicists still publish on this question. In 2012, F. Bocci showed that the best strategy depends on the shape of the moving body and on the wind. Flux integrals answer the question when there is no wind. How much rain lands on you, as a function of your speed, and does running keep you drier?", "model": "Typical heavy-rain intensity and drop speed are published; the cylindrical body, still air, and constant speed are assumptions.", "sources": ["usgsrain", "bocci2012"], "work": ["Sketch your body (the cylinder) from the side and from above, with the rain velocity $(-v,0,-u)$ that you see.", "Before (a): Give the domain of $\\Phi(\\theta,z)=(0.15\\cos\\theta,0.15\\sin\\theta,z)$, the parametrization of the side.", "After (a): Decide whether $\\Phi_\\theta\\times\\Phi_z$ points outward or inward, and say what happens if you list the parameters in the order $(z,\\theta)$.", "Compute the flux of $\\mathbf F$ through the top disk with the upward normal, and explain its sign.", "After (b): On the front half ($\\cos\\theta>0$), water lands at $g=\\rho v\\cos\\theta$ m$^3$ per square meter of shirt per second. Compute $\\iint g\\,dS$ there and compare it with (b).", "Explain why the outward flux of $\\mathbf F$ through the whole side is $0$, and why that is not the amount of water you collect."], "questions": [{"prompt": "For the side parametrized by $\\Phi(\\theta,z)=(0.15\\cos\\theta,0.15\\sin\\theta,z)$, enter $\\Phi_\\theta\\times\\Phi_z$ as a function of $\\theta$.", "expected": ["0.15*cos(theta)", "0.15*sin(theta)", "0"], "units": "m", "kind": "vector", "tolerance": 1e-05, "hints": ["Differentiate Φ with respect to θ and with respect to z, then take the cross product in the order Φ_θ × Φ_z.", "Φ_θ = (−0.15 sin θ, 0.15 cos θ, 0) and Φ_z = (0, 0, 1)."], "id": "w08-p3-a", "label": "a"}, {"prompt": "Walking at $v=1.5$ m/s, find the outward flux of $\\mathbf F$ through the front half of the side ($\\cos\\theta\\ge0$), in milliliters per second ($1$ m$^3=10^6$ mL).", "expected": "-10^6*2*0.15*1.7*(0.0152/3600/6.7)*1.5", "units": "mL/s", "kind": "number", "tolerance": 1e-05, "hints": ["On the side, F · (Φ_θ × Φ_z) = −0.15 ρ v cos θ; integrate over −π/2 ≤ θ ≤ π/2 and 0 ≤ z ≤ 1.7.", "Use ρ = R/u with R = 0.0152/3600 m/s and u = 6.7 m/s, then convert m³ to mL. Expect a negative answer."], "id": "w08-p3-b", "label": "b"}, {"prompt": "You cross the $100$ m at constant speed $v$ (in m/s). Counting only the top disk and the front half of the side, find the total volume of water that lands on you, in mL, as a function of $v$.", "expected": "10^8*(0.0152/3600)*(pi*0.15^2/v+2*0.15*1.7/6.7)", "units": "mL", "kind": "expression", "tolerance": 1e-05, "hints": ["The trip takes 100/v seconds; multiply the water landing on you per second by this time.", "Per second, R times the disk area lands on the top, and ρv times 2(0.15)(1.7) lands on the front."], "id": "w08-p3-c", "label": "c"}], "solution": ["Orientation: On the domain $0\\le\\theta\\le2\\pi$, $0\\le z\\le1.7$, $\\Phi_\\theta=(-0.15\\sin\\theta,0.15\\cos\\theta,0)$ and $\\Phi_z=(0,0,1)$, so $\\Phi_\\theta\\times\\Phi_z=(0.15\\cos\\theta,0.15\\sin\\theta,0)$. At $\\theta=0$ it is $(0.15,0,0)$, which points away from the axis, so it is outward. Listing the parameters as $(z,\\theta)$ gives $\\Phi_z\\times\\Phi_\\theta=-(\\Phi_\\theta\\times\\Phi_z)$, the inward normal; to keep the outward orientation you would have to negate it.", "Top disk: The water fraction is $\\rho=R/u=(0.0152/3600)/6.7\\approx6.30\\times10^{-7}$, so rain is less than a millionth water by volume. The top disk has upward normal $\\mathbf k$, and $\\mathbf F\\cdot\\mathbf k=-\\rho u=-R$, so its flux is $-R\\pi(0.15)^2\\approx-0.298$ mL/s at any speed. It is negative because the rain moves down through a disk oriented up.", "Front half: On the side, $\\mathbf F\\cdot(\\Phi_\\theta\\times\\Phi_z)=-0.15\\rho v\\cos\\theta$. Over the front half, \\[\\int_0^{1.7}\\!\\!\\int_{-\\pi/2}^{\\pi/2}-0.15\\rho v\\cos\\theta\\,d\\theta\\,dz=-2(0.15)(1.7)\\rho v\\approx-0.482\\text{ mL/s}\\] at $v=1.5$ m/s. It is negative because the rain enters your body through the outward-oriented front.", "Scalar integral: With $dS=0.15\\,d\\theta\\,dz$, $\\iint g\\,dS$ over the front half gives $+0.482$ mL/s. It has the same size as (b) but is positive, because a scalar integral carries no orientation.", "Whole side: The back half has outward flux $+0.482$ mL/s, so the whole side gives $0$: without your body, the rain entering through the front would leave through the back. But your body blocks the rain, so the back stays dry and only the inward flux through the front wets you.", "Total water: The trip takes $100/v$ seconds, so \\[W(v)=\\frac{100}{v}\\big(R\\pi(0.15)^2+2(0.15)(1.7)\\rho v\\big)\\times10^6=\\frac{29.85}{v}+32.14\\text{ mL}.\\] Walking ($v=1.5$ m/s) collects about $52$ mL and running ($v=5$ m/s) about $38$ mL, so running helps, but only partly. The front term does not depend on speed: you sweep out the same rainy volume however fast you go. Running only shortens the time the top is exposed."], "reflection": "A 2 m/s tailwind blows the rain forward, in your direction of travel. At what running speed does the front of your shirt stay dry, and what does this suggest about Bocci’s finding that shape and wind matter?", "extension": false, "id": "w08-p3", "discussionSolution": "At 2 m/s. In your frame the rain’s horizontal velocity is 2 − v m/s, which is zero at v = 2 m/s, so only the top gets wet. Running faster wets your front, and running slower wets your back. With wind there can be a best speed, and how much it helps depends on the ratio of top area to front area, that is, on the body’s shape.", "modelSpec": {"data": ["Heavy rain (typical): intensity $1.52$ cm/h", "Median drop diameter $2.05$ mm; fall velocity $6.7$ m/s"], "assume": ["Your body is a vertical cylinder of radius $0.15$ m and height $1.7$ m.", "The air is still: rain falls straight down at $u=6.7$ m/s, and you move in the $+x$ direction at constant speed $v$.", "Rain lands only on surfaces moving into it, so your body shelters its back half.", "Your class is $100$ m away."], "model": ["Rain rate $R=0.0152/3600$ m/s; water fraction of the air (m$^3$ of water per m$^3$ of air) $\\rho=R/u$", "In your frame the rain velocity is $(-v,0,-u)$, and the water-flux field is $\\mathbf F=\\rho\\,(-v,0,-u)$ (m$^3$ of water per m$^2$ per s)", "Body: side $x^2+y^2=0.15^2$, $0\\le z\\le1.7$, and top disk at $z=1.7$ (meters)"]}, "photo": {"alt": "A rain-soaked footbridge through misty redwood and oak forest on the UC Santa Cruz campus", "credit": "Busition", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:UC_Santa_Cruz_Bridge.jpg", "file": "w08-p3.jpg"}, "figure": {"alt": "Left, side view: a tall cylinder 1.7 m high representing your body, moving to the right, with rain arrows slanting down and to the left; the top and the right-hand (front) side are highlighted. Right, view from above: a circle with rain arrows arriving from the right, the front half highlighted and the back half labeled sheltered", "caption": "The model in your frame: you move in the $+x$ direction, and the rain arrives with velocity $(-v,0,-u)$. The top disk and the front half of the side, where $\\cos\\theta>0$ (teal), get wet; the back half is sheltered.", "file": "w08-p3"}}, {"title": "How fast is the universe making room?", "context": "Distant galaxies are moving away from us, each at a speed proportional to its distance. This is Hubble’s law, and the constant of proportionality is the Hubble constant $H_0$, measured in km/s per megaparsec (one megaparsec, Mpc, is about $3.09\\times10^{22}$ m). Two precise measurements of $H_0$ disagree, a puzzle called the “Hubble tension.” The Planck satellite’s map of the cosmic microwave background gives $67.4$ km/s/Mpc, while Cepheid stars and supernovae (the SH0ES team, using the Hubble Space Telescope) give $73.04$. How fast does a region of space that moves with the galaxies gain volume?", "model": "The values of the Hubble constant are published; treating the galaxies as a smooth fluid that moves exactly with the Hubble flow is an assumption.", "sources": ["planck2018", "shoes2022", "pdgastro"], "work": ["Sketch $W$ with a few velocity arrows on its dome and on its base.", "Before (a): Give the outward unit normal on the dome and on the base, and compute $\\mathbf v\\cdot\\mathbf n$ on each without parametrizing.", "Before (b): Explain why the base contributes nothing even though the galaxies on it are moving.", "After (b): Say what the ratio of total outward flux to volume means for a region carried along by the flow.", "Before (c): Write $\\mathbf v=H(\\mathbf r-\\mathbf p)+H\\mathbf p$, and use symmetry to explain why the flux through a sphere centered on another galaxy at $\\mathbf p$ matches that of a sphere centered on us."], "questions": [{"prompt": "Find the outward flux of $\\mathbf v$ through the dome of $W$ (the curved part only), in Mpc$^3$/Gyr, as a function of $a$.", "expected": "2*pi*0.0689*a^3", "units": "Mpc³/Gyr", "kind": "expression", "tolerance": 0.002, "hints": ["On the dome n = r/a, so v · n = H a everywhere.", "Multiply by the hemisphere’s area 2πa²."], "id": "w08-p4-a", "label": "a"}, {"prompt": "Find the total outward flux of $\\mathbf v$ through the boundary of $W$ (dome and base) divided by the volume of $W$, in Gyr$^{-1}$.", "expected": "3*0.0689", "units": "per Gyr", "kind": "number", "tolerance": 1e-05, "hints": ["On the base the outward normal is (0, 0, −1), and v · n = −H z = 0 there.", "The half-ball’s volume is (2/3)πa³."], "decimals": 3, "id": "w08-p4-b", "label": "b"}, {"prompt": "Find the outward flux of $\\mathbf v$ through the sphere of radius $a$ centered on another galaxy at position $\\mathbf p$, in Mpc$^3$/Gyr, as a function of $a$.", "expected": "4*pi*0.0689*a^3", "units": "Mpc³/Gyr", "kind": "expression", "tolerance": 0.002, "hints": ["On this sphere n = (r − p)/a, so v · n = H a + H p · n.", "The constant field H p has zero net flux through the sphere, because p · n changes sign between opposite points."], "id": "w08-p4-c", "label": "c"}], "solution": ["Dome: On the dome $\\mathbf n=\\mathbf r/a$, so $\\mathbf v\\cdot\\mathbf n=H\\,\\mathbf r\\cdot\\mathbf r/a=Ha$, a constant. The flux is $Ha\\cdot2\\pi a^2=2\\pi Ha^3\\approx0.433\\,a^3$ Mpc$^3$/Gyr with $H=0.0689$ Gyr$^{-1}$.", "Base: On the base $z=0$ the outward normal points down, $\\mathbf n=(0,0,-1)$, so $\\mathbf v\\cdot\\mathbf n=-Hz=0$. Galaxies in that plane move along it, not across it. The total outward flux is therefore $2\\pi Ha^3$.", "Flux per volume: Dividing by the volume $\\tfrac23\\pi a^3$ gives $3H\\approx0.207$ Gyr$^{-1}$, whatever the value of $a$. So a region carried along by the flow gains volume at about $21\\%$ per billion years at today’s rate. With the SH0ES value it would be $3\\times0.0747\\approx0.224$ Gyr$^{-1}$.", "Another center: On the sphere about $\\mathbf p$, $\\mathbf n=(\\mathbf r-\\mathbf p)/a$ and $\\mathbf v\\cdot\\mathbf n=Ha+H\\,\\mathbf p\\cdot\\mathbf n$. The first term gives $Ha\\cdot4\\pi a^2=4\\pi Ha^3$. The second integrates to zero because opposite points of the sphere have opposite $\\mathbf n$. So the flux is $4\\pi Ha^3$, the same as for a sphere centered on the Milky Way: every galaxy sees the same expansion, and the flow singles out no center."], "reflection": "The ratio of flux to volume was $3H$ for the half-ball in (b) and for the sphere in (c). Guess the ratio for a cube of side $s$ centered on us, check it face by face, and say which general theorem this previews.", "extension": false, "id": "w08-p4", "discussionSolution": "Also 3H. For the cube centered on us, the face x = s/2 has v · n = Hs/2 and area s², so it contributes Hs³/2; the six faces give 3Hs³, and dividing by the volume s³ gives 3H, which is div v. This previews the Divergence Theorem: the outward flux through any closed surface equals the integral of div v over the enclosed volume.", "modelSpec": {"data": ["Planck 2018: $H_0=67.4\\pm0.5$ km/s/Mpc", "SH0ES 2022: $H_0=73.04\\pm1.04$ km/s/Mpc", "Conversion: $100$ km/s/Mpc $=(9.777752$ Gyr$)^{-1}$, so $67.4$ km/s/Mpc $\\approx0.0689$ Gyr$^{-1}$"], "assume": ["Galaxies move exactly with the Hubble flow (no local motions), and the Milky Way is at the origin.", "The Planck value $H=0.0689$ Gyr$^{-1}$ is used; lengths are in Mpc and times in Gyr."], "model": ["Velocity field: $\\mathbf v=H\\mathbf r=H(x,y,z)$ Mpc/Gyr", "Region $W$: the half-ball $x^2+y^2+z^2\\le a^2$, $z\\ge0$, bounded by a dome and a flat base disk in the plane $z=0$"]}, "photo": {"alt": "The Hubble Ultra Deep Field: thousands of distant galaxies of many shapes and colours scattered across a black sky", "credit": "NASA and the European Space Agency", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Hubble_ultra_deep_field.jpg", "file": "w08-p4.jpg"}, "figure": {"alt": "Cross-section of the half-ball region: a semicircular dome on a flat base, with the Milky Way at the center of the base. Velocity arrows point straight out from the center and get longer farther away; the arrows on the base lie along it", "caption": "Cross-section of the region $W$: the dome, the base $z=0$, and the Hubble-flow arrows $\\mathbf v=H\\mathbf r$, which grow with distance from the Milky Way at the center. On the base the arrows lie along it, not across it.", "file": "w08-p4"}}, {"title": "Saharan dust across the Atlantic", "context": "Every year the trade winds lift dust off the Sahara and carry it west across the Atlantic. A team led by Hongbin Yu used NASA’s CALIPSO satellite, which tracked the dust in three dimensions from 2007 to 2013. They estimated how much dust crosses imaginary vertical “curtains” of air at fixed longitudes, and how much falls on the Amazon rainforest, where its phosphorus acts as fertilizer. How much dust crosses each square meter of a curtain, does tilting the curtain change the total, and how much dust falls into the ocean between two curtains?", "model": "The yearly dust totals are published multi-year averages; the curtain size, horizontal westward motion, and steady state are assumptions.", "sources": ["saharadust"], "work": ["Sketch the curtain at $15^\\circ$W and the closed box from it to the $35^\\circ$W curtain; mark each outward normal.", "Before (b): For the tilted curtain $x=g(y,z)=-z/5$ with $\\Phi(y,z)=(g(y,z),y,z)$, compute $\\Phi_y\\times\\Phi_z$, say whether it points east or west, and write the westward vector area element.", "After (b): Explain why tilting the curtain does not change the flux of horizontally moving dust (compare it with its shadow on the plane $x=0$).", "Before (c): Write the dust budget for the closed box face by face (east, west, bottom, top, sides), and explain why in steady state its total outward flux is zero."], "questions": [{"prompt": "Find the average westward dust flux through the $15^\\circ$W curtain, in kilograms per square meter per year.", "expected": "182*10^9/(3*10^6*5*10^3)", "units": "kg/(m²·yr)", "kind": "number", "tolerance": 1e-05, "hints": ["The average flux is the yearly mass divided by the curtain’s area; 182 million tonnes is 1.82e11 kg.", "The curtain is 3000 km by 5 km; convert both to meters before dividing."], "id": "w08-p5-a", "label": "a"}, {"prompt": "Find the westward flux of dust through the tilted curtain $x=-z/5$ (same $y$ and $z$ ranges), in millions of tonnes per year.", "expected": "182", "units": "Mt/yr", "kind": "number", "tolerance": 1e-05, "hints": ["With the westward element (−1, g_y, g_z) dy dz, F · dS = f(y, z) dy dz.", "That is the same integrand, over the same rectangle, as for the vertical curtain."], "id": "w08-p5-b", "label": "b"}, {"prompt": "Using the closed box between the $15^\\circ$W and $35^\\circ$W curtains, find how much dust per year falls into the ocean between them, in millions of tonnes.", "expected": "182-132", "units": "Mt/yr", "kind": "number", "tolerance": 1e-05, "hints": ["Outward flux: −182 through the east face (dust enters) and +132 through the west face.", "The bottom’s outward normal points down; the top and sides carry nothing in the model."], "id": "w08-p5-c", "label": "c"}], "solution": ["Average flux: $182$ million tonnes per year is $1.82\\times10^{11}$ kg per year. The curtain’s area is $(3\\times10^6)(5\\times10^3)=1.5\\times10^{10}$ m$^2$, so the average flux is the total divided by the area, about $12.13$ kg per m$^2$ per year.", "Tilted curtain: For $\\Phi(y,z)=(-z/5,y,z)$, $\\Phi_y=(0,1,0)$ and $\\Phi_z=(-\\tfrac15,0,1)$, so $\\Phi_y\\times\\Phi_z=(1,0,\\tfrac15)$, which points east. The westward element is therefore $(-1,0,-\\tfrac15)\\,dy\\,dz$. With $\\mathbf F=(-f,0,0)$, $\\mathbf F\\cdot d\\mathbf S=f\\,dy\\,dz$: the same integrand over the same rectangle as for the vertical curtain, so the flux is still $182$ Mt/yr.", "Why the tilt does not matter: The dust moves horizontally, so only the curtain’s shadow on the plane $x=0$, perpendicular to the flow, matters. The tilted curtain and the vertical one have the same shadow.", "Box budget: The outward fluxes are $-182$ Mt/yr through the east face (dust entering), $+132$ Mt/yr through the west face, and $0$ through the top and sides by assumption. The bottom, whose outward normal points down, carries the deposition $D$. In steady state no dust is created or stored inside, so the total outward flux is zero: $-182+132+D=0$, which gives $D=50$ Mt/yr.", "Interpretation: Of the $182$ Mt/yr that crosses $15^\\circ$W, about $50$ Mt/yr falls into the ocean before $35^\\circ$W. Farther west, about $27.7$ Mt/yr ($15\\%$ of $182$) falls on the Amazon basin, and about $43$ Mt/yr travels past $75^\\circ$W to the Caribbean."], "reflection": "The tilted curtain carried the same flux as the vertical one. What assumption about the dust’s motion made that true, and would it still be true if the dust were also settling downward?", "extension": true, "id": "w08-p5", "discussionSolution": "The assumption that the dust moves horizontally. The vertical curtain, the tilted curtain, the 1 km wide strip joining their top edges, and the two triangular ends enclose a thin wedge. With horizontal flow no dust crosses the top strip or the ends, and in steady state none is created or stored inside, so the two curtains carry the same flux. If the dust also settles downward, this fails: dust falls into the wedge through the top strip and leaves through the tilted curtain, so the tilted curtain carries slightly more than the vertical one.", "modelSpec": {"data": ["Dust carried past $15^\\circ$W: $182$ million tonnes per year", "Still airborne at $35^\\circ$W: $132$ million tonnes per year", "Falling on the Amazon basin: $27.7$ million tonnes per year; past $75^\\circ$W: about $43$ million"], "assume": ["The curtain at $15^\\circ$W is a vertical rectangle $3000$ km wide (north–south) and $5$ km tall.", "Dust moves horizontally westward, so nothing crosses the top or the north and south sides of the box between $15^\\circ$W and $35^\\circ$W.", "Steady state: the yearly averages do not change with time."], "model": ["$x$ east, $y$ north, $z$ up (km); curtain: $x=0$, $0\\le y\\le3000$, $0\\le z\\le5$", "Dust mass flux: $\\mathbf F=(-f(y,z),0,0)$, with $\\iint f\\,dy\\,dz=182$ Mt/yr over the curtain", "Tilted curtain: $x=-z/5$ over the same $y$, $z$ rectangle"]}, "figure": {"alt": "Schematic of the tropical Atlantic with West Africa on the right and South America on the left. Two vertical curtains, at 15 degrees west and 35 degrees west, bound a closed box. Westward dust arrows are labeled 182 and 132 million tonnes per year, arrows from the box floor mark an unknown deposition, and a dashed arrow labeled 27.7 points to the Amazon", "caption": "Schematic, not to scale: the curtains at $15^\\circ$W and $35^\\circ$W with the published yearly dust totals ($182$ and $132$ million tonnes), and the closed box between them. The deposition through the box’s bottom is the unknown.", "file": "w08-p5"}}]}, {"week": 9, "title": "Boundaries that know the inside", "subtitle": "It’s Not Easy Being Green", "skills": ["Orient boundaries positively, including boundaries of regions with holes", "Verify Green’s theorem edge by edge, and use it to avoid hard line integrals", "Find areas and centroids from boundary data (ellipses, polygons, planimeters)", "Excise a small circle around a singularity, and decide when a circulation is zero", "Review sphere symmetry for surface integrals and flux (Quiz 3)"], "formulas": ["$\\oint_{\\partial D}P\\,dx+Q\\,dy=\\iint_D\\Big(\\dfrac{\\partial Q}{\\partial x}-\\dfrac{\\partial P}{\\partial y}\\Big)dA$, $\\partial D$ positively oriented (region on the left), $P,Q$ continuously differentiable on an open set containing $D$", "Area, with $\\partial D$ positively oriented: $A=\\oint_{\\partial D}x\\,dy=-\\oint_{\\partial D}y\\,dx=\\tfrac12\\oint_{\\partial D}x\\,dy-y\\,dx$", "Flux form, with $\\mathbf n$ the outward unit normal: $\\oint_{\\partial D}\\mathbf F\\cdot\\mathbf n\\,ds=\\oint_{\\partial D}F_1\\,dy-F_2\\,dx=\\iint_D\\Big(\\dfrac{\\partial F_1}{\\partial x}+\\dfrac{\\partial F_2}{\\partial y}\\Big)dA$"], "sources": ["noaastations", "bermuda", "orange", "haiyan", "imoseac", "vitrovex", "agulhas"], "problems": [{"title": "Measuring the Bermuda Triangle from its edges", "context": "A 1964 magazine article drew a “Bermuda Triangle” between Miami, Bermuda, and San Juan and blamed it for vanished ships and planes. NOAA finds no evidence that disappearances happen there more often than anywhere else, but the triangle still makes a good test shape. Before computers, chart-makers measured areas with a planimeter: an instrument with an arm whose tracer point you run once around a boundary while a small wheel rolls along the paper. The wheel’s roll gives the area. Mapping software today does the same job from boundary coordinates alone. How can one trip around the edge tell you the area inside, and where the region’s center is?", "model": "The three station positions are published; the flat chart, the rounded vertices, and the idealized planimeter are modeling choices.", "sources": ["noaastations", "bermuda"], "work": ["Orient $\\partial T$ positively (in which order are M, S, B visited?) and parametrize each edge for $0\\le t\\le1$.", "Before (b): Check the hypotheses of Green’s theorem for the planimeter field, and explain why $|y|<L$ must hold on the whole region.", "Before (b): Show that the wheel roll is $A/L$ for any traced region, and say what the wheel shows if traced clockwise.", "After (c): Check (c) with $\\iint_T2x\\,dA$, then find $\\bar x=\\frac1{2A}\\oint_{\\partial T}x^2\\,dy$ and mark the centroid.", "Review: Compute $\\int x\\,ds$ along the Miami–San Juan edge."], "questions": [{"prompt": "Before tracing the triangle, an operator checks (calibrates) the planimeter on a shape whose area is known exactly. Use $A=\\tfrac12\\oint x\\,dy-y\\,dx$ to find the area of the calibration ellipse $x=6\\cos t$, $y=4\\sin t$ (in cm), $0\\le t\\le2\\pi$.", "expected": "24*pi", "units": "cm²", "kind": "number", "tolerance": 1e-05, "hints": ["Substitute the parametrization: dx = −6 sin t dt and dy = 4 cos t dt.", "The integrand simplifies to x dy − y dx = 24 dt. Integrate over 0 ≤ t ≤ 2π, then halve."], "id": "w09-p1-a", "label": "a"}, {"prompt": "Using the planimeter model with $L=10$ cm, find the wheel roll when the tracer goes once counterclockwise around the triangle $T$.", "expected": "11.3", "units": "cm", "kind": "number", "tolerance": 1e-05, "hints": ["Apply Green’s theorem with P = −y/L and Q = √(L² − y²)/L. Since Q depends on y only, Q_x − P_y = 1/L.", "So the roll is (area of T)/L. The area of T is half the cross product of the edge vectors from M to S and from M to B."], "id": "w09-p1-b", "label": "b"}, {"prompt": "With $\\partial T$ positively oriented, compute $\\oint_{\\partial T}x^2\\,dy$ edge by edge, in chart units (cm).", "expected": "2260", "units": "cm³", "kind": "number", "tolerance": 1e-05, "hints": ["Split ∂T into the edges M to S, S to B, and B to M, and parametrize each for 0 ≤ t ≤ 1.", "For example, on S to B: x = 14 + 2t and dy = 15 dt, so that piece is 15 ∫₀¹ (14 + 2t)² dt = 3380. The other two edges are negative."], "id": "w09-p1-c", "label": "c"}], "solution": ["Orientation and area: The counterclockwise order is M $\\to$ S $\\to$ B $\\to$ M, because $(14,-8)\\times(16,7)=14\\cdot7+8\\cdot16=226>0$. So the area of $T$ is $A=\\tfrac12(226)=113$ cm$^2$.", "Calibration ellipse (a): $x\\,dy-y\\,dx=(6\\cos t)(4\\cos t)\\,dt-(4\\sin t)(-6\\sin t)\\,dt=24\\,dt$, so $A=\\tfrac12\\int_0^{2\\pi}24\\,dt=24\\pi\\approx75.40$ cm$^2$.", "Hypotheses: Green’s theorem needs a positively oriented, piecewise-smooth simple closed boundary, and $P,Q$ continuously differentiable on an open set containing the region. Here $P=-y/L$ and $Q=\\sqrt{L^2-y^2}/L$. At $|y|=L$ the derivative $Q_y$ blows up, and beyond it $Q$ is undefined (the arm cannot reach that far from the rail), so we need $|y|<L$. With $L=10$ cm and $-8\\le y\\le7$ on $T$, the hypotheses hold.", "Wheel roll (b): Green’s theorem gives roll $=\\iint_T(0+\\tfrac1L)\\,dA=A/L=113/10=11.3$ cm, and the same argument gives $A/L$ for any region the tracer can reach. The awkward $\\sqrt{L^2-y^2}\\,dy$ term never needs integrating. On the calibration ellipse the wheel should roll $24\\pi/10\\approx7.54$ cm, which is how the operator checks the instrument. Tracing clockwise reverses the boundary, so the wheel reads $-11.3$ cm.", "Edge by edge (c): $\\int_0^1(14t)^2(-8)\\,dt=-\\tfrac{1568}3$, then $\\int_0^1(14+2t)^2(15)\\,dt=15(196+28+\\tfrac43)=3380$, and $\\int_0^1(16-16t)^2(-7)\\,dt=-\\tfrac{1792}3$. The total is $3380-1120=2260$ cm$^3$.", "Double-integral check and centroid: With $P=0$ and $Q=x^2$, Green’s theorem gives $\\oint_{\\partial T}x^2\\,dy=\\iint_T2x\\,dA=2A\\bar x$, so $\\bar x=2260/226=10$ cm. This matches the average of the vertices’ $x$-coordinates, $(0+14+16)/3=10$, which is the centroid of any triangle. Similarly $\\bar y=(0-8+7)/3=-\\tfrac13$ cm.", "Review: On M to S, $\\mathbf c(t)=(14t,-8t)$ has speed $\\sqrt{260}$, so $\\int x\\,ds=\\int_0^1 14t\\sqrt{260}\\,dt=7\\sqrt{260}\\approx112.9$ cm$^2$.", "On the map: $113$ cm$^2$ on the chart is $1.13$ million km$^2$. The spherical triangle through the three stations has about $1.15$ million km$^2$, so the flat chart loses little. The centroid $(10,-\\tfrac13)$ cm is about 1,000 km east of Miami, in open ocean north of Hispaniola."], "reflection": "Writers have given the Triangle areas from 1.3 to 3.9 million km². What does that range tell you, and what would you need before trusting a claim that the region is unusually dangerous?", "extension": false, "id": "w09-p1", "discussionSolution": "The range shows that the “Triangle” has no agreed boundary: its area depends on which vertices a writer picks, so it is a story, not a measurement. Before believing a claim of danger you would need a fixed boundary, a count of incidents, and the amount of shipping and air traffic inside it, compared with other busy regions. NOAA finds no evidence that disappearances there are more frequent than elsewhere.", "modelSpec": {"data": ["NOAA stations: Virginia Key (Miami) $25.73^\\circ$ N $80.16^\\circ$ W; Bermuda $32.37^\\circ$ N $64.70^\\circ$ W; San Juan $18.46^\\circ$ N $66.12^\\circ$ W", "Vertices (Gaddis, 1964): Miami, San Juan, Bermuda"], "assume": ["The chart is flat: distances east and north in km, measured at latitude $25.5^\\circ$ N and drawn at 1 cm $=100$ km", "Each vertex is rounded to the nearest 100 km (1 cm on the chart)", "The planimeter is an idealized linear one: the foot of the arm (length $L=10$ cm) slides along a rail on the $x$-axis, and the wheel at the tracer rolls only by the tracer’s motion perpendicular to the arm"], "model": ["Chart coordinates in cm, $x$ east and $y$ north, Miami at the origin. Triangle $T$: M $=(0,0)$, S $=(14,-8)$, B $=(16,7)$", "Wheel roll (cm) when the tracer goes once around a loop $C$: $\\dfrac1L\\oint_C-y\\,dx+\\sqrt{L^2-y^2}\\,dy$", "Calibration ellipse: $x=6\\cos t$, $y=4\\sin t$ cm, $0\\le t\\le2\\pi$"]}, "photo": {"alt": "A Keuffel and Esser polar planimeter, with its tracing arm and measuring wheel, in a green-lined case in front of a map", "credit": "Cantons-de-l'Est", "license": "CC BY-SA 4.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Planim%C3%A8tre_Keuffel_%26_Esser.jpg", "file": "w09-p1.jpg"}, "figure": {"alt": "Chart of triangle T with vertices M (Miami) at the origin, S (San Juan) at (14, −8), and B (Bermuda) at (16, 7). A planimeter rail runs along the x-axis, an arm of length 10 cm joins a point on the rail to the tracer on the edge from S to B, and a half-size calibration ellipse sits at the lower left.", "caption": "The chart model (1 cm $=100$ km): the triangle $T$ and the idealized planimeter. The foot of the arm (length $L$) slides along the rail $y=0$, and the wheel at the tracer rolls by the tracer’s motion perpendicular to the arm. The calibration ellipse is drawn at half size.", "file": "w09-p1"}}, {"title": "Every seat in the Roman theatre at Orange", "context": "The Roman theatre at Orange, in southern France, still has its stone seating: a half-ring of rows wrapped around the orchestra, the semicircular floor in front of the stage. How much seating area is there, and how far from the front of the stage does the average spectator sit? A surveyor’s software answers both questions using only the boundary of the seating, and you will do the same with Green’s theorem.", "model": "Both diameters are published; the exact half-ring, the rounded radii, and the flat plan view are assumptions.", "sources": ["orange"], "work": ["Sketch $D$, mark its four boundary pieces, and orient each so that $D$ stays on the left. Explain why the inner arc runs clockwise.", "Before (a): Use Green’s theorem to turn the area and first-moment boundary integrals into double integrals, set up in polar coordinates.", "Before (b): Explain why the two straight pieces add nothing to $-\\tfrac12\\oint y^2\\,dx$.", "After (c): Check the outer-arc piece directly with a parametrization.", "Find $\\bar y=M/A$, and estimate the capacity at $0.5$ m$^2$ per spectator."], "questions": [{"prompt": "Find the seating area $A$ of the model region $D$.", "expected": "1239.5*pi", "units": "m²", "kind": "number", "tolerance": 1e-05, "hints": ["Green’s theorem with ½(x dy − y dx) turns the boundary integral into ∬ 1 dA.", "In polar coordinates: ∫₀^π ∫ from 15 to 52 of r dr dθ."], "id": "w09-p2-a", "label": "a"}, {"prompt": "With $\\partial D$ positively oriented, find the inner arc’s contribution to $-\\tfrac12\\oint_{\\partial D}y^2\\,dx$.", "expected": "-2250", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Keeping D on the left, the inner arc runs clockwise, from (−15, 0) to (15, 0).", "Use x = 15 cos t, y = 15 sin t with t going from π down to 0. Then −½ y² dx = (15³/2) sin³t dt, and ∫₀^π sin³t dt = 4/3."], "id": "w09-p2-b", "label": "b"}, {"prompt": "Find the first moment of the seating about the stage line, $M=-\\tfrac12\\oint_{\\partial D}y^2\\,dx=\\iint_D y\\,dA$.", "expected": "2/3*(52^3-15^3)", "units": "m³", "kind": "number", "tolerance": 1e-05, "hints": ["Green’s theorem with P = −y²/2 and Q = 0 gives Q_x − P_y = y.", "In polar coordinates y dA = (r sin θ) r dr dθ, so ∬ y dA = ∫₀^π sin θ dθ · ∫ from 15 to 52 of r² dr."], "id": "w09-p2-c", "label": "c"}], "solution": ["Orientation: $D$ is $15\\le r\\le52$, $0\\le\\theta\\le\\pi$. Its positive boundary is the segment from $(15,0)$ to $(52,0)$, the outer arc counterclockwise to $(-52,0)$, the segment to $(-15,0)$, and the inner arc clockwise back to $(15,0)$. Along the inner arc the region lies outside the small circle, so keeping it on the left means going clockwise.", "Area (a): By Green’s theorem, $A=\\iint_D1\\,dA=\\int_0^\\pi\\!\\int_{15}^{52}r\\,dr\\,d\\theta=\\tfrac\\pi2(52^2-15^2)=1239.5\\pi\\approx3894.0$ m$^2$.", "Boundary pieces (b): On the two segments $y=0$, so $y^2\\,dx=0$. On the outer arc, $x=52\\cos t$, $y=52\\sin t$, $0\\le t\\le\\pi$, which gives $-\\tfrac12\\int_0^\\pi52^2\\sin^2t\\,(-52\\sin t)\\,dt=\\tfrac{52^3}2\\cdot\\tfrac43=\\tfrac23(52^3)$. The inner arc is the same computation with radius $15$ and $t$ running from $\\pi$ to $0$, so its piece is $-\\tfrac23(15^3)=-2250$ m$^3$.", "First moment (c): By Green’s theorem, $M=\\iint_D y\\,dA=\\int_0^\\pi\\sin\\theta\\,d\\theta\\int_{15}^{52}r^2\\,dr=\\tfrac23(52^3-15^3)\\approx91{,}488.7$ m$^3$, which matches the sum of the two arcs. So $\\bar y=M/A\\approx23.5$ m.", "In the theatre: the average spectator sits about $23.5$ m back from the front of the stage. At $0.5$ m$^2$ per person the model seats $3894/0.5\\approx7800$ spectators, a little above the published 5,850 to 7,300, because aisles and stairs, ignored in the model, take up part of the plan area."], "reflection": "Real Roman seating rises in stone steps away from the stage. Is the plan-view area you found more or less than the actual stone seat surface, and is $\\bar y$ the same as the average distance from a seat to the actors?", "extension": false, "id": "w09-p2", "discussionSolution": "Less, and no. The plan-view area is a projection, so the stepped stone surface (seat tops plus risers) is larger. $\\bar y$ is only the average horizontal distance from the stage line; the distance to the actors also includes each seat’s sideways offset and the height of the upper rows.", "modelSpec": {"data": ["Seating diameter: $103.63$ m", "Orchestra diameter: $29.9$ m", "Capacity: 5,850 to 7,300"], "assume": ["In plan view the seating is a flat, exact half-ring, with radii rounded to $15$ m and $52$ m", "The front of the stage is the line $y=0$ through the center of the orchestra", "Aisles and stairs are ignored, and spectators fill the seating area evenly"], "model": ["$D$: $15\\le r\\le52$, $0\\le\\theta\\le\\pi$ (meters), in polar coordinates centered on the orchestra", "Area $A=\\tfrac12\\oint_{\\partial D}x\\,dy-y\\,dx$; first moment $M=-\\tfrac12\\oint_{\\partial D}y^2\\,dx$; $\\bar y=M/A$"]}, "photo": {"alt": "Wide view of the Roman theatre at Orange: curved rows of stone seating wrap around the semicircular orchestra, facing the tall stage wall", "credit": "Benh LIEU SONG (Flickr)", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Roman_Theatre_in_Orange_2008.jpg", "file": "w09-p2.jpg"}, "figure": {"alt": "Plan view of a half-ring seating area between radii 15 m and 52 m, above a horizontal line marking the front of the stage; the semicircular orchestra fills the inside of the ring.", "caption": "Plan view of the model seating $D$ ($15\\le r\\le52$ m, $0\\le\\theta\\le\\pi$), with the front of the stage along $y=0$ and the orchestra inside the inner arc.", "file": "w09-p2"}}, {"title": "Circulation around Typhoon Haiyan", "context": "Typhoon Haiyan crossed the central Philippines on 8 November 2013 with 10-minute average winds of 65 m/s (about 230 km/h). The Japan Meteorological Agency, the regional center for the western Pacific, reported storm-force winds (at least 25 m/s) out to 150 km from the center. A simple model treats the wind outside the eye as an ideal vortex: the air circles the eye, and its speed falls like $1/r$ with distance $r$ from the center. The circulation around a closed loop adds up the part of the wind that blows along the loop. What is the circulation around a loop that encloses the eye, and does the shape of the loop matter?", "model": "The peak wind and the wind radii are published; the ideal-vortex model, its calibration at 150 km, and the loops are assumptions.", "sources": ["haiyan"], "work": ["Compute $Q_x-P_y$ for $r>0$.", "Before (a): Explain why Green’s theorem on the disk $r\\le150$ km would wrongly predict zero circulation.", "Before (b): Excise a small circle $C_\\varepsilon$ about the center, orient the boundary of the region between $C_\\varepsilon$ and the ellipse positively, and conclude without parametrizing the ellipse.", "After (c): Explain part (c) with Green’s theorem.", "Check the model: find its wind speed at JMA’s gale radius, $460$ km, and the radius where it reaches $65$ m/s. Say what these show about $1/r$."], "questions": [{"prompt": "Find the circulation of the wind counterclockwise around the circle $r=150$ km centered on the eye.", "expected": "27000*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["On this circle the wind is tangent to the circle, counterclockwise, with the calibrated speed of 90 km/h.", "For a tangent wind of constant speed, circulation = speed × length of the loop."], "id": "w09-p3-a", "label": "a"}, {"prompt": "Find the circulation of the wind around the ellipse $x^2/300^2+y^2/200^2=1$, traversed clockwise.", "expected": "-27000*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["Between the ellipse and a small circle around the eye the curl is zero, so by Green’s theorem the two loops, both taken counterclockwise, have equal circulation.", "Traversing the ellipse clockwise reverses the sign."], "id": "w09-p3-b", "label": "b"}, {"prompt": "Find the circulation of the wind counterclockwise around the circle of radius $100$ km centered at $(420,0)$ km.", "expected": "0", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["Check whether this circle encloses the eye.", "The field is smooth on the disk this circle bounds, and its curl is zero there."], "id": "w09-p3-c", "label": "c"}], "solution": ["Curl and hypotheses: For $r>0$, with $P=-\\tfrac{\\Gamma}{2\\pi}\\tfrac{y}{x^2+y^2}$ and $Q=\\tfrac{\\Gamma}{2\\pi}\\tfrac{x}{x^2+y^2}$, both $Q_x$ and $P_y$ equal $\\tfrac{\\Gamma}{2\\pi}\\tfrac{y^2-x^2}{(x^2+y^2)^2}$, so $Q_x-P_y=0$. But the field is undefined at the center, which lies in every disk around the eye. So Green’s theorem does not apply on the disk $r\\le150$, and its prediction of zero is wrong.", "Circle (a): On $r=150$ the wind is tangent with speed $\\Gamma/(2\\pi\\cdot150)=90$ km/h, so the circulation is $\\Gamma=2\\pi(150)(90)=27000\\pi\\approx84{,}823$ km$^2$/h. The same computation gives $\\Gamma$ on every circle centered on the eye.", "Excised region (b): Let $R_\\varepsilon$ be the region between the ellipse and $C_\\varepsilon$, with $\\varepsilon<200$. Its positive boundary is the ellipse counterclockwise plus $C_\\varepsilon$ clockwise. The field is smooth on $R_\\varepsilon$ with zero curl, so Green’s theorem gives $\\oint_{\\text{ellipse, ccw}}=\\oint_{C_\\varepsilon,\\text{ccw}}=\\Gamma$. Clockwise, the circulation is $-27000\\pi\\approx-84{,}823$ km$^2$/h.", "Loop that misses the eye (c): The disk $(x-420)^2+y^2\\le100^2$ does not contain the center, so Green’s theorem applies and gives $\\iint0\\,dA=0$.", "Model check: At $460$ km the model gives $90\\cdot150/460\\approx29$ km/h $\\approx8$ m/s, but JMA reported gale winds ($\\ge15$ m/s) that far north, so the real winds fall off more slowly than $1/r$. The model reaches $65$ m/s at $r=150\\cdot25/65\\approx58$ km, and closer in it predicts ever faster winds without limit. The ideal vortex is only a rough description of the winds outside the core."], "reflection": "Any loop that encloses the eye once has the same circulation. What is the circulation around a loop that circles the eye twice, and what does that suggest the circulation “counts”?", "extension": false, "id": "w09-p3", "discussionSolution": "Twice as much, $2\\Gamma$. Excising the center shows that any loop’s circulation is $\\Gamma$ times the number of times it winds counterclockwise around the eye. The circulation counts the vorticity (spin) concentrated in the core, here idealized as a point, not the details of the loop.", "modelSpec": {"data": ["Maximum 10-minute wind: $65$ m/s", "Central pressure: $895$ hPa", "Storm-force winds ($\\ge25$ m/s $=90$ km/h) out to $150$ km from the center", "Gale winds ($\\ge15$ m/s) out to $460$ km north and $330$ km south of the center"], "assume": ["Outside the eye, the wind is an ideal counterclockwise vortex, calibrated so that its speed is $90$ km/h at $r=150$ km", "The model does not apply in the eye, and the field is undefined at the center", "The map is flat, in km, with the eye at the origin"], "model": ["$\\mathbf v(x,y)=\\dfrac{\\Gamma}{2\\pi}\\,\\dfrac{(-y,\\ x)}{x^2+y^2}$ km/h for $(x,y)\\ne(0,0)$, with speed $\\Gamma/(2\\pi r)$ at distance $r$ km from the eye; $\\Gamma$ (km$^2$/h) is a constant fixed by the calibration", "Loops: the circle $r=150$; the ellipse $x^2/300^2+y^2/200^2=1$; the circle of radius $100$ about $(420,0)$"]}, "photo": {"alt": "Typhoon Haiyan seen from the International Space Station: a vast spiral of cloud over the western Pacific, with part of the station at the edge", "credit": "NASA/Karen Nyberg", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:Typhoon_Haiyan_viewed_from_International_Space_Station.jpg", "file": "w09-p3.jpg"}, "figure": {"alt": "Wind arrows circling counterclockwise around the eye. Three loops are drawn: the dashed circle of radius 150 km around the eye, a larger ellipse around the eye marked clockwise, and a small circle to the east that does not enclose the eye.", "caption": "The ideal-vortex model outside the eye (arrows) and the three loops: (a) the circle $r=150$, (b) the ellipse, traversed clockwise, and (c) the circle of radius $100$ about $(420,0)$, which does not enclose the eye. Map in km.", "file": "w09-p3"}}, {"title": "Glass floats that hold up moorings in the East Australian Current", "context": "Off Brisbane, the East Australian Current carries warm water south along the coast. Until 2023, Australia’s Integrated Marine Observing System kept six moorings across it, from the continental slope out to water almost 5 km deep. A mooring is a cable anchored to the seafloor and lined with instruments such as thermometers and current meters. What keeps a 4 km cable standing upright in a strong current? Clusters of hollow glass floats near the top, each a sphere 17 inches across. How much does one float lift, and how hard would it be to spin one about the rope? Both answers are sphere integrals that symmetry finishes quickly. (This problem reviews Weeks 7 and 8 for Quiz 3.)", "model": "The float’s size, weight, and rated buoyancy are published, as are the float clusters; the thin glass shell and the still water are assumptions.", "sources": ["imoseac", "vitrovex"], "work": ["Before (a): Explain, without parametrizing, why $\\iint_Sx^2\\,dS=\\iint_Sy^2\\,dS=\\iint_Sz^2\\,dS$ on a sphere centered at the origin; use $x^2+y^2+z^2=R^2$ to evaluate them.", "Before (b): Find the outward unit normal $\\mathbf n$ on $S$, and explain why it must point outward here.", "Explain why $\\iint_S z\\,dS=0$ but $\\iint_S z\\,n_z\\,dS>0$.", "Find a float’s moment of inertia $I$ about the rope, treating the glass as a thin shell, and compare it with $\\tfrac25mR^2$ for a solid ball of the same mass.", "After (c): Compare your lift per float with the datasheet’s net buoyancy of $26$ kg."], "questions": [{"prompt": "For a sphere of radius $r$ centered at the origin, enter $\\iint_S x^2\\,dS$ as a function of $r$.", "expected": "4*pi*r^4/3", "units": "", "kind": "expression", "tolerance": 1e-05, "hints": ["By symmetry the integrals of x², y², and z² over the sphere are equal, and together they add up to the integral of x² + y² + z² = r².", "The sphere’s area is 4πr², so the three integrals add up to r² · 4πr²."], "id": "w09-p4-a", "label": "a"}, {"prompt": "Find the outward flux $\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$ through one float’s outer surface, with $R=2.16$ dm. Measure lengths in decimeters, so the answer is in liters.", "expected": "4*pi*2.16^3/3", "units": "L", "kind": "number", "tolerance": 1e-05, "hints": ["On the sphere, n = (x, y, z)/R, so the integrand is z²/R.", "Use part (a) with R = 432/2 mm = 2.16 dm."], "id": "w09-p4-b", "label": "b"}, {"prompt": "The water’s up-thrust on each float is $\\rho g$ times the flux from part (b). Find the net lift of the 16-float cluster on mooring M4 (total up-thrust minus total weight), in kilograms, that is, divided by $g$.", "expected": "16*(1.025*4*pi*2.16^3/3-17)", "units": "kg", "kind": "number", "tolerance": 1e-05, "hints": ["Seawater has density 1.025 kg per liter, so one float displaces 1.025 times the liters from part (b), in kilograms.", "Subtract each float’s 17 kg, then multiply by 16."], "id": "w09-p4-c", "label": "c"}], "solution": ["Symmetry (a): Rotating the axes ($x$ to $y$ to $z$) maps the sphere and its area element to themselves, so the three integrals are equal. Their sum is $\\iint_S R^2\\,dS=R^2(4\\pi R^2)$, so each is $\\tfrac43\\pi R^4$.", "Flux (b): The outward normal is $\\mathbf n=(x,y,z)/R$, so $(0,0,z)\\cdot\\mathbf n=z^2/R$, and the flux is $\\tfrac1R\\cdot\\tfrac43\\pi R^4=\\tfrac43\\pi R^3$, the sphere’s volume. With $R=2.16$ dm it is about $42.21$ L. An inward normal would flip the sign; the water pushes inward on the outer surface, and the up-thrust formula is written with the outward normal.", "Sign check: $\\iint_S z\\,dS=0$ because the top and bottom hemispheres cancel. In $z\\,n_z=z^2/R$ both factors change sign together, so every part of the sphere contributes a positive amount.", "Spin: $I=\\frac{m}{4\\pi R^2}\\iint_S(x^2+y^2)\\,dS=\\frac{m}{4\\pi R^2}\\cdot\\frac83\\pi R^4=\\tfrac23mR^2\\approx\\tfrac23(17)(0.216)^2\\approx0.53$ kg·m$^2$. This is larger than $\\tfrac25mR^2\\approx0.32$ kg·m$^2$ for a solid ball, because a shell keeps all its mass at the full radius. The real glass is $14$ mm thick, so its true $I$ is slightly below the thin-shell value.", "Net lift (c): One float displaces $1.025(42.21)\\approx43.27$ kg of seawater and weighs $17$ kg, so it lifts about $26.27$ kg, matching the datasheet’s $26$ kg. The cluster of 16 lifts about $16(26.27)\\approx420.3$ kg, an upward pull of about $4.12$ kN on the top of the mooring."], "reflection": "The lift of one float is ρ times its volume minus its mass. Would the same flux argument give the up-thrust on a cylindrical or cube-shaped float, and why does the sphere’s symmetry make the computation so quick?", "extension": false, "id": "w09-p4", "discussionSolution": "Yes. For any closed surface the up-thrust is $\\rho g\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$, which equals ρg times the enclosed volume (a fact the divergence theorem will explain), so a float of any shape lifts ρV minus its mass. For a sphere, symmetry gives that flux without the general theorem, because x², y², and z² have equal integrals over the sphere.", "modelSpec": {"data": ["EAC array: six moorings across the current off Brisbane; 2015 water depths $500$ to $4800$ m", "Mooring M4 (design depth $4259$ m): a cluster of $16$ glass floats, 17-inch, near the top", "17-inch glass float (VITROVEX FS-6700-17): outer diameter $432$ mm, weight in air $17$ kg, net buoyancy $26$ kg in seawater of $1.025$ g/cm$^3$"], "assume": ["Each float’s outer surface is a sphere of radius $R=21.6$ cm $=2.16$ dm", "For spinning, the float’s $17$ kg of glass is a thin uniform shell", "Seawater density is $1.025$ kg/L", "The floats are fully submerged and still; protective casings, clamps, and rope are ignored"], "model": ["$S$: $x^2+y^2+z^2=R^2$, $R=2.16$ dm, with $z$ measured upward along the rope from the float’s center", "Water’s up-thrust: $\\rho g\\iint_S(0,0,z)\\cdot\\mathbf n\\,dS$ with $\\mathbf n$ outward, $\\rho=1.025$ kg/L", "Spin about the rope ($z$-axis): $I=\\dfrac{m}{4\\pi R^2}\\iint_S(x^2+y^2)\\,dS$, with $m=17$ kg"]}, "photo": {"alt": "Satellite map of sea-surface temperature off eastern Australia on 17 August 2005 (Aqua MODIS): a tongue of warm water (pale orange, about 23 to 25 °C) runs south along the coast past Brisbane and peels off in swirls near 34° S, with cooler purple water farther south toward Tasmania", "credit": "NASA Earth Observatory (Aqua MODIS)", "license": "Public domain", "licenseUrl": "", "page": "https://commons.wikimedia.org/wiki/File:East_Australian_Current.jpg", "file": "w09-p4.jpg"}, "figure": {"alt": "Cross-section of one glass float threaded on a vertical mooring rope, with the z-axis pointing up along the rope, the radius R marked, and outward normal arrows all around the sphere, in seawater.", "caption": "One float as a sphere $S$ of radius $R=21.6$ cm on the mooring rope (the $z$-axis), fully submerged, with outward normals $\\mathbf n$.", "file": "w09-p4"}}, {"title": "Agulhas rings: the loop with the most spin", "context": "Off the southern tip of Africa, the Agulhas Current loops back on itself and pinches off rings of warm water, about six a year. Each ring is 200 to 280 km across and reaches about 1,100 m deep. The rings drift into the Atlantic, carrying Indian Ocean heat and salt. Inside a ring the water swirls around the center, and toward the ring’s edge the swirl dies away. The circulation around a closed loop adds up how much the water flows along it. Which loop inside a ring captures the most circulation, and what is the circulation around the ring’s edge?", "model": "Ring sizes and the sense of rotation are published; the swirl profile and its peak speed of about 1 m/s are assumptions.", "sources": ["agulhas"], "work": ["Before (b): Explain why maximizing $\\oint_C\\mathbf u\\cdot d\\mathbf r$ over positively oriented simple closed loops is the same as maximizing $\\iint_D(Q_x-P_y)\\,dA$ over regions $D$.", "Before (b): Prove the disk $r\\le a$ wins: compare any $D$ with $D\\cap\\{r\\le a\\}$.", "After (b): Check part (b) directly on the circle $r=a$.", "Compute the outward flux $\\oint\\mathbf u\\cdot\\mathbf n\\,ds$ across $r=a$ with $\\mathbf n\\,ds=(dy,-dx)$, and compare it with $\\iint\\operatorname{div}\\mathbf u\\,dA$."], "questions": [{"prompt": "Writing $\\mathbf u=(P,Q)$, enter $Q_x-P_y$ as a function of $r$.", "expected": "2*6.6/90*(1-r^2/8100)", "units": "1/h", "kind": "expression", "tolerance": 1e-05, "hints": ["Write u = g(r)(−y, x) with g(r) = (6.6/90)(1 − r²/16200), and use the product rule.", "For a field g(r)(−y, x), Q_x − P_y = 2g + r g′(r)."], "id": "w09-p5-a", "label": "a"}, {"prompt": "Using part (a), find the largest possible circulation of $\\mathbf u$ around a positively oriented simple closed loop inside the ring.", "expected": "594*pi", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["By Green’s theorem the circulation is the integral of Q_x − P_y over the enclosed region, and Q_x − P_y is positive exactly for r < 90 km.", "Integrate Q_x − P_y over that disk, or use circulation = 2πr × (speed at r = 90 km)."], "id": "w09-p5-b", "label": "b"}, {"prompt": "Find the circulation of $\\mathbf u$ counterclockwise around the ring’s edge, the circle $r=90\\sqrt2$ km.", "expected": "0", "units": "km²/h", "kind": "number", "tolerance": 1e-05, "hints": ["At the edge the swirl speed is zero.", "Equivalently, the negative Q_x − P_y in the outer band cancels the positive core."], "id": "w09-p5-c", "label": "c"}], "solution": ["Curl (a): With $g(r)=\\frac{V_0}{a}\\big(1-\\frac{r^2}{2a^2}\\big)$ and $\\mathbf u=g(-y,x)$, $Q_x-P_y=2g+rg^{\\prime}=\\frac{2V_0}{a}\\big(1-\\frac{r^2}{a^2}\\big)=\\frac{2(6.6)}{90}\\big(1-\\frac{r^2}{8100}\\big)$ per hour. It is positive in the core and negative outside $r=a=90$ km.", "Best loop (b): By Green’s theorem, the circulation around $C$ equals $\\iint_D(Q_x-P_y)\\,dA$ over the region $D$ it encloses, so the best loop bounds the best region. For any $D$, $\\iint_D(Q_x-P_y)\\le\\iint_{D\\cap\\{r\\le a\\}}(Q_x-P_y)\\le\\iint_{r\\le a}(Q_x-P_y)$, because the dropped outer part is negative and the added inner part is positive. The maximum is $2\\pi\\int_0^{90}\\frac{13.2}{90}\\big(1-\\frac{r^2}{8100}\\big)r\\,dr=\\pi(6.6)(90)=594\\pi\\approx1866$ km$^2$/h. Check: at $r=90$ the speed is $3.3$ km/h, and $2\\pi(90)(3.3)=594\\pi$.", "Flux form: On $r=a$, $\\mathbf u$ is tangent to the circle, so $\\mathbf u\\cdot\\mathbf n=0$ and the outward flux is $0$. Also $\\operatorname{div}\\mathbf u=0$, so both sides of the flux form of Green’s theorem agree.", "Ring edge (c): At $r=90\\sqrt2$, $1-r^2/(2a^2)=0$, so the swirl speed is $0$ and so is the circulation. The negative $Q_x-P_y$ of the outer band exactly cancels the positive core, so seen from outside, the ring carries no net spin."], "reflection": "A ring full of spinning water has zero circulation around its edge. How is that possible, and why might a ring like this hold together while it drifts across an ocean?", "extension": true, "id": "w09-p5", "discussionSolution": "Circulation measures the net spin (vorticity) inside the loop: the core spins one way, a surrounding band spins the other way, and the two cancel at the edge. Because the swirl stops at the edge, the ring barely disturbs the water around it, so it is a self-contained (“shielded”) vortex that can drift far without spreading its spin to the surrounding ocean.", "modelSpec": {"data": ["About six rings a year", "Ring diameter $200$ to $280$ km, reaching about $1100$ m deep", "Rings are anticyclonic (counterclockwise in the Southern Hemisphere)"], "assume": ["The surface swirl speed at distance $r$ km from the center is $v(r)=V_0\\dfrac ra\\Big(1-\\dfrac{r^2}{2a^2}\\Big)$, with $a=90$ km and $V_0=6.6$ km/h (peak about $1$ m/s)", "The ring ends where the swirl stops, at $r=a\\sqrt2\\approx127$ km"], "model": ["$\\mathbf u(x,y)=\\dfrac{6.6}{90}\\Big(1-\\dfrac{x^2+y^2}{16200}\\Big)(-y,\\ x)$ km/h, for $x^2+y^2\\le16200$, with $x,y$ in km from the ring’s center"]}, "figure": {"alt": "Graph of the model swirl speed of an Agulhas ring against distance r from the center: the speed rises from zero to a peak a little above 3.5 km/h and falls back to zero at the ring edge, near 127 km.", "caption": "Model swirl speed $v(r)$ across the ring. It peaks at about $1$ m/s and falls to zero at the ring edge, $r=90\\sqrt2\\approx127$ km.", "file": "w09-p5"}}]}, {"week": 10, "title": "Curl at work", "subtitle": "Curl Power", "skills": ["Compute curl and read it as local rotation: $2\\boldsymbol\\Omega$ for rigid rotation, circulation per unit area, paddle-wheel spin", "Apply Stokes’ theorem in both directions with compatible orientations, choosing the easiest surface", "Find potentials by successive integration and use them to evaluate line integrals along any path", "Decide when zero curl guarantees a potential: removing a line versus removing a point", "Test which fields are curls with $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$, then build and use a vector potential", "Apply the Divergence Theorem to a ball and to a column of crust (extension)"], "formulas": ["$\\nabla\\times\\mathbf F=\\big(\\partial_yF_3-\\partial_zF_2,\\ \\partial_zF_1-\\partial_xF_3,\\ \\partial_xF_2-\\partial_yF_1\\big)$", "Stokes: $\\iint_S(\\nabla\\times\\mathbf F)\\cdot d\\mathbf S=\\oint_{\\partial S}\\mathbf F\\cdot d\\mathbf r$, with $\\partial S$ traversed by the right-hand rule (thumb along the normal of $S$)", "On a simply connected domain, $\\nabla\\times\\mathbf F=\\mathbf 0\\iff\\mathbf F=\\nabla f$; then $\\int_C\\nabla f\\cdot d\\mathbf r=f(Q)-f(P)$ for $C$ from $P$ to $Q$", "$\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$ for $C^2$ fields; on all of $\\mathbb R^3$, a $C^1$ field $\\mathbf G$ is a curl $\\iff\\nabla\\cdot\\mathbf G=0$", "Divergence Theorem: $\\iint_{\\partial W}\\mathbf F\\cdot\\mathbf n\\,dS=\\iiint_W\\nabla\\cdot\\mathbf F\\,dV$, with $\\mathbf n$ the outward normal"], "sources": ["iersconst", "earth", "montereylat", "qispec", "lhcdesign", "lhcquad", "esacluster", "uafelectrojet", "earthheat"], "problems": [{"title": "Earth’s spin as a curl", "context": "Earth turns once each sidereal day (one turn relative to the stars), carrying the air, the oceans, and Monterey Bay with it. Seen from space, everything on the planet shares one rigid rotation, and that rotation has a curl. The part of the curl along the local vertical slowly turns the swing of a Foucault pendulum, a long pendulum free to swing in any direction. It also gives large ocean eddies and storms their preferred direction of spin. How large is that vertical part at Monterey, how long does a pendulum there take to turn once around, and which way should a paddle wheel’s axle point to spin fastest?", "model": "Earth’s rotation rate, its mean radius, and Monterey’s latitude are published; a spherical Earth in perfect rigid rotation, with no winds or currents relative to the ground, is assumed.", "sources": ["iersconst", "earth", "montereylat"], "work": ["Check that $\\boldsymbol\\Omega=(0,0,\\Omega)$ gives $\\mathbf v=\\boldsymbol\\Omega\\times\\mathbf r=\\Omega(-y,x,0)$.", "Orient $C$ eastward: show that this is counterclockwise seen from above the North Pole, and that the compatible normal on the cap $S$ points away from Earth’s center.", "With (b): compute the flux of $\\nabla\\times\\mathbf v$ through $S$ directly, using $\\mathbf n=\\mathbf r/R$, $dS=R^2\\sin\\phi\\,d\\phi\\,d\\theta$, the right range of $\\phi$, and the cap’s symmetry about the axis. Then compute it through the flat disk spanning $C$. Both must match the circulation.", "Find the limit of (circulation)/(area) for a tiny horizontal circle of radius $\\epsilon$ centered at Monterey, as $\\epsilon\\to0$.", "Predict how long a Foucault pendulum at Monterey takes to turn its swing once around (it turns at $\\Omega\\sin L$)."], "questions": [{"prompt": "For $\\mathbf v=w(-y,x,0)$, rotation at rate $w$ about the $z$-axis (the model’s velocity with $\\Omega$ written as $w$), enter $\\nabla\\times\\mathbf v$.", "expected": ["0", "0", "2*w"], "units": "rad/s", "kind": "vector", "tolerance": 1e-05, "hints": ["v has no z-component and does not depend on z, so the first two components of the curl vanish.", "Third component: d(wx)/dx − d(−wy)/dy."], "id": "w10-p1-a", "label": "a"}, {"prompt": "Find the circulation $\\oint_C\\mathbf v\\cdot d\\mathbf r$ of Earth’s rotational velocity around Monterey’s parallel $C$ (latitude $36.605^\\circ$ N), traversed eastward. Take $R$ in km and give km²/s.", "expected": "2*pi*7.292115e-5*6371^2*cos(36.605*pi/180)^2", "units": "km²/s", "kind": "number", "tolerance": 1e-05, "hints": ["Along C the velocity is tangent to C, with constant speed Omega R cos L.", "Multiply that speed by the length 2πR cos L of C, or use Stokes on the flat disk: (2 Omega) times π(R cos L)²."], "id": "w10-p1-b", "label": "b"}, {"prompt": "A tiny paddle wheel is carried along by the rigidly rotating air at Monterey. It spins about its axle at half the component of $\\nabla\\times\\mathbf v$ along the axle. Which axle direction makes it spin fastest?", "expected": "1", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["The curl is the same vector 2 Omega k at every point of Earth.", "The component of a fixed vector along a unit axle is largest when the axle points along that vector."], "options": ["Straight up (the local vertical at Monterey)", "Parallel to Earth’s axis: pointing north, tilted up 36.6° from the horizontal", "Horizontal, pointing east", "All directions spin equally, because the rotation is rigid"], "id": "w10-p1-c", "label": "c"}], "solution": ["Curl: $\\nabla\\times\\mathbf v=\\big(0-0,\\ 0-0,\\ \\partial_x(\\Omega x)-\\partial_y(-\\Omega y)\\big)=(0,0,2\\Omega)=2\\boldsymbol\\Omega$ at every point, which is twice the angular velocity.", "Orientation: parametrize $C$ as $(R\\cos L\\cos t,\\,R\\cos L\\sin t,\\,R\\sin L)$ with $t$ increasing eastward, which is counterclockwise seen from above the North Pole. With your thumb pointing away from Earth’s center on the cap (upward on the flat disk), your fingers curl the same way, so these orientations are compatible.", "Flux three ways: on the cap, $(\\nabla\\times\\mathbf v)\\cdot\\mathbf n=2\\Omega z/R$ with $z=R\\cos\\phi$, and the cap is $0\\le\\phi\\le\\pi/2-L$, so \\[\\iint_S\\frac{2\\Omega z}{R}dS=\\frac{2\\Omega}{R}\\int_0^{2\\pi}\\!\\!\\int_0^{\\pi/2-L}R^3\\cos\\phi\\sin\\phi\\,d\\phi\\,d\\theta=2\\pi\\Omega R^2\\cos^2L.\\] Through the flat disk the flux is $2\\Omega\\cdot\\pi(R\\cos L)^2$. The circulation is the speed $\\Omega R\\cos L$ times the length $2\\pi R\\cos L$. All three give $2\\pi(7.292115\\times10^{-5})(6371)^2\\cos^2(36.605^\\circ)\\approx11{,}984.67$ km$^2$/s.", "Circulation per unit area: for a tiny horizontal circle at Monterey, (circulation)/(area) $\\to(\\nabla\\times\\mathbf v)\\cdot\\mathbf n_{\\rm up}=2\\Omega\\sin L\\approx8.70\\times10^{-5}$ s$^{-1}$, because the upward normal $\\mathbf n_{\\rm up}=\\mathbf r/R$ makes angle $90^\\circ-L$ with the axis.", "Foucault pendulum: its swing turns at half that rate, $\\Omega\\sin L$, so one full turn takes $2\\pi/(\\Omega\\sin L)\\approx1.445\\times10^5$ s, about $40.1$ hours.", "Paddle wheel: with unit axle $\\mathbf u$ it spins at $\\tfrac12(\\nabla\\times\\mathbf v)\\cdot\\mathbf u=\\Omega\\,\\mathbf k\\cdot\\mathbf u$. That is fastest ($\\Omega$) for an axle parallel to Earth’s axis, $\\Omega\\sin L$ for a vertical axle, and zero for any axle perpendicular to Earth’s axis, such as one pointing east."], "reflection": "What would a Foucault pendulum do at the equator, and at the South Pole? Use the vertical component of $\\nabla\\times\\mathbf v$.", "extension": false, "id": "w10-p1", "discussionSolution": "At the equator the swing does not turn at all; at the South Pole it turns once per sidereal day, in the opposite sense from Monterey. At the equator the local vertical is perpendicular to Earth’s axis, so the vertical component of the curl, $2\\Omega\\sin0$, is zero. In the Southern Hemisphere $\\sin L<0$, so the swing turns counterclockwise seen from above; at the South Pole one turn takes $2\\pi/\\Omega\\approx23.93$ hours.", "modelSpec": {"data": ["Earth’s angular velocity: $\\Omega=7.292115\\times10^{-5}$ rad/s", "Earth’s mean radius: $R=6371$ km", "Monterey Harbor latitude: $L=36.605^\\circ$ N"], "assume": ["Everything on Earth turns rigidly with it: winds and currents relative to the ground are ignored.", "Earth is a perfect sphere centered at the origin, with the $z$-axis through the North Pole."], "model": ["Velocity seen from space: $\\mathbf v=\\boldsymbol\\Omega\\times\\mathbf r$ (km/s), with $\\boldsymbol\\Omega=(0,0,\\Omega)$ and position $\\mathbf r=(x,y,z)$ in km", "Monterey’s parallel $C$: the circle $x^2+y^2=(R\\cos L)^2$, $z=R\\sin L$", "Polar cap $S$: the part of the sphere $x^2+y^2+z^2=R^2$ with $z\\ge R\\sin L$"]}, "photo": {"alt": "Star trails circling the north celestial pole above the Gemini North telescope dome on Maunakea, Hawaii: a long exposure that records Earth’s rotation", "credit": "International Gemini Observatory/NOIRLab/NSF/AURA/T. Matsopoulos", "license": "CC BY 4.0", "licenseUrl": "https://creativecommons.org/licenses/by/4.0/", "page": "https://commons.wikimedia.org/wiki/File:Star_Trails_Above_Gemini_North_(iotw2506a).jpg", "file": "w10-p1.jpg"}, "figure": {"alt": "Cross-section of Earth through its rotation axis. The vertical axis has a rotation arrow at the top; the angle L is marked at the center; Monterey is a dot on the circle, with a dashed line across the circle for its parallel and a thick arc above it for the polar cap. Two arrows leave Monterey: the local vertical and the direction parallel to the axis", "caption": "The model: Earth rotating rigidly about the $z$-axis, Monterey’s parallel $C$ at latitude $L$, and the polar cap $S$ (teal) that $C$ bounds. At Monterey, compare the local vertical with the direction of $\\nabla\\times\\mathbf v=2\\boldsymbol\\Omega$.", "file": "w10-p1"}}, {"title": "Charging a phone through thin air", "context": "Lay a phone on a Qi wireless charging pad and it charges with no plug. A coil in the pad drives a rapidly oscillating magnetic field. By Faraday’s law, the changing magnetic field creates a circulating electric field, which pushes current around a coil in the phone. The total push around a loop is the electromotive force (EMF): the circulation of the electric field around the loop, measured in volts. Stokes’ theorem turns that circulation into a flux. How large is the EMF on a small loop, does tilting the loop change it, and what happens to a phone standing on its edge?", "model": "The coil size and operating frequency are published for one Qi reference design; the uniform vertical field, its 1 mT amplitude, and the single-turn loops are assumed.", "sources": ["qispec"], "work": ["Check that the model field satisfies Faraday’s law $\\nabla\\times\\mathbf E=-\\partial\\mathbf B/\\partial t$.", "Before (b): parametrize the flat loop $x^2+y^2=0.02^2$, $z=0$, counterclockwise seen from above.", "After (b): confirm it with Stokes’ theorem on the flat disk, naming the normal the right-hand rule pairs with this direction.", "Explain why the flat loop, whose plane is perpendicular to $\\nabla\\times\\mathbf E$, has nonzero circulation, while a loop standing in the plane $x=0$ (a phone on its edge) has none.", "Before (c): describe the shape of $C$, choose the planar surface it bounds, and write that surface’s upward vector area element.", "After (c): explain why the EMF does not depend on the tilt, even though $C$ is longer than the flat circle, and why parametrizing $C$ directly gives the same integral as the flat loop."], "questions": [{"prompt": "For the model field $\\mathbf E=\\tfrac b2(y,-x,0)$, enter $\\nabla\\times\\mathbf E$.", "expected": ["0", "0", "-b"], "units": "V/m²", "kind": "vector", "tolerance": 1e-05, "hints": ["E has no z-component and does not depend on z, so only the third component of the curl can be nonzero.", "Compute d(−bx/2)/dx − d(by/2)/dy; Faraday’s law tells you what to expect."], "id": "w10-p2-a", "label": "a"}, {"prompt": "Find the EMF $\\oint\\mathbf E\\cdot d\\mathbf r$ around the flat loop of radius $0.02$ m in the plane $z=0$, counterclockwise seen from above, as an expression in $b$.", "expected": "-0.0004*pi*b", "units": "V", "kind": "expression", "tolerance": 1e-05, "hints": ["Parametrize the loop as r(t) = (0.02 cos t, 0.02 sin t, 0); the dot product E · r′ comes out constant.", "E · r′ = −(b/2)(0.02)²; integrate over 0 ≤ t ≤ 2π. The minus sign is Lenz’s law."], "id": "w10-p2-b", "label": "b"}, {"prompt": "For the tilted loop $C$, find the largest size of the EMF $\\oint_C\\mathbf E\\cdot d\\mathbf r$ during one cycle of $B(t)$, in volts.", "expected": "2*pi*140000*0.001*pi*0.02^2", "units": "V", "kind": "number", "tolerance": 1e-05, "hints": ["Use Stokes on the planar patch z = 0.004 + 0.36y over the disk x² + y² ≤ 0.02²: its upward vector area element is (0, −0.36, 1) dA.", "Dotting the curl with that element gives |EMF| = |b| times the disk’s area; |b| = |B′(t)| peaks at the amplitude 0.001 T times 2π × 140000 per second."], "id": "w10-p2-c", "label": "c"}], "solution": ["Faraday’s law check: $\\nabla\\times\\mathbf E=\\big(0,\\,0,\\,\\partial_x(-bx/2)-\\partial_y(by/2)\\big)=(0,0,-b)=-\\partial\\mathbf B/\\partial t$, so the model field obeys Faraday’s law.", "Flat loop: on $\\mathbf r(t)=(0.02\\cos t,0.02\\sin t,0)$, $\\mathbf E\\cdot\\mathbf r^\\prime=\\tfrac b2\\big(0.02\\sin t(-0.02\\sin t)-0.02\\cos t(0.02\\cos t)\\big)=-\\tfrac b2(0.0004)$, so $\\oint\\mathbf E\\cdot d\\mathbf r=-0.0004\\pi b$ V.", "Stokes check: counterclockwise from above pairs with the upward normal $\\mathbf k$, and $(\\nabla\\times\\mathbf E)\\cdot\\mathbf k=-b$ times the area $0.0004\\pi$ m$^2$ gives the same $-0.0004\\pi b$ V.", "Upright loop: the flat loop’s normal $\\mathbf k$ is parallel to $\\nabla\\times\\mathbf E$, the best case. A loop in the plane $x=0$ has normal $(1,0,0)$, perpendicular to $\\nabla\\times\\mathbf E$, so the flux of the curl through its disk, and hence its EMF, is $0$: in this model an upright phone does not charge.", "Tilted loop: $C$ is an ellipse in the tilted plane, and its shadow on the $xy$-plane is the circle of radius $0.02$ m. Take the planar patch $z=0.004+0.36y$ over that disk, with upward vector area element $(0,-0.36,1)\\,dA$. Then $(\\nabla\\times\\mathbf E)\\cdot(0,-0.36,1)=-b$, so the EMF is $-b\\pi(0.02)^2$, the same as for the flat loop: only the vertical part of the vector area meets the vertical curl. Parametrizing $C$ directly agrees, because $\\mathbf E$ has no $z$-component, so $z(t)$ never enters $\\mathbf E\\cdot d\\mathbf r$.", "Peak EMF: with $B(t)=0.001\\sin(2\\pi\\cdot140000\\,t)$ T, the rate $b=B^\\prime(t)$ peaks in size at $0.001(2\\pi)(140000)\\approx879.6$ T/s. So the peak EMF is $879.6\\times\\pi(0.02)^2\\approx1.105$ V for each turn of the receiver coil."], "reflection": "How does the EMF scale with the number of turns in a real receiver coil? And why would a circular coil tilted by $30^\\circ$ get less EMF than the tilted loop $C$?", "extension": false, "id": "w10-p2", "discussionSolution": "The EMF is multiplied by the number of turns, and the tilted circular coil gets less by the factor cos 30° ≈ 0.87. Each turn is a loop with the same flux change, so the turns add. A circle of radius r tilted by 30° has vector area πr² n, whose vertical component is only πr² cos 30°, so the flux of the vertical field drops by that factor. The model loop C instead kept a full disk as its shadow, which is why its EMF did not change.", "modelSpec": {"data": ["Qi reference transmitter design A2: coil outer diameter $40$ mm, inner diameter $19$ mm, $2\times10$ turns", "Fixed operating frequency: $140$ kHz"], "assume": ["Over the pad’s coil the magnetic field is vertical and uniform: $\\mathbf B=(0,0,B(t))$ with $B(t)=0.001\\sin(2\\pi\\cdot140000\\,t)$ T.", "Each receiver loop is a single turn of wire.", "Edge effects at the rim of the pad’s coil are ignored."], "model": ["Faraday’s law: $\\nabla\\times\\mathbf E=-\\partial\\mathbf B/\\partial t$. With $b=B^\\prime(t)$ (T/s), the induced field is $\\mathbf E=\\tfrac b2(y,-x,0)$ V/m, with $x,y$ in meters", "EMF of a loop: $\\oint\\mathbf E\\cdot d\\mathbf r$ (volts)", "Flat loop: the circle $x^2+y^2=0.02^2$ in the plane $z=0$", "Tilted loop $C$: where the plane $z=0.004+0.36y$ meets the cylinder $x^2+y^2=0.02^2$ (meters), counterclockwise seen from above"]}, "photo": {"alt": "A smartphone lying on a black wireless charging pad, its screen showing a charging symbol", "credit": "LG Electronics", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Inductive_charging_of_LG_smartphone_(2).jpg", "file": "w10-p2.jpg"}, "figure": {"alt": "Three-dimensional sketch of a flat circular loop, a tilted elliptical loop directly above it on the same vertical cylinder (dotted lines join them), and upward arrows for the magnetic field", "caption": "The model: a uniform vertical field $\\mathbf B(t)$ over the pad’s coil, the flat loop at $z=0$, and the tilted loop $C$ on the cylinder $x^2+y^2=0.02^2$. Dotted lines show that $C$ lies directly above the flat loop.", "file": "w10-p2"}}, {"title": "Which magnetic fields can steer the LHC?", "context": "The Large Hadron Collider (LHC) at CERN, on the French–Swiss border, sends two proton beams around a 27 km ring. Its 1232 superconducting dipole magnets bend the beams around the ring, and hundreds of quadrupole magnets focus them, squeezing the protons toward the middle of the beam pipe. Apart from the beam’s own small current, no current flows inside the pipe, and, as everywhere in nature, there are no magnetic monopoles. Which magnetic fields do these two facts allow? Why can no single magnet focus the beam in every direction at once? And how much magnetic flux passes through a search coil, a wire loop used to measure flux, inside a quadrupole?", "model": "The ring size, dipole field, quadrupole gradient, and beam-screen size are published; the ideal current-free magnet fields and the search coil are assumed.", "sources": ["lhcdesign", "lhcquad"], "work": ["Prove $\\nabla\\cdot(\\nabla\\times\\mathbf F)=0$ for every $C^2$ field $\\mathbf F$. Explain why a field with nonzero divergence is never a curl, so never a magnetic field.", "For (a): compute the divergence and curl of each option.", "After (a): Compute $\\mathbf k\\times\\mathbf B$ for the quadrupole field and show that it pushes protons toward the axis in one transverse direction and away in the other.", "For (b): write the three component equations of $\\nabla\\times\\mathbf A=\\mathbf B$ with $A_1=0$, integrate in $x$, and choose the leftover functions of $(y,z)$.", "Find $\\psi$ with $\\nabla\\psi=\\mathbf B$: the quadrupole field is also a gradient.", "Explain, by cutting a closed surface into two patches and using Stokes’ theorem, why the flux of any curl (so of $\\mathbf B$) through it is $0$."], "questions": [{"prompt": "Ignoring the beam’s own small current, a magnetic field inside the beam screen must have zero divergence and zero curl. With $G=223$ T/m, which of these fields is possible there?", "expected": "2", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Divergence must be 0: that already rules out two options.", "Of the remaining two, one has curl (0, 0, 2G), which would need a current inside the beam screen."], "options": ["$G(x,y,0)$", "$G(-y,x,0)$", "$G(y,x,0)$", "$G(x,y,-z)$"], "id": "w10-p3-a", "label": "a"}, {"prompt": "Find a vector potential $\\mathbf A=(0,A_2,A_3)$ for the quadrupole field, so that $\\nabla\\times\\mathbf A=223\\,(y,x,0)$. Enter its three components.", "expected": ["0", "0", "223*(y^2-x^2)/2"], "units": "T·m", "kind": "vector", "tolerance": 1e-05, "hints": ["Write the three component equations of curl A = B with A_1 = 0, and integrate in x.", "The second equation, −dA_3/dx = 223x, gives A_3 = −223x²/2 + g(y, z); the third, dA_2/dx = 0, lets you take A_2 = 0. Then the first needs dg/dy = 223y."], "semantic": "curl", "curlTarget": ["223*y", "223*x", "0"], "firstComponentZero": true, "id": "w10-p3-b", "label": "b"}, {"prompt": "A rectangular search coil lies in the plane $y=0$, with $0\\le x\\le0.017$ m and $0\\le z\\le1$ m (1 m along the beam). Find the magnetic flux of the quadrupole field through it in the $+y$ direction, in webers.", "expected": "223*0.017^2/2", "units": "Wb", "kind": "number", "tolerance": 1e-05, "hints": ["The flux in the +y direction is the integral of B · j = B_y over the rectangle.", "On y = 0, B_y = 223x; integrate over 0 ≤ x ≤ 0.017 and 0 ≤ z ≤ 1, or use the circulation of A around the coil."], "id": "w10-p3-c", "label": "c"}], "solution": ["Divergence of a curl: $\\nabla\\cdot(\\nabla\\times\\mathbf F)=\\partial_x(\\partial_yF_3-\\partial_zF_2)+\\partial_y(\\partial_zF_1-\\partial_xF_3)+\\partial_z(\\partial_xF_2-\\partial_yF_1)=0$, because mixed partials of $C^2$ functions are equal. So a field with $\\nabla\\cdot\\mathbf G\\ne0$ cannot be a curl $\\nabla\\times\\mathbf A$.", "Sorting the options: $G(x,y,0)$ has divergence $2G$ and $G(x,y,-z)$ has divergence $G$, so neither can be a magnetic field. $G(-y,x,0)$ has divergence $0$ but curl $(0,0,2G)\\ne\\mathbf0$, which would require a current. $G(y,x,0)$ has divergence $0$ and curl $(0-0,0-0,G-G)=\\mathbf0$, so it is possible.", "Focusing: $\\mathbf k\\times G(y,x,0)=G(-x,y,0)$. A proton displaced in $x$ is pushed back toward the axis (focusing), but one displaced in $y$ is pushed farther out (defocusing). A linear field that focused in both directions would have $\\mathbf B\\propto(-y,x,0)$, which has nonzero curl. That is why accelerators alternate quadrupoles of opposite orientation.", "Vector potential: with $A_1=0$ the equations are $\\partial_yA_3-\\partial_zA_2=Gy$, $-\\partial_xA_3=Gx$, and $\\partial_xA_2=0$. So $A_3=-Gx^2/2+g(y,z)$ and $A_2=h(y,z)$, and the first equation becomes $g_y-h_z=Gy$; take $g=Gy^2/2$ and $h=0$. Then $\\mathbf A=\\big(0,0,\\tfrac{223}{2}(y^2-x^2)\\big)$ T·m, and indeed $\\nabla\\times\\mathbf A=(223y,\\ 223x,\\ 0)$. (For the dipole, $(0,0,-8.33x)$ works.)", "Scalar potential: $\\mathbf B=\\nabla(Gxy)$, so $\\psi=223xy$. In this current-free region the quadrupole field has zero curl and zero divergence, so it is both a gradient and a curl.", "Search coil: the flux is $\\int_0^1\\!\\int_0^{0.017}223x\\,dx\\,dz=223(0.017)^2/2\\approx0.0322$ Wb. Stokes check: with normal $+\\mathbf j$, the boundary runs up $z$ along $x=0$ (where $A_3=0$) and down $z$ along $x=0.017$ (where $A_3=-223(0.017)^2/2$), giving $+223(0.017)^2/2$; on the edges parallel to the $x$-axis, $\\mathbf A\\cdot d\\mathbf r=0$.", "Closed surfaces: cut a closed surface along a closed curve into two patches. By Stokes, each patch’s flux of $\\nabla\\times\\mathbf A$ is the circulation of $\\mathbf A$ around the cut, traversed in opposite directions for the two patches, so the total is $0$. Hence $\\mathbf B$ has zero flux through every closed surface: there are no magnetic monopoles."], "reflection": "The LHC dipoles have field 8.33 T. Is the uniform field (0, 8.33, 0) a curl, a gradient, both, or neither? Give a vector potential and a scalar potential if they exist.", "extension": false, "id": "w10-p3", "discussionSolution": "Both. Its divergence and curl are zero. A vector potential is $(0,0,-8.33x)$, whose curl is $(0,8.33,0)$, and a scalar potential is $\\psi=8.33y$. In fact any constant field is both a gradient and a curl on all of $\\mathbb R^3$.", "modelSpec": {"data": ["Ring circumference $26{,}658.883$ m; $1232$ main dipoles with field $8.33$ T", "$408$ main arc quadrupoles, nominal gradient $223$ T/m", "Beam screen in the arcs: $36.9$ mm wide, $46.5$ mm high"], "assume": ["The beam’s own current is ignored, so inside the beam screen $\\nabla\\cdot\\mathbf B=0$ and $\\nabla\\times\\mathbf B=\\mathbf 0$.", "Magnet fields are ideal and do not change along the beam.", "A hypothetical rectangular search coil lies in the plane $y=0$, $0\\le x\\le0.017$ m, along $1$ m of a quadrupole."], "model": ["Beam along $+z$. Dipole field $(0,8.33,0)$ T; quadrupole field $\\mathbf B$: the one field in part (a) that is possible, with gradient $G=223$ T/m and $x,y$ in meters", "Magnetic force on a proton moving along $+z$: proportional to $\\mathbf k\\times\\mathbf B$", "Vector potential: any $\\mathbf A$ with $\\nabla\\times\\mathbf A=\\mathbf B$"]}, "photo": {"alt": "The LHC tunnel during installation, with the blue cryostats of superconducting magnets lining one side", "credit": "alpinethread", "license": "CC BY-SA 2.0", "licenseUrl": "https://creativecommons.org/licenses/by-sa/2.0/", "page": "https://commons.wikimedia.org/wiki/File:LHC_dipole_magnets.jpg", "file": "w10-p3.jpg"}, "figure": {"alt": "Cross-section of the quadrupole field: hyperbola-shaped field lines with arrows around the beam at the center, the rectangular beam screen, and the search coil as a segment along the positive x-axis", "caption": "Field lines of the quadrupole field in the beam-pipe cross-section (millimeters), with the $36.9\\times46.5$ mm beam screen and the search coil (orange) along the positive $x$-axis in the plane $y=0$.", "file": "w10-p3"}}, {"title": "What lights up the aurora?", "context": "The aurora over Alaska glows where fast electrons crash into the upper atmosphere. ESA’s Cluster satellites found that the electrons are first accelerated to several thousand electronvolts (keV) in narrow electric structures that start several thousand kilometers up, while the electrons spiral around Earth’s magnetic field lines. An electronvolt is the energy one electron gains across one volt. Lower down, near 100 km altitude, the auroral electrojet, an east–west current of up to half a million amperes, flows through the upper atmosphere, and its magnetic field reaches the ground. How much energy does an electron gain on its spiral, how strong is the electrojet’s field at the ground, and why does one curl-free field have a potential while the other does not?", "model": "The electron energies and the electrojet’s current and altitude are published typical values; the force field, the spiral path, and the straight-line current are models.", "sources": ["esacluster", "uafelectrojet"], "work": ["Show that $\\nabla\\times\\mathbf F=\\mathbf 0$ on all of $\\mathbb R^3$.", "For (a): find $f$ by successive integration, writing the unknown $g(y,z)$ and then $h(z)$ explicitly.", "After (b): explain why the energy gain depends only on the spiral’s endpoints, and check that it is “several keV.”", "Show that the electrojet field has $\\nabla\\times\\mathbf B=\\mathbf 0$ everywhere off the current line.", "Compute $\\oint\\mathbf B\\cdot d\\mathbf r$ around a circle of radius $\\rho$ about the line. Use it to find the field strength on the ground directly below the current, in nanotesla.", "After (c): explain why zero curl and nonzero circulation do not contradict each other for the electrojet field, and what is different about the domain of the field you chose."], "questions": [{"prompt": "Find a potential $f$ with $\\nabla f=\\mathbf F=(2xz,\\ 2yz,\\ x^2+y^2-2)$.", "expected": "x^2*z+y^2*z-2*z", "units": "keV", "kind": "potential", "tolerance": 1e-05, "hints": ["Integrate one component at a time, keeping an unknown function of the remaining variables each time.", "Integrate 2xz in x: f = x²z + g(y, z). Then f_y = 2yz forces g = y²z + h(z); match f_z with x² + y² − 2."], "id": "w10-p4-a", "label": "a"}, {"prompt": "Using part (a), find the energy (in keV) that the electric force $\\mathbf F$ gives the electron along the spiral $\\mathbf c(t)=(0.5\\cos t,\\ 0.5\\sin t,\\ 3-t/(2\\pi))$, $0\\le t\\le6\\pi$.", "expected": "(0.5^2*0-2*0)-(0.5^2*3-2*3)", "units": "keV", "kind": "number", "tolerance": 1e-05, "hints": ["For a gradient field, the work done is f(end) − f(start), whatever the path.", "The spiral starts at c(0) = (0.5, 0, 3) and ends at c(6π) = (0.5, 0, 0)."], "id": "w10-p4-b", "label": "b"}, {"prompt": "Which of these fields is a gradient on its whole domain?", "expected": "3", "units": "", "kind": "choice", "tolerance": 1e-05, "hints": ["Two of these have nonzero curl, so they are out at once.", "Zero curl is enough only if every loop in the domain can shrink to a point without leaving the domain."], "options": ["The electrojet field $\\mathbf B$, on $\\mathbb R^3$ minus the current line", "Earth’s rotational velocity $\\Omega(-y,x,0)$, on $\\mathbb R^3$", "The charging pad’s induced field $\\tfrac b2(y,-x,0)$, on $\\mathbb R^3$", "The point-source field $\\mathbf r/|\\mathbf r|^3$, on $\\mathbb R^3$ minus the origin"], "id": "w10-p4-c", "label": "c"}], "solution": ["Zero curl: componentwise, $\\partial_yF_3-\\partial_zF_2=2y-2y=0$, $\\partial_zF_1-\\partial_xF_3=2x-2x=0$, and $\\partial_xF_2-\\partial_yF_1=0$. So $\\mathbf F$ is conservative on the simply connected domain $\\mathbb R^3$.", "Potential: $f=\\int2xz\\,dx=x^2z+g(y,z)$. Then $f_y=g_y=2yz$ gives $g=y^2z+h(z)$, and $f_z=x^2+y^2+h^\\prime(z)=x^2+y^2-2$ gives $h=-2z+C$. So $f=x^2z+y^2z-2z+C$.", "Energy along the spiral: by the fundamental theorem for line integrals the work is $f(0.5,0,0)-f(0.5,0,3)=0-3(0.25-2)=5.25$ keV, which is “several keV,” no matter how many times the path winds. (Real spirals have radii of meters, not hundreds of kilometers; only the endpoints matter.)", "Electrojet: for $\\mathbf B=\\frac{\\mu_0I}{2\\pi}\\frac{(0,-(z-h),y)}{y^2+(z-h)^2}$, the components give $\\nabla\\times\\mathbf B=\\mathbf0$ wherever $y^2+(z-h)^2\\ne0$. On a circle of radius $\\rho$ about the line, $\\mathbf B$ is tangent with size $\\mu_0I/(2\\pi\\rho)$, so $\\oint\\mathbf B\\cdot d\\mathbf r=\\mu_0I\\ne0$ (Ampère’s law). On the ground directly below, $\\rho=h=10^5$ m, so $B=\\frac{4\\pi\\times10^{-7}(5\\times10^5)}{2\\pi(10^5)}=10^{-6}$ T $=1000$ nT.", "Line versus point: there is no contradiction. The domain is $\\mathbb R^3$ minus a line, and a loop around the line cannot shrink to a point without crossing it, so zero curl does not force a potential (any “potential” would have to increase by $\\mu_0I$ each time around). Removing only a point leaves a simply connected domain, since loops slide off the point, and indeed $\\mathbf r/|\\mathbf r|^3=\\nabla(-1/|\\mathbf r|)$. The rotation and induced fields have curl $(0,0,2\\Omega)$ and $(0,0,-b)$, so they are not gradients."], "reflection": "A magnetometer on the ground is not directly below the electrojet but 100 km to the side. Using only Ampère’s law and the geometry, how does the field strength there compare with the 1000 nT directly below?", "extension": false, "id": "w10-p4", "discussionSolution": "It is weaker by the factor $1/\\sqrt2$: about 707 nT. The ground point is $\\rho=\\sqrt2\\times100$ km from the current, and Ampère’s law gives a field of size $\\mu_0I/(2\\pi\\rho)$ tangent to the circle of that radius, so the field there is also tilted 45° from the horizontal.", "modelSpec": {"data": ["Auroral electrons are accelerated to several keV in structures starting several thousand km up", "Auroral electrojet: mostly east–west near $100$ km altitude, up to about half a million amperes"], "assume": ["For the electron, lengths are in thousands of km and energies in keV; the force field $\\mathbf F$ stands in for a real acceleration structure.", "The spiral is drawn far wider than a real electron’s spiral (radius of meters) so that it is visible.", "The electrojet is a straight line current $I=5\\times10^5$ A along the $x$-axis (east) at height $h=100$ km over flat ground."], "model": ["Electric force on the electron: $\\mathbf F=(2xz,\\ 2yz,\\ x^2+y^2-2)$ keV per $1000$ km", "Spiral: $\\mathbf c(t)=(0.5\\cos t,\\ 0.5\\sin t,\\ 3-t/(2\\pi))$, $0\\le t\\le6\\pi$", "Electrojet field (SI units, off the line $y=0$, $z=h$): $\\mathbf B=\\dfrac{\\mu_0I}{2\\pi}\\,\\dfrac{(0,\\,-(z-h),\\,y)}{y^2+(z-h)^2}$, with $\\mu_0=4\\pi\\times10^{-7}$ T·m/A"]}, "photo": {"alt": "Green and red aurora borealis filling the night sky above silhouetted trees at Wickersham Dome, Alaska", "credit": "FairbanksMike", "license": "CC BY 2.0", "licenseUrl": "https://creativecommons.org/licenses/by/2.0/", "page": "https://commons.wikimedia.org/wiki/File:Aurora_Borealis_-_Wickersham_Dome_-_Alaska_-_16_March_2013.jpg", "file": "w10-p4.jpg"}, "figure": {"alt": "Left: a spiral path winding down around a vertical field line from (0.5, 0, 3) to (0.5, 0, 0) at the ground. Right: circular magnetic field lines around a line current 100 km above the ground, seen end-on", "caption": "Left: the model spiral $\\mathbf c(t)$ around a field line (radius exaggerated). Right: the electrojet as a line current at height $h=100$ km, seen end-on, with circular field lines (not to scale).", "file": "w10-p4"}}, {"title": "What Happens Inside Stays Inside", "context": "Earth leaks heat from its interior through every square meter of its surface. The heat comes from radioactive elements in the rocks and from heat left over from the planet’s formation. Davies and Davies (2010) combined heat-flow measurements with maps of geology and models of cooling ocean floor to estimate the total at 47 terawatts (TW). The heat flux is the rate at which heat crosses a surface per unit area, in watts per square meter. The Divergence Theorem links the total heat leaving a closed surface to the heat produced inside it. What is the average heat flux at Earth’s surface, and how much of the heat flowing out of a continent comes up from the mantle below its crust?", "model": "The total and continental heat flows are published; steady state, uniform heat production in the thought experiment, and the crust’s heat-production profile are assumed.", "sources": ["earthheat", "earth"], "work": ["For (a): use $\\mathbf n=\\mathbf r/R$ to turn the total heat flow into an average outward flux.", "For (b): compute $\\nabla\\cdot\\mathbf q$, then check the Divergence Theorem on the ball by computing the surface integral directly.", "Before (c): list the crustal column’s six faces with their outward normals (the bottom’s points down), and say which faces carry heat.", "For (c): apply the Divergence Theorem to the column to find $q_m$.", "Compare $H$ from (b) with the crust’s $2.5\\ \\mu$W/m$^3$ at the surface. What does this suggest about where Earth’s heat-producing elements are?"], "questions": [{"prompt": "Find the average outward heat flux through Earth’s surface, in mW/m².", "expected": "47*10^12/(4*pi*6371000^2)*1000", "units": "mW/m²", "kind": "number", "tolerance": 1e-05, "hints": ["The outward flux through the whole sphere is 47 TW = 4.7e13 W.", "Divide by the area 4πR² with R = 6.371e6 m, then convert W/m² to mW/m²."], "id": "w10-p5-a", "label": "a"}, {"prompt": "Thought experiment: suppose the 47 TW were produced uniformly throughout Earth’s volume, with steady flux $\\mathbf q=\\tfrac H3(x,y,z)$. Find the heat production $H$, in nW/m³ (1 nW = $10^{-9}$ W).", "expected": "47*10^12/(4/3*pi*6371000^3)*10^9", "units": "nW/m³", "kind": "number", "tolerance": 1e-05, "hints": ["div q = H, so the Divergence Theorem gives H times Earth’s volume = 47 TW.", "Earth’s volume is (4/3)πR³ with R in meters; then convert W/m³ to nW/m³."], "id": "w10-p5-b", "label": "b"}, {"prompt": "Apply the Divergence Theorem to a column of continental crust to find the mantle heat flux $q_m$ entering the bottom of the crust, in mW/m².", "expected": "73-25*(1-exp(-3.5))", "units": "mW/m²", "kind": "number", "tolerance": 1e-05, "hints": ["Take a column of top area A. Only the top (outward flux 73A) and the bottom (outward flux −q_m A) carry heat.", "The volume integral is A times the integral of 2.5e^(z/10) dz from −35 to 0; note that 2.5 microwatts per m³ times 10 km is 25 mW/m²."], "id": "w10-p5-c", "label": "c"}], "solution": ["Average flux: on the sphere the outward normal is $\\mathbf n=\\mathbf r/R$, and $\\iint\\mathbf q\\cdot\\mathbf n\\,dS=47$ TW. Dividing by the area $4\\pi R^2=5.10\\times10^{14}$ m$^2$ gives an average of $92.15$ mW/m$^2$.", "Uniform production: $\\nabla\\cdot\\big(\\tfrac H3(x,y,z)\\big)=H$. Directly, $\\mathbf q\\cdot\\mathbf n=\\tfrac H3R$ on the sphere, so the flux is $\\tfrac H3R\\cdot4\\pi R^2=H\\cdot\\tfrac43\\pi R^3$, which checks the Divergence Theorem. Setting it equal to $47$ TW gives $H=47\\times10^{12}/(1.083\\times10^{21})\\approx4.34\\times10^{-8}$ W/m$^3=43.39$ nW/m$^3$.", "Crustal column: take $[0,a]\\times[0,a]\\times[-35,0]$ km with $\\mathbf q=(0,0,q(z))$ and top area $A=a^2$. The four sides have horizontal normals, so $\\mathbf q\\cdot\\mathbf n=0$ there. The top has $\\mathbf n=\\mathbf k$ and flux $73A$; the bottom has outward $\\mathbf n=-\\mathbf k$ and flux $-q_mA$. Since $\\nabla\\cdot\\mathbf q=q^\\prime(z)=H(z)$, \\[(73-q_m)A=A\\int_{-35}^0 2.5e^{z/10}\\,dz\\ \\ (\\mu\\text{W/m}^3\\cdot\\text{km})=25(1-e^{-3.5})A\\text{ mW/m}^2,\\] so $q_m=73-24.25\\approx48.75$ mW/m$^2$.", "Interpretation: the crust near the surface produces about $2.5\\ \\mu$W/m$^3$, roughly 60 times the whole-Earth average $H\\approx0.043\\ \\mu$W/m$^3$ from (b). So heat-producing elements are strongly concentrated in the continental crust. In this model the crust itself supplies about a third of the 73 mW/m$^2$ flowing out of a continent."], "reflection": "In the crustal column, suppose you had used the upward normal on the bottom face by mistake. What mantle heat flux would you have reported, and how could you tell it was wrong?", "extension": true, "id": "w10-p5", "discussionSolution": "You would report $q_m\\approx-48.75$ mW/m$^2$, and the minus sign gives the error away. With the upward normal the bottom term becomes $+q_mA$, so $73+q_m=24.25$. A negative $q_m$ would mean heat flowing down into the mantle, but heat flows upward out of the hot interior. With the correct outward (downward) normal, the bottom flux is $-q_mA$, negative because heat enters there.", "modelSpec": {"data": ["Total heat flow out of Earth: $47\\pm2$ TW", "Continents: $13.8$ TW, mean $73$ mW/m$^2$", "Earth’s mean radius $R=6371$ km"], "assume": ["Steady state: the heat flux does not change with time.", "Thought experiment: heat is produced uniformly throughout the whole Earth.", "Continental crust is $35$ km thick, with heat production $H(z)=2.5\\,e^{z/10}\\ \\mu$W/m$^3$ ($z$ in km, $-35\\le z\\le0$).", "In the crust, heat flows only vertically."], "model": ["Divergence Theorem: $\\iint_{\\partial W}\\mathbf q\\cdot\\mathbf n\\,dS=\\iiint_W\\nabla\\cdot\\mathbf q\\,dV$, where $\\mathbf q$ is the heat flux (W/m$^2$) and $\\nabla\\cdot\\mathbf q$ is the heat production (W/m$^3$)", "Whole Earth (thought experiment): $\\mathbf q=\\tfrac H3(x,y,z)$ on the ball of radius $R$", "Crust: $\\mathbf q=(0,0,q(z))$ with $q^\\prime(z)=H(z)$, surface value $q(0)=73$ mW/m$^2$, mantle input $q(-35)=q_m$"]}, "figure": {"alt": "Left: Earth with arrows pointing outward all around its surface. Right: a column of continental crust, 35 km thick, with arrows for heat entering the bottom from the mantle and leaving the top at 73 mW per square meter", "caption": "Left: heat leaving Earth through its surface. Right: the crustal column, with heat leaving its top at 73 mW/m² and the unknown mantle flux $q_m$ entering its bottom.", "file": "w10-p5"}}]}]};
